window.FS_DATA=window.FS_DATA||{};FS_DATA["sinaksari_07"]={"month":7,"name":"Korrik","days":[{"d":1,"m":7,"blocks":[{"t":"intro","x":"Më 1 të këtij muaji, nderojmë kujtimin e Anargjendëve të shenjtë Kozma dhe Damian romanë, që u martirizuan në Romë në vitin 283."},{"t":"li","x":"Kujtimin e 25 000 dëshmorëve, të cilët u dogjën në Nikomedi të Azisë së Vogël në shekullin e 3-të."},{"t":"li","x":"Kujtimin e 2 000 martirëve që mbaruan me shpatë."},{"t":"li","x":"Kujtimin e dëshmorëve Konstandini alamani bashkë me grupin e tij nga Qiproja."},{"t":"li","x":"Kujtimin e dëshmorit Mavriku."},{"t":"li","x":"Kujtimin e oshënarit Petro i Evandrit nga Konstandinopoja; fjeti në vitin 854."},{"t":"li","x":"Kujtimin e oshënarit Leoni, murg i shkretëtirës, i cili jetonte i zhveshur."},{"t":"li","x":"Kujtimin e oshënarit Vasili, i cili organizoi Manastirin Vathi Riaki në Triglia të Azisë së Vogël në shekullin e 10."},{"t":"li","x":"Kujtimin e transferimit të lipsanit të oshënarit Joani në Rila, afër kryeqytetit të Bullgarisë në vitin 1469."},{"t":"li","x":"Kujtimin e shën Angjelinës, mbretëresha e Serbisë në shekullin e 16."},{"t":"li","x":"Kujtimin e atit të shenjtë Leonti i Radaucit, nderimi u bë zyrtar nga Patriarkana e Rumanisë në qershor të 1992."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Kozma dhe Damian, anargjendë"},{"t":"p","x":"Kemi tre çifte shënjtorësh, vëllezër që mbartin të njënjtat emra. Që të gjashtë ishin mjekë dhe shëronin nëpërmjet shkencës, por më tepër nëpërmjet forcës së Krishtit, pothuajse çdo sëmundje njërëzore, por edhe kafshësh. Prandaj nderohen si mbrojtës të mjekëve. Mrekullitë që bënin pa marrë para (pa argjend), i jepnin besueshmëri predikimit të tyre për për-hapjen e Krishterimit. Fama e tyre u përhap shpej kudo, ndër-sa mrekullitë pasuan edhe mbas vdekjes së tyre."},{"t":"p","x":"Dyshja e parë (1 korrik) ishin romakë. Disa idhujtarë cmirëzinj shpifën kundër tyre tek perandor Karini (283-285), se mrekullitë që ata bënin ishin rezultat i magjisë. Shkuan te mbreti pa i ftuar, që siç i kërcënonte iu kthye qafa mbrapsht! Shenjtët e shëruan, pra u bë i krishterë, si dhe shumë të tjerë. Por mësuesi i tyre në mjekësi i kishte smirë, prandaj pasi komplotoi me nxënësit e tij, i ngjitën në mal gjoja për të mbledhur barëra. Atje i vranë duke i goditur me gurë."},{"t":"p","x":"Dyshja e dytë ishin arabë dhe kishin edhe vëllezër të tjerë, Leontin, Anthimin, Efprepin (ose Eftropin) që i festojnë bashkë me Kozmain dhe Damianin (17 tetor). Në kohën e Dioklitianit (284-305) idhujtarët e Kilikisë, në juglindje të Azisë së Vogël, i rrahën të gjithë, i hodhën në det të lidhur me gurë dhe pastaj në furrë. Meqenëse ata shpëtonin në mënyrë të mbinatyrshme i mbërthyen në kryqe dhe iu prenë kokat. Anargjendët (anargjirët) e fundit (1 nëntor) ishin me origjinë nga Azia. U edukuan me shpresëtari nga prindërit e tyre dhe në veçanti nga e ëma e tyre, shën Theodhota (2 janar), që ngeli herët e ve. Pas fjetjes së saj vepruan me frytshmëri dhe u prehën në paqe."}]},{"d":2,"m":7,"blocks":[{"t":"intro","x":"Më 2 të këtij muaji, nderojmë kujtimin e Vendosjes së Rrobës së shën Marisë në Kishën e Vllahernës në Konstandinopojë në vitin 458."},{"t":"li","x":"Kujtimin e dëshmorit Kointi."},{"t":"li","x":"Kujtimin e atit tonë Juvenali, patriark i Jerusalemit në vitet 422-458."},{"t":"li","x":"Kujtimin e shën Pavlit, Vilonit, Theonit dhe Heronit, të cilët u martirizuan në Selanik."},{"t":"li","x":"Kujtimin e shën Fotit, mitropolit i Moskës."},{"t":"li","x":"Kujtimin e dëshmorëve të rinj Theodhori, Llambri, Theodhori, Gjergji dhe Joani, të cilët u martirizuan në ishullin Samothraki të Greqisë në vitin 1835."},{"t":"li","x":"Kujtimin e shën Stefanit të madh, në Moldavi."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Vendosja e rrobës se Nënës së Zotit në Vllahernë"},{"t":"p","x":"Në kohën e perandorit Leon i I-rë e të gruas së tij Verina (457- 474), dy vëllezër fisnikë, Galbio e Kandidi, pasi hoqën dorë nga herezia ariane vendosën të ndërmarrin një pelegrinazh në Tokën e Shenjtë. Me të mbërritur në Galile, bënë një ndalesë në shtëpinë e Anës, një grua e moshuar jude, por e perëndishme dhe e virtytshme, e cila lutej natë e ditë duke imituar kështu Anën, bijën e Fanuelit (Luk. 2:36). Pelegrinët fisnikë vunë re se të krishterët sillnin qirinj dhe temjan në pjesën më të brendshme të shtëpisë dhe se një numër i madh të sëmurësh e të paralizuarish kalonin natën atje, ndaj dhe i kërkuan zonjës së shtëpisë t’u tregonte arsyen. Ana, duke dëshmuar se hiri i Perëndisë kryente mrekulli të shumta, tregoi fillimisht se atje ndodhej një kostum i vjetër i të lashtëve. Por ndërsa iu lutën që t’u tregonte më shumë, ajo u zbuloi përfundimisht se Rroba e Nënës së Zotit gjendej atje, që kur e Tërëshenjta në çastin e Fjetjes ia kishte dhënë një nga shërbyeseve të saj jude. Kjo rrobë ishte ruajtur brez pas brezi nga një virgjëreshë. Vëllezërit përfituan nga gjumi i të sëmurëve të pranishëm dhe morën masat e kutisë së drurit, e cila mbante veshjen e shenjtë, e prej andej u nisën për në Jerusalem. I premtuan zonjës së shtëpisë se do të ktheheshin ta përshëndesnin në rrugën e kthimit. Pasi nderuan varret e qytetit të shenjtë, ata ndërtuan një kuti të ngjashme me kutinë që mbante rrobën e Hyjlindëses dhe kur u kthyen tek gruaja e virtytshme gjetën mënyrën dhe e zëvendësuan kutinë bosh mbuluar me një shtresë ari. Kur mbërritën në Konstandinopojë e vendosën këtë thesar të çmuar në një vend të quajtur Vllahernë, në pjesën veriperëndimore të qytetit, jashtë mureve, ku dhe ndërtuan një kishë për nder të apostujve të shenjtë Petro e Mark, me qëllim që të ruanin sendin e shenjtë. Por nuk mund ta fshihnin për një kohë të gjatë këtë thesar, për shkak të mrekullive që kryheshin në kishë. Pasi i thanë perandorit se kishin sjellë këtë trofe të çmuar nga pelegrinazhi i tyre për mbrojtjen e qytetit, ky plot gëzim ndërtoi një kishë ku vendosi kutinë ku ishte rroba e Hyjlindëses. Më pas kjo kuti u zëvendësua nga një kuti ari e argjendi zbukuruar me gurë të çmuar. Rroba e shenjtë ishte një copë e tërë e purpurt mbretërore, e punuar me lesh të dobët njëngjyrësh. Mbeti e paprekur gjatë gjithë kohës duke treguar në mënyrë të qartë mrekullinë e virgjërisë së përhershme të Nënës së Perëndisë."},{"t":"h","x":"Juvenali i Jerusalemit"},{"t":"p","x":"Kryehirësoi në vitet 422-458, periudhë e oshënarëve të famshëm palestinezë. U mor me problemet dogmatike dhe u përpoq që të ishte i pavarur nga mitropoliti i Qesarisë (të Palestinës), nën juridiksionin e të cilit ishte deri atëherë Jerusalemi. Pra, dorëzonte episkopë edhe jashtë Palestinës, si psh. një anëtar të fisit të sarakinëve si baritor të bashkatdhetarëve të tij."},{"t":"p","x":"Megjithëse zotëronte një post të lartë në Sinodin III Ekumenik, në Efes (431), në sinodin Listrik të Efesit (449) u bashkua me monofizitët, të cilët i luftoi në Sinodin IV Ekumenik, në Kalkidoni (451). Në të njëjtin Sinod ra dakord me episkopin e Antiokisë, i cili ankohej sepse zona të tij i ishin dhënë episkopit të Jerusalemit nga mbreti, shën Theo-dhosi II (29 korrik). Zonat iu kthyen, por Palestina iu dha kryebariut të Jerusalemit që u njoh tashmë patrik, i katërti në radhë të patrikëve të Lindjes. Duke u kthyer, për pak desh u vra prej murgjish monofizitë për arsye të kthimit të tij në besimin orthodhoks. Për këtë arsye shkoi në Konstandino-pojë, ndërsa në vend të tij u bë patrik ai që kurdisi kryengritjen kundër tij. Këtë të fundit e mbështeti edhe ish - perandoresha, shën Evdhokia (13 gusht), e cila banonte në qytetin e shenjtë. Perandori, shën Markiani (17 shkurt) rivendosi në fron më 453 shenjtin, me të cilin u pajtua Evdhokia. Më parë ajo u kthye në Orthodhoksi sipas sugjerimit të Efthimit të Madh (20 janar), mikut të Juvenalit."},{"t":"p","x":"Patriku thirri një sinod orthodhoks në selinë e tij. Atëherë episkopi i Romës, shën Leoni (18 shkurt) i cili e kishte ndër-prerë nga komunikimi kishtar, e njohu përsëri (454)."},{"t":"p","x":"Juvenali ndërtoi kishën e shën Stefanit në vendin e marti-rizimit të tij, të cilën mbas një ftese e përuroi më 438 ( ose 439) shën Kirilli i Aleksandrisë (18 janar). Ai caktoi të festohen dhe në Jerusalem Krishtlindjet më 25 dhjetor, veç nga Theofania. Gjithashtu dërgoi në Vlahernë të Konstan-dinopojës, në kishën e sapondërtuar të Markianit, arkivolin dhe pëlhurat e Hyjlindëses. Fjeti më 458."}]},{"d":3,"m":7,"blocks":[{"t":"intro","x":"Më 3 të këtij muaji, nderojmë kujtimin e dëshmorit Jakinthi Kubikulari, i cili u martirizua në Romë ndërmjet viteve 98-117."},{"t":"li","x":"Kujtimin e dëshmorëve Theodhoti, Theodhota grua, Golindhuku, Dhiomidhi, Evlambi, Asklipiadi."},{"t":"li","x":"Kujtimin e dëshmorëve Marku dhe Mokiu."},{"t":"li","x":"Kujtimin e atit tonë Anatoli, patriark i Konstandinopojës (449-458), i cili mori pjesë në Sinodin e Katërt Ekumenik (431)."},{"t":"li","x":"Kujtimin e oshënarit Anatoli i Mbylluri nga Lavra e Kievit të Rusisë në shekullin e 12."},{"t":"li","x":"Kujtimin e oshënarit Joan i marrë më Krishtin në Moskë të Rusisë në vitin 1589."},{"t":"li","x":"Kujtimin e oshënarit dhe dëshmorit të ri Gjerasimi, i cili u martirizua në Konstandinopojë në vitin 1812."},{"t":"li","x":"Kujtimin e atit të shenjtë Isai anakoreti."},{"t":"li","x":"Kujtimin e atit të shenjtë Joakimi nga Manastiri i Notenës në Akai."},{"t":"li","x":"Kujtimi princave të shenjtë Vasili dhe Konstandini të Iaroslavit."},{"t":"li","x":"Kujtimin e atit të shenjtë Nikodhimi nga liqeni i Kojës."},{"t":"li","x":"Kujtimin e shën Joanit dhe Longinit, çudibërës në Solovsk."},{"t":"li","x":"Kujtimin e transferimit të lipsaneve të shën Filipit, mitropolit i Moskës më 1652."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Jakinthi, martir"},{"t":"p","x":"I lindur në Qesari të Kapadhoqisë nga prindër të krishterë, ishte në Romë “kubikular” d.m.th. kujdestar i dhomës dhe kamerier i tavolinës së perandor Trajanit (98-117)."},{"t":"p","x":"Dikur e denoncuan tek perandori, i cili e thirri në drekë dhe i bëri presion që të hajë mish flijimesh. Pasi bëri kryqin, mohoi në mënyrë kategorike që të ndryshojë besim dhe të hajë atë ushqim të molepsur. Përkundrazi, i sugjeroi që edhe ai të besojë!"},{"t":"p","x":"Monarku i egërsuar urdhëroi që ta godisnin në gojë. Shenjtin e hodhën përtokë dhe e godisnin me shqelma, i hapën gojën dhe ia mbushën me mish flijimesh, por nuk e hëngri. Më pas e burgosën me këmbë të shtrënguara në “drurin” torturues."},{"t":"p","x":"Ditën e nesërme e sollën në festën e perëndive në teatër. Nuk sakrifikoi dhe xhelatët e rrahën aq sa u spërkatën me gjak. Pastaj e varën dhe i shqyen brinjët, por ai për çudi të shikuesve priste ndëshkime edhe më të mëdha, të cilat i quante bamirësi! Më pas u burgos dhe nuk hëngri gjë e as piu, sepse i jepnin vetëm mish idhulli. Ditën e 38 të, roja i burgut pa i tmerruar një engjëll që t’i mbulonte trupin dhe një tjetër që e kurorëzonte. Trajani, megjithë këto, nuk tërhiqej, derisa mbas dy ditësh dëshmori 20-vjeçar mbaroi. Atëherë u shfaqën shumë qenie të veshura me të bardha, që mbanin llambadha dhe i qarkuan trupin. Tirani urdhëroi dhe e hodhën në mal te bishat, por ato nuk e prekën sepse e ruanin engjëjt. Një prift, i udhëzuar prej një engjëlli, gjeti trupin e tij dhe e varrosi. Kur po vdiste, ia bëri të njohur çështjen një plake shpresëtare të ve që e mori lipsanin e tij, i cili binte erë të mrekullueshme."},{"t":"p","x":"Më vonë shenjti iu shfaq një senatori të verbër. E këshilloi ta marrë lipsanin e shenjtë nga plaka dhe ta dërgojë në Kapadhoqi, në qoftë se donte të shërohej. Arkondi u lye me vajin e kandilit të lipsanit të nderuar dhe u shërua, por mbajti qëndrim indiferent për të tjerat. Filloi të verbohej sërish derisa erdhi në vete, u shërua përsëri dhe e dërgoi lipsanin në shtëpi të atletit (dëshmorit), në Qesari."},{"t":"p","x":"Jakinthi, greqisht do të thotë zymbyl ose sapfir."}]},{"d":4,"m":7,"blocks":[{"t":"intro","x":"Më 4 të këtij muaji, nderojmë kujtimin e atit tonë Andrea, kryepiskop i Kretës (711-740), shkrimtar i Kanunit të Madh të Pendimit dhe veprave të tjera. Fjeti në vitin 740."},{"t":"li","x":"Kujtimin e dëshmorëve Theodhori, episkop i Kirinit në Libi, dëshmoret gra Kiprila, Aroa dhe Lukia, të cilët u martirizuan me shpatë në vitet 284- 305."},{"t":"li","x":"Kujtimin e dëshmorit Theodhoti."},{"t":"li","x":"Kujtimin e hierodëshmorit Theofili."},{"t":"li","x":"Kujtimin e oshënares Asklipia çudibërëse."},{"t":"li","x":"Kujtimin e oshënarit Menigni."},{"t":"li","x":"Kujtimin e atit tonë Donati, episkop në Libi të Afrikës së Veriut."},{"t":"li","x":"Kujtimin e oshënares Marta, nëna e shën Simeon Stilitit."},{"t":"li","x":"Kujtimin e shën Mihail Honiatit, mitropolit i Athinës."},{"t":"li","x":"Kujtimin e apostujve Kirili dhe Metodi, ndriçues të sllavëve bashkë me nxënësit e tyre: Klimi, Sava, Angjelari, Gorazdi dhe Naumi, në shekullin e 9."},{"t":"li","x":"Kujtimin e shën Andreas, princ i Bogoliubovit në Rusi, në vitin 1174."},{"t":"li","x":"Kujtimin e atit të nderuar Andrea Rublev."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Andrea i KretësJ"},{"t":"p","x":"Hinomograf shumë i shquar, i quajtur gjithashtu “jerusalemas”. Lindi ndoshta më 660, në Damask, prej prindërish të thjeshtë por shpresëtarë, Gjergji dhe Grigoria. Për herë të parë foli në moshën 8 - vjeçare, me mrekulli."},{"t":"p","x":"15 vjeç u rreshtua në Manastirin e Shën Savës (afër Jerusalemit), ku u arsimua në theologji, muzikë, retorikë, filozofi, u qeth murg dhe veproi si sekretar patriarkal. Megji-thëse i ri, u dërgua me dy jerontë në një mision zyrtar, drejtuar perandorit në Konstandinopojë (685). Qëndroi në kryeqytet, u dorëzua dhjak në Kishën e Shën Sofisë dhe mori përsipër drejtimin e një jetimoreje dhe të një institucioni tjetër filantropik."},{"t":"p","x":"Më 712 (ose më parë) e zgjodhën kryepiskop të dymbë-dhjetë episkopatave të ishullit të Kretës, me seli kryeqytetin e saj, Gortina. Intelektual por edhe praktik, aktivizoi edhe këtu aftësitë e tij të pasura. Mësoi popullin, shkroi, ndërtoi kisha dhe shtëpi për të varfrit, të sëmurët dhe të huajt dhe organizoi Kishën. I njohim mrekullitë e tij në kohë thatësire dhe epidemie. Gjithashtu i dha zemër grigjës së tij, saqë zmbrapsën agresorin arab."},{"t":"p","x":"Luftoi për mbrojtjen e ikonave, por ashtu si miku i tij, shën Gjermanoi, më pas kryepiskop i Konstandinopojës (12 maj), u ndikua (712) për një kohë prej Monotelitizmit, degë-zim i Monofizitizmit. Por pastaj u pendua."},{"t":"p","x":"I moshuar udhëtoi në kryeqytet ku u admirua retorika e tij. Duke u kthyer u lodh nga lundrimi dhe ndërroi jetë në ishullin e Mitilinit - siç e kishte parashikuarnë verilindje të detit Egje. Atje e varrosën (rreth vitit 740)."},{"t":"p","x":"Fjalimet e tij, festive zakonisht, lavdërojnë sidomos festat Hyjlindësore; veprat e tij himnografike përfshijnë muzikë “melos” dhe poezi “ode”, pra melodi, himnodi e “kanuneve” të shumtë, “idiomeleve” dhe “stikirareve”, madje më të shumtit e konsiderojnë si babain e “kanuneve”. “Kanuni i Madh” i tij shumë i famshëm (261 tropare) shfaq ashtu si gjithë krijimtaria e tij, njohuri të thella të Dhiatës së Vjetër dhe të Re. Njëkohësisht zbulon bollëk ndjenjash të njeriut që ngacmohet nga djalli. Pasuria letrare përfundon me thirrjen për pendim."},{"t":"p","x":"Andrea, greqisht = burrëror."},{"t":"p","x":"Kiril dhe Metod dhe nxënësit e tyre Gorazhdi, Klimi, Naumi, Angjellari dhe Sava B Në kultin e \"Shtatë Shenjtorëve\" bëjnë pjesë shenjtorët Kiril dhe Metod dhe nxënësit e tyre Gorazhdi, Klimi, Naumi, Angjellari dhe Sava. Nuk kemi saktësi në përcaktimin se si u krijua tradita e kultit të shtatë shenjtorëve. Ata i përmend vetëm Teofilakti në jetëshkrimin e shenjtorit Klement të Ohrit. Në të thuhet se Angjellari së bashku me Naumin dhe Klimin shkuan në Bullgari, ku edhe mbylli sytë pas përndjekjeve nga kleri francez. Ndërsa Gorazhdi vazhdoi veprën e mësuesve të tij duke luftuar kundër ithtarëve frëng të Filioque-s. Vite më vonë Gorazhdi e vazhdoi veprimtarinë e tij në Berat të Shqipërisë ku edhe u martirizua. Në katedralen e Shën Marisë në Berat ndodhen ende lipsanët e tij dhe të Angjellarit. Gjithashtu një ikonë e kësaj kishe paraqet fjetjen e shenjtorëve. Ekziston edhe një shërbesë e shkruar në greqisht për nder të shtatë shenjtorëve. Nga kjo akoluthi ruhet vetëm një kopje, e cila është shtupur në Venedik me shpenzimet e zotërinjve Andrea Papa, Joan Papa dhe të bijve të tij, Nikollës dhe Anastasit. Në shërbesë bëhet fjalë për nderimin e Angjellarit dhe gorazhdit në zonën e Beratit. Akoluthia shpesh përmend lipsanet e tyre të shenjta: \"Grumbulli me lipsanat e Shtatë shenjtorëve, burim jetëdhënës për besimtarët..\". masa e besimtarëve i shpalli mbrojtës të qytetit, prandaj u hartua edhe akoluthia për nder të shtatë shenjtorëve. Ky tekst që u shkrua për nder të shenjtorëve Kiril dhe Metod si dhe nxënësit e tyre, i përket një tradite Ballkanike dhe u drejtohej besimtarëve të episkopatës së Ohrit."}]},{"d":5,"m":7,"blocks":[{"t":"intro","x":"Më 5 të këtij muaji, nderojmë kujtimin e atit tonë të madh, shën Athanas athoniti, themelues i Manastirit të Lavrës së Madhe në Malin e Shenjtë, fjeti në vitin 1000."},{"t":"li","x":"Kujtimin e oshënarit Lambadh çudibërësi."},{"t":"li","x":"Kujtimin e shën Vasilit dhe 70 shokëve të tij që mbaruan nga shpata në Skithopol."},{"t":"li","x":"Kujtimin e atit tonë Stefani, mitropolit në Rigjion të Italisë."},{"t":"li","x":"Kujtimin e oshënarëve Athanasi dhe Theodhosi nga Kerepoveski, nxënës të shën Sergjit në Radonezh."},{"t":"li","x":"Kujtimin e oshënarit dhe dëshmorit të ri Qipriani, i cili ishte murg në Manastirin e Kutlumusiut të Malit të Shenjtë dhe u martirizua në Konstandinopojë në vitin 1679."},{"t":"li","x":"Kujtimin e gjetjes së lipsaneve të shën Sergjit në Radonezh."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Athanas athoniti dhe gjashtë nxënësit e tij"},{"t":"p","x":"Eshtë patriku i murgjërisë së Malit të Shënjtë. Lindi në Trapezuntë, në bregdetin jugor të Detit të Zi rreth 930, jetim nga i ati (që rridhte prej Antiokisë). Që foshnjë humbi nënën dhe në moshën 7 - vjeçare kujdestaren, një murgeshë e shenjtëruar. Një i afërm i familjes dhe një tjetër i afërm, gjeneral, e morën nën kujdestari. Në lojëra e bënin igumen."},{"t":"p","x":"I mprehtë, i ditur, i shenjtë, mësues me famë në Konstan-dinopojë, u magjeps nga oshënar Mihail Maleini (12 korrik), xhaxhai i gjeneralit Niqifor Foka dhe igumen i malit Kimina të Vithinisë në veriperënim të Azisë së Vogël. Atje qethet murg me emrin Athanas, ndërsa më parë quhej Avramiu dhe u lidh me Fokanë, mikun e monakizmit."},{"t":"p","x":"Meqë e nderonin shumë, u arratis në Athos ku u paraqit si një i pashkollë. Gjenerali urdhëroi dhe e zbuluan. Athonitët, që atëherë asketonin nëpër kasolle, e vunë si ndërmjetues dhe u ndërtua kisha e shkëlqyer e Protatit, e cila zbukuron Malin e Shenjtë."},{"t":"p","x":"Më pas u bë eremit në vendin ku ndodhet Lavra e Madhe mahnitëse e tij. Demonët e luftuan për tërë vitin, por ndërsa do të ikte një çudi i dëboi. I jepte kurajo edhe e Tërëshënjta, duke iu çfaqur herë pas here."},{"t":"p","x":"Fokai e mori në inkursionin e Kretës për t’u lutur, derisa arabët u mundën (961). Menjëherë formon manastirin e parë të Athosit me paratë e Niqifor Fokait, për të murgëruar së bashku. Por mëson se ai u bë mbret, i shkruan me qortim dhe zhduket. Fokai pendohet, e kërkon dhe e gjen në Qipro, atëherë oshënari kthehet në Athos."},{"t":"p","x":"Më vonë shkon në kryeqytet. Perandori i dërrmuar shpirtërisht i premton përsëri se do të bëhet murg dhe financon përsëri ndërtimin. Në punë e sipër oshënarit i thyhet kavilja dhe dergjet duke vuajtur në shtrat për tre vjet, ndërsa merret me kaligrafi."},{"t":"p","x":"Perandor Fokai vritet dhe disa athonitë, që më pas u pe-nduan, e denoncojnë shenjtin tek pasardhësi i tij, Joan Cimiski (969-976) si revizionist (ithtar). Perandori i ri e thërret në apologji, por i bëri përshtypje dhe jep para për veprimtarinë. Gjithashtu më 972 bën të pranueshëm “Cjapin”, lëkurën e cja-pit, mbi të cilën u shkrua “Tipikoja” (rregullorja) e parë e Athosit."},{"t":"p","x":"Mrekullibërësi, rilindësi i murgjërisë, u vra së bashku me gjashtë prej bindësve të tij të shumtë në aksident, siç e kishte paranjohur kur ndërtohej kisha e Lavrës, brenda së cilës është i varrosur."},{"t":"p","x":"Më 1963 u festua mijëvjeçari i Lavrës dhe i Malit në përgjithësi."}]},{"d":6,"m":7,"blocks":[{"t":"intro","x":"Më 6 të këtij muaji, nderojmë kujtimin e oshënarit Sisoi i Madh nga Egjipti në shekullin e 4-t."},{"t":"li","x":"Kujtimin e dëshmorëve Filemoni, Arkipi dhe Onesimi."},{"t":"li","x":"Kujtimin e dëshmorëve Luçia virgjëreshë bashkë me ata që besuan tek Krishti përmes saj: Riksi shërbëtor i prefektit të Romës, Anatoli, Antonini, Luki, Nei, Serini, Diodori, Dioni, Apolloni, Apami, Papiani, Koti, Oroni, Papiku, Satiri, Viktori dhe 9 të tjerë, të cilët u martirizuan në Kambania të Italisë."},{"t":"li","x":"Kujtimin e atit tonë Asti, episkop i Durrëst ndërmjet viteve 98-117."},{"t":"li","x":"Kujtimin e dëshmorit Apolon, mbaroi në një varkë që e kishin lënë në mes të detit pasi ia kishin vënë zjarrin."},{"t":"li","x":"Kujtimin e martirit të shenjtë Aleksandër, të cilin e lishën në një rrotë dhe e lëshuan nga një mal."},{"t":"li","x":"Kujtimin e martirit të shenjtë Epimaku, i cili mbaroi me shpatë."},{"t":"li","x":"Kujtimin e martirit të ri Kirili i Selanikut."},{"t":"li","x":"Kujtimin e gjetjes së lipsanit të virgjëreshës Juliana, e cila prehej në Lavrën e Shpellave të Kievit në shekullin e 16."},{"t":"li","x":"Kujtimin e oshënarit Sisoi nga Lavra e Kievit në shekullin e 18."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Asti, hieromartir"},{"t":"p","x":"Episkop i Durrësit. Emri i tij greqisht do të thotë qytetar (në kundërshtim me fshatar)."},{"t":"p","x":"E zunë në kohën e Trajanit (98-117), nga të parët e Durrë-sit dhe pasi nuk ra dakord që të sakrifikojë, e çuan tek qeveritari. E rrahën me doreza plumbi dhe kamxhikë, por nuk e mohoi besimin e tij. E lyen pra me mjaltë, e kryqëzuan në dru - sipas një tradite tjetër, e ngjeshën - dhe në vapën e verës e vunë afër mureve, përkundrejt diellit përvëlues."},{"t":"p","x":"Mbaroi nga pickimet e grerëzave, bletëve dhe insekteve të tjera, u varros në mënyrë modeste nga të krishterët, të cilët i ngritën kishë."},{"t":"p","x":"Vdekja e lavdishme e tij u bë shkak i martirizimit të martirëve Peregrinit, Lukianit, Pompeut, Isikiut, Papiut, Satorninit dhe Gjermanit (festohen nesër)."},{"t":"p","x":"Duke ikur d.m.th. nga përndjekja e pamëshirshme që ndodhte në atdheun e tyre Itali, kaluan me anije në Durrës, ndërkaq duke parë shën Astin të vuajë heroikisht për Zotin, e lumëruan, kështu që u ndaluan. Kur shprehën haptazi bin-djen e tyre për hyjninë e Jisuit, tirani dha urdhër dhe i mbytën duke i zhytur ata atje, në detin Adriatik."},{"t":"p","x":"Mbas shtatëdhjetë (apo nëntëdhjetë) vjetësh iu shfaqën kryepiskopit të Aleksandrisë. Ky gjeti lipsanet e çmuara të tyre të futura në rërën - e brigjeve egjiptiane, siç duket - ku i kishin nxjerrë që në fillim dallgët. I varrosi me nder dhe iu ndërtoi një kishë të vogël."},{"t":"p","x":"Matërial më i zgjeruar për shën Astin"},{"t":"h","x":"Hierodëshmor Asti"},{"t":"p","x":"Asti ishte Episkop i Durrësit në vitin 98 pas Krishtit (emri tij do të thotë “qytetar” ose “i qytetit”). Ai ishte një Barí i vërtetë, shembull i gjallë i një jete të krishterë aktive për besimtarët e tij, një veprimtar i zellshëm për përhapjen e Ungjillit. Me hipjen në fron si Perandor i Romës (98-117) Trajani përtëriti dekretin e persekutimit të krishterëve në të gjithë Perandorinë Romake. Kështu Asti arrestohet nga paria e qytetit Numeriu, Nearku, Aglaidhi dhe Ariani dhe pasi nuk pranoi t’i bëjë therore idhujve, e dorëzojnë tek qeveritari Agrikola. Ky u përpoq që në fillim t’i ndryshonte mendjen dhe të mohonte Krishtin e më pas me kërcënime, por pa rezultat. Si një kryefetar i denjë i foli Agrikolës se nuk vlente ai pushtet që përdor forcën e tij për të bërë keq. Qeveritari i tërbuar nga qendrimi i Astit mendoi të hakmerrej djallzisht. E torturuan, duke e rrahur me kamzhikë prej lëkure kau të pajisur me sfera plumbi, por ai përsëri ngulmoi në besimin tij te Krishti, duke mos e mohuar Atë. E më pas, e lyen me mjaltë dhe e kryqëzuan mbi dru, pranë mureve të qytetit, ku dhe i pickuar nga grenxat dhe insektet e tjera dha shpirtin e tij në duart e Perëndisë dhe i lumur mori kurorën e martirizimit. Ishte kohë vere dhe dielli përvëlonte. Lipsanin e Shën Astit e morën të krishterët dhe e varrosën duke ngritur edhe një kishë mbi të."},{"t":"p","x":"Po atë ditë me shën Astin dhanë jetën e tyre si dëshmorë të Krishtit dhe 7 besimtarë të tjerë që quheshin: Peregrini, Lukiani (Luçiani), Pompeu, Hisiki, Papia, Saturnini, Gjermani, të gjithë nga Italia. Meqënëse atje ata përndiqeshin, erdhën me një anije në Durrës, për të shpëtuar. Këtu duke parë shën Astin, episkopin e Durrësit, të varur në kryq, të lyer me mjaltë dhe të pickuar nga grenxat dhe insektet, për besimin e Krishtit filluan ta lumëronin atë dhe t’i thurnin lavde e për këtë ata u arrestuan. Këta deklaruan se ishin të krishterë. Qeveritari i tërbuar nga vendosmëria e Astit dhe i befasuar nga vendosmëria që të 7 këta pohuan se ishin të krishterë urdhëroi dhe i mbytën në detin Adriatik, kështu të lumurit morën kurorën e pavyshkur të martirizimit. Mbas 70 vjetësh dëshmorët iu shfaqën Kryepiskopit të Aleksandrisë. Ky i gjeti lipsanet e çmuara të tyre të futura në rërë, i mori e i varrosi me nderim dhe iu ndërtoi një kishë të vogël për nder të tyre."},{"t":"p","x":"Për hierodëshmor Astin janë hartuar dy shërbesa kishtare me himne, të cilat këndoheshin ditën kur populli e kremtonte bashkëqytetarin e tyre. Shërbesa e parë ka qenë hartuar nga Josifi Himnografi i shekullit të IX, ku një kopje e saj ruhet në një dorëshkrim, në Bibliotekën e Parisit në kodikun greqisht 13, f.330a dhe 1575, f.145b. Shërbesa e dytë është hartuar në vitin 1918 me titull “Shërbesë e kënduar e Shenjtit, hierodëshmor të lavdëruar Astit, Episkop i Durrësit, hartuar nga Mitropoliti i Durrësit, Gorëmokrës dhe Shpatit, Jakovi, dhe e miratuar nga Kisha e Madhe e Krishtit shtypur me shpenzimet e të nderuarit Mihail Thoma Truja nga paria e Durrësit. Në Konstandinopojë, 1918”. Kjo shërbesë u miratua nga Sinodi i Patriarkanës Ekumenike të Konstandinopojës më 30 korrik 1918 dhe mban nënshkrimin e Patriarkut Gjermani. Deri tani asnjë nga shërbesat e tij nuk janë përkthyer në shqip, përveç disa himneve nga i paharruari Dhimitër Beduli."},{"t":"h","x":"“Ejani tani, si të kryejmë ndryshimin më të mirë"},{"t":"p","x":"Të ngrihemi lart shpirtërisht, duke kërcyer me këngë"},{"t":"p","x":"Dhe me psalme e himne dhe le të brohorasim Mbrojtësin e nderuar të Durrësit dhe forcues Të patundur të besimit dhe predikuesin e Trinisë,"},{"t":"p","x":"Kalanë e shprestarisë, qortuesin e pabesisë.”"},{"t":"h","x":"“Guximin e paturshëm të tiranit e turpërove"},{"t":"p","x":"Dhe veten e solle therore të gjallë për Krishtin Duke shtrirë mbi kryqin duart e tua të shenjta"},{"t":"p","x":"O Shën Ast i gjithëlavdishëm.”"},{"t":"h","x":"“Duke marrë vendim shumë të fortë, o i urtë,"},{"t":"p","x":"I armatosur me shpirt të hekurt, O Bariu i Durrësit, o Shën Ast i gjithëlavdëruar. E shkele me të vërtetë egërsimin e Agrikolës Dhe me gëzim pranove që të kryqëzoheshe mbi dru"},{"t":"p","x":"Dhe prandaj e more dhe shpërblimin e fitores.”"},{"t":"p","x":"Shën Asti ka qenë dhe vazhdon të jetë një shenjtor tepër popullor ndër besimtarët e krishterë ortodoksë të Durrësit, aq sa edhe mjaft qytetarë të tij mbanin dhe mbajnë emrin e tij, si dhe ndërtonin edhe kisha për nder të tij (historianë, kronistë dhe arkeologë dëshmojnë mjaft për të, ku ndër të tjera përmendim katedralen e madhe për nder të shën Astit dhe Isavrit në shek. XIII-XIV, në Spitallë në vitin 1917, në varrezat e qytetit rreth vitit 1957, pranë portit 2002)."},{"t":"p","x":"Gjithashtu Mitropoliti Jakov shkruan ndër të tjera në parathënien e Shërbesës së tij, hartuar në Durrës në Mitropolinë e Hirshme më 26 korrik 1917, se: “priftërinjtë e qytetit u porositën për muaj të tërë t’i japin djemve të sapopagëzuar emrin e shenjtit. Filluam të ndërtojmë një kishë në zonën e Spitallës, që ndodhet gjysëm ore larg Durrësit, bëmë ikonën e Shën Astit dhe Episkopit të parë të Durrësit, sipas traditës, Apostull Qesarit në kishën e shenjtë të Shën Gjergjit. Por plus këtyre të gjithave përkujdesjeve dhe formimit të Shërbesës me këngë për të kremten në fjalë, përkushtuar tërësisë shpresëtare të Dioqezës sonë të Hirshme dhe veçanërisht të krishterëve kremtëdashës të Durrësit, dhe duke i këshilluar në mënyrë atërore si kujtues të vdekjes në kryq të Episkopit plak dhe hierodëshmorit Asti dhe të nderit të lartë, ku edhe nderohet qyteti dhe me anë të tij e gjithë Dioqeza e Durrësit, duke kryer çdo vit kujtimin e tij të përvitshëm me urtësi, shprestari dhe panagjirikisht, që nga viti im i parë në fronin hieratik në vitin 1911, duke lavdëruar dhe madhëruar atë ndër shenjtorët e Zotit dhe Perëndisë tonë të madh e të lavdëruar, Jisu Krishtit. I Tij qoftë lavdia në jetë të jetëve. Amin.”"},{"t":"p","x":"Fama e shën Astit kalon kufinjtë e qytetit dhe të vendit tonë, duke u përmendur dhe pikturuar në afreske edhe në kisha të tjera lokale si ato të Ohrit, Kosovës, Serbisë, Malit të Zi, Greqisë dhe Italisë."},{"t":"p","x":"“Ejani të kremtojmë tani të gëzuar, o kremtëdashës"},{"t":"p","x":"Panairin e hyjshëm të hierarkut të lavdëruar"},{"t":"p","x":"Dhe të ngazëlluar për punët e lavdishme Që ai ka kryer, le të brohorasim me zë të madh Për atë që madhëroi dhe e lavdëroi veçanërisht Jisuin, Njeridashësin, Shpërblyesin e shpirtrave tanë.”"},{"t":"h","x":"Virgjëresha Juliana"},{"t":"p","x":"Ishte bijë e princit Olshansk dhe fjeti në vitin 1540 në moshën 16 vjet. Dy qind vjet më vonë, ndërsa hapnin një varr pranë kishës qëndrore të Lavrës së Kievit, u gjet trupi i paprishur i virgjëreshës Juliana, e cila ngjante sikur flinte. Mrekulli të shumta u kryen, madje vetë Juliana u shfaq tek shumë besimtarë, dhe një prej më të njohurve ishte Petro Mogila."}]},{"d":7,"m":7,"blocks":[{"t":"intro","x":"Më 7 të këtij muaji, nderojmë kujtimin e dëshmores së madhe grua Kirjakia (E Diela) nga Nikomedia, e cila u martirizua në vitet 284-305."},{"t":"li","x":"Kujtimin e shën Dhorotheut dhe Efsevia, prindërit e shën Kirjakisë."},{"t":"li","x":"Kujtimin e dëshmorëve Peregrini, Lukiani, Pompi, Isiki, Papia, Satornini, Gjermani, të cilët u martirizuan në vitet 98-117 në Durrës."},{"t":"li","x":"Kujtimin e dëshmorit të ri Polikarpi i ri, maroi me shpatë."},{"t":"li","x":"Kujtimin e dëshmorit Evangjeli, maroi me shpatë.."},{"t":"li","x":"Kujtimin e hierodëshmorit Efstathi, maroi me zjarr."},{"t":"li","x":"Kujtimin e atit tonë dëshmor Apolloni, episkop në Vreskia të Italisë në shekullin e 2-të."},{"t":"li","x":"Kujtimin e oshënarit Thoma nga Malea e Peloponezit të Greqisë."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Qirjaqia (E Diela), martire e madhe"},{"t":"p","x":"U ushtrua në kohën e Perandor Dioklitianit (284-305). Dorotheu dhe Efsevia, të pasur dhe të pëlqyer nga Perëndia, por pa fëmijë, luteshin që të bëheshin me fëmijë. Dhe kështu lindën vajzë ditën e diel, ndaj dhe e pagëzuan me emrin E Diela (greqisht Qirjaqi = [dita] zotërore)."},{"t":"p","x":"Duke u rritur ajo pati shumë kërkesa për nuse nga arkon-dët, për hir të bukurisë së saj shpirtërore dhe trupore. Por, duke dëshiruar dhëndrin e shpirtrave, Jisuin, nuk i pranonte propozimet për martesë."},{"t":"p","x":"Kështu, një idhujtar, që e kërkonte nuse për të birin, u zemërua dhe e denoncoi pranë Dioklitianit, i cili hetoi prindë-rit dhe të bijën. I ati u rrah pa mëshirë. Më pas, së bashku me bashkëshorten i dërguan tek arkondi brutal i qytetit armen, Melitini, se mos ndoshta i kthente në paganizëm. Por nuk ia arriti dot dhe u preu kokën."},{"t":"p","x":"Qirjaqinë, Dioklitiani ia dërgoi bashkëperandorit Maksi-mian (286- 305), i cili në atë kohë ndodhej në Nikomedia të Propontidës, në Bithini të Azisë së Vogël. (Nikomedia në vitin 293 u bë kryeqytet i Dioklitianit)."},{"t":"p","x":"Meqenëse nuk e gënjeu me lajka, urdhëroi dhe e tendosën me këmbë e duar dhe e fshikulluan me orë të tëra. Ndërsa torturuesit u lodhën, virgjëresha e fuqizuar nga Hiri hyjnor dukej e gëzuar. Maksimiani i qortoi, duke kujtuar se nuk e godisnin fort ngaqë u vinte keq për bukurinë e saj."},{"t":"p","x":"Më pas e dërgoi tek komandanti gjakatar i Vithinisë, i cili urdhëroi dhe e varën prej flokësh për orë të tëra dhe e digjnin me llambadha. Në burg iu shfaq Zoti, e inkurajoi dhe e shëroi, saqë komandanti u mahnit."},{"t":"p","x":"Ajo pranoi të shkonin në tempullin e hyjnive, siç i kërkoi ai, por në vend që të bënte fli, ajo iu lut Krishtit. Kështu ra termet dhe u rrëzuan idhujt duke u thyer copa-copa, dhe një erë e fortë i shpërndau, ndërsa një rrufe goditi për vdekje tiranin."},{"t":"p","x":"Predikoi lirisht, derisa pasardhësi i tij e arrestoi. E hodhi në zjarr, por zjarri u shua nga një shi i papritur. E hodhën tek luanët, por ata u sollën me të si kafshë shtëpiake. Atëherë shumë njerëz besuan dhe i vranë. Në fund, kur do t’i prisnin kokën, ajo iu lut xhelatëve dhe ata e lejuan që të lutej. Atëherë u shfaqën engjëjt dhe morën shpirtin e saj."}]},{"d":8,"m":7,"blocks":[{"t":"intro","x":"Më 8 të këtij muaji, nderojmë kujtimin e dëshmorit të madh Prokopi, i cili u martirizua ndërmjet viteve 284-305."},{"t":"li","x":"Kujtimin e shën Theodhosisë, nëna e shën Prokopit."},{"t":"li","x":"Kujtimin e 12 dëshmoreve gra bashkë me Antiokun dhe Nikostratin, të cilët besuan tek Krishti ndërmjet shën Prokopit."},{"t":"li","x":"Kujtimin e dëshmorit Abdai, mbaroi me shpatë."},{"t":"li","x":"Kujtimin e dëshmorit Prokopi nga Qesaria e Palestinës."},{"t":"li","x":"Kujtimin e oshënarit Theofil Mirovlitit, murg në shkretëtirën e Kapsalës në Malin e Shenjtë. Mbaroi jetën me paqe në vitin 1558."},{"t":"li","x":"Kujtimin e hierodëshmorit të ri Anastasi i Janinës, i cili u martirizua në Konstandinopojë në vitin 1743."},{"t":"li","x":"Kujtimin e shën Prokopit të Ustiugut i marrë më Krishtin."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Prokopi, martir i madhJ"},{"t":"p","x":"Ishte filiz i Kristoforit të krishterë dhe senatore Theodhosisë (festohet sot), që ishte fillimisht idhujtare, e cila u bë shpejt vejushë. Ajo e drejtoi tek mbreti Dioklitian (284-305) në Antioki, të cilin e bindi me para dhe e emëroi dukë të Aleksandrisë. Bile i ngarkoi që të asgjësonte pasuesit e Nazareasit."},{"t":"p","x":"Por, duke shkuar, u kthye pothuajse ashtu si apostull Pavli (29 qershor). Një mbrëmje, d.m.th. mbas një tërmeti dhe rrufeje, u shfaq një kryq dhe i foli Çliruesi - do t’i fliste dhe në raste të tjera në të ardhmen që ta mbështetë."},{"t":"p","x":"U kthye atëherë në atdheun e tij, Jerusalem dhe predi-konte Ungjillin, siç edhe mposhti në betejë agarinej plaçkitës, duke mbajtur kryqin e çmuar të tij - diçka si eksperiment që e siguroi për fuqinë e të Kryqëzuarit."},{"t":"p","x":"U padit pra nga nëna e tij tek monarku, kështu që pësoi shumë kohë pas kohe në Qesari të Palestinës: Gjithë ditën e shqyenin në mënyrë të frikshme, por në mbrëmje në burg Zoti e shëroi, megjithëse gjysmë i vdekur, dhe ia ndërroi emrin nga Neania, që quhej, në Prokop (greqisht = me pro-kopi); e shqyen fytyrën e tij, pa nxjerrë asnjë psherëtimë; u kamxhikua; u kërcënua se do t’i shponin të përbrendshmet, por ushtarit që mbante ushtën, iu tha dora e pastaj vdiq; e shtrinë në tokë dhe e kamxhikuan; vendosën në shpinën e tij zjarr; e shponin me hell të skuqur dhe i hidhnin kripë në plagë; e lanë t’i digjej dora e vet, në të cilën vunë temjan dhe ia mbajtën me masha mbi altar, që duke mos duruar djegien të lërë të bien temjanët gjoja si therore idhujve; e varën nga duart me pesha në këmbë; u rrezikua të hidhej në furrë, por flakët i vranë ata që ishin rrotull."},{"t":"p","x":"Së fundi, me kërkesë të turmës që trembej se mos i zhdukte të gjithë, iu pre koka më 8. 7. 303 mbasi u lut për të afërmit e tij. Trupi i tij u varros natën me nder nga besimtarët. Jeta tjetër e shën Theodhosisë tregon se si shenjti i shkatërroi idhujt."},{"t":"p","x":"Theodhosia, dymbëdhjetë senatoret, Andioki, Nikostrati, martirë J"},{"t":"p","x":"U ndriçuan falë martirit të madh të mëparshëm Prokop, të cilin e lindi por dhe e tradhtoi e para, d.m.th. senatorja shën Theodhosia, ashtu siç tregohet atje."},{"t":"p","x":"Pra, mbasi iu shfaq në burg Jisui që ia ndryshoi emrin në Prokop dhe e shëroi, ndërsa zinxhirët ishin zgjidhur, e shpunë në tempullin e idhujve, por në vend që të falej, rrëzoi nëpërmjet shenjës së kryqit të tridhjetë idhujt e drunjtë!"},{"t":"p","x":"Të pranishmit u frikësuan dhe dëshmuan spontanisht Shpëtimtarin, dhe natën tribunët (oficerët) Andioki (greqisht = kundërshtar) dhe Nikostrati (greqisht = fitorja e ushtrisë) së bashku me ushtarë depërtuan në burg."},{"t":"p","x":"Shenjti i burgosur, bindi gardianin, dhe ai vetë (Prokopi) i udhëzoi tek episkopi, i cili i pagëzoi. U kthyen dhe i mësonte të gjithë ata që i vinin, madje bënte mrekullira nëpërmjet shenjës së kryqit kryesisht duke shëruar ata që kishin sëmundje të pashërueshme."},{"t":"p","x":"Më 22 maj 303 tribunëve dhe ushtarëve iu prenë kokën sepse nuk e mohuan Krishtin."},{"t":"p","x":"Afër Prokopit u burgosën dhe dymbëdhjetë senatore, të cilat kishin besuar dhe ato. Aq i mbështeste, sa në mëngjes në gjyq, në të cilin erdhi dhe senatore Theodhosia për të parë rezultatin, nuk u tërhoqën. Kështu i varën, dhe iu digjnin brinjët, iu hoqën gjinjtë dhe iu vunë nën sqetulla sfera hekuri të skuqura."},{"t":"p","x":"Theodhosia (greqisht = dhënie e Perëndisë) e mahnitur nga qëndrimi i tyre u radhit me të Vërtetën dhe u burgos me gratë heroike, gjë që entuziazmoi birin e saj."},{"t":"p","x":"Gjithashtu u pagëzua dhe i përballoi pa u përkulur torturat: E rrahën në gojë për të mos poshtëruar idhujt, e tendosën lakuriq, e rrahën katër veta dhe ia shqyen brinjët me thonj të skuqur."},{"t":"p","x":"Pasi dymbëdhjetë atletet luteshin për të, tirani urdhëroi që t’ua godisnin nofullat e tyre me sfera plumbi dhe në fund t’u prisnin kokat të gjithave. Kështu më 29 maj mbaruan të gëzuara të gjitha, të trembëdhjeta."},{"t":"h","x":"Prokopi i Ustiugut, i marrë për Krishtin"},{"t":"p","x":"Ishte bir i të tregëtarve të pasur të Lubekut në Gjermani dhe u rrit në besimin katolik. Gjatë qëndrimit për punë në Novgorod, ai u prek nga bukuria e Orthodhoksisë dhe u pagëzua. Dëshironte të arrinte në përsosmëri, prandaj shpërndau të mirat tek të varfrit dhe hyri në manastirin e Kutinit Çutinit, pranë Novgorodit. Si mësoi bindjen dhe virtytet e krishtera, e braktisi manastirin dhe shkoi në Ustiug, në imitim të shën Andrea së marrë (28 maj), u dha në asketizmin e rrallë e të rrezikshëm të marrëzisë në Krishtin, ende i panjohur në Rusi në atë kohë. Endej në rrugë dhe e ofronte veten në talljet dhe fyerjet e kalimtarëve, natën e kalonte në oborrin e katedrales dhe lutej për ata që gabonin duke përsëritur fjalët e Zotit: “Fali, o Zot, se nuk dinë se ç’ bëjnë” (Lluk. 23.34). I veshur me rrecka, i pambrojtur nga i ftohti i dimrit, pranonte ushqim vetëm nga të varfrit dhe njerëzit e perëndishëm. Një natë dimri, duke mos e duruar dot të ftohtin, shkoi tek disa të varfër, të cilët e lanë tek porta. U përpoq të ngrohej pranë një tufe qensh, por ata u larguan. Mbeti i vetëm, por një engjëll erdhi dhe e ngrohu."},{"t":"p","x":"Nga betejat asketike dhe braktisja plotësisht në vullnetin e Perëndisë, ai fitoi karizmin e profecisë. Një të diel, mori fjalën në katedrale, dhe i nxiti për pendim besimtarët e Novgorodit me qëllim që t’i shpëtonin zjarrit që do ta përpinte qytetin në të njëjtën mënyrë si Sodoma dhe Gomora. Reaguan me tallje, por shenjti e vazhdoi predikimin e tij për tri ditë rresht, në rrugë e kudo, por pa sukses. Kur java u mbyll, një re e madhe e zezë dhe e frikshme e mbuloi qytetin. Populli i frikësuar shpejtoi të gjente shenjtorin, i cili qëndronte në katedrale para ikonës së Ungjillëzimit të Perëndilindëses duke u lutur që qyteti të shpëtonte. Të gjithë u bashkuan me të në lutje, dhe panë se nga ikona rrodhi një vaj me erë qiellore dhe shpërndau atmosferës e tmerrshme. Furtuna u largua në një pyll atje afër dhe me breshër shkatërroi dhunshëm gjithçka. Vaji mrekullibërës u mblodh dhe shëroi shumë të sëmurë."}]},{"d":9,"m":7,"blocks":[{"t":"intro","x":"Më 9 të këtij muaji, nderojmë kujtimin e hierodëshmorit Pangrati, episkop në Tavromeni, nxënës i apostull Pavlit."},{"t":"li","x":"Kujtimin e dëshmorëve Andrea dhe Provi, të cilët mbaruan në zjarr."},{"t":"li","x":"Kujtimin e oshënarëve dhe dëshmorëve Patermuthi, Kopri, Aleksandri nga Egjipti në vitet 361-363."},{"t":"li","x":"Kujtimin e oshënarit Foti, themelues i Manastirit të Akapniut në Selanik të Greqisë."},{"t":"li","x":"Kujtimin e hierodëshmorit Petro nga Vologda e Rusisë."},{"t":"li","x":"Kujtimin e oshënarëve Dionis predikuesi dhe Mitrofani, nxënës i tij nga Skiti i Shën Anës së Vogël në Malin e Shenjtë në shekullin e 16."},{"t":"li","x":"Kujtimin e martirit të ri Metodi o Kretës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Pangratiu i Tavromeniut"},{"t":"p","x":"Që në moshë të re prindërit e tij të pasur dhe të mirë e morën nga atdheu i tyre, Antiokia dhe u pagëzuan të tre bashkë në Jerusalem. Mbas vdekjes së tyre u bë eremit në një shpellë të Pontit, në veri të Asizë së Vogël. Apostull Petri (29 qershor) duke kaluar prej andej e mori për bashkëpunëtor të tij në Antioki dhe në Kiliki, ku takuan apostull Pavlin (29 qershor)."},{"t":"p","x":"Të dy korifejtë (ose njëri prej tyre) e dorëzuan atë episkop të Tavromeniut (sot Taormina) në Siçili, derisa shën Markia-nin (30 tetor) e dorëzuan episkop të Sirakuzës. Të dy hierarkët të lidhur shpirtërisht që nga ai moment, lundruan në Siçili."},{"t":"p","x":"Atëherë Pangratiu ndriçoi shumë idhujtarë në ishull, si dhe qeveritarin e tij, Bonifatin, për hir edhe të mrekullive të tij: I bënte idhujt të rrëzoheshin në tokë ose të binin në det, ndërsa demonët rrëfyen se kishte ardhur Perëndia i madh dhe i vërtetë. Shenjti, që ishte muzikant shumë i shquar, kur meshoi për herë të parë në kishën që ndërtoi për një muaj, të gjithë idhujt e Tavromeniut u rrëzuan! Ai lidhi një gjarpër të gjatë, i cili plasi. Shëronte të sëmurët dhe të demonizuarit, urtësonte mendjelehtët. Paratha për fitore kundër pushtuesve dhe i mundi, duke ngritur kundër tyre një kryq dhe dy ikona. Vetëtinte sidomos kur vishte amfiat (rrobat e klerikut) edhe kur nuk meshonte, pra i hiqte që njerëzit t’i afroheshin pa u trembur!"},{"t":"p","x":"Paranjohu fundin e tij, që erdhi kur cmirëzinjtë, heretikët mondanë kurdisën linçimin e tij, në kohën kur nuk ishte Bonifati. Trupin e tij e vendosën në arkivol të florinjtë, por në vizion kërkoi që ta varrosnin thjesht, sepse asnjëherë në jetën e tij nuk e deshi floririn. Pra lipsanmbajtësja u hap dhe lipsani i bukur, dhe pa shenjë plage, ra erë miro. Atletizimin (martirizimin) e tij e tejpa në Romë Petri."},{"t":"p","x":"Kremtohet edhe më 9 tetor me shën Markelin e Siçilisë, i cili atëherë quhej babai i hierodëshmorit tonë. Nxënëset e tij ishin virgjëreshat e martirizuara në zjarr, Esia e Suzana (7 qershor)."},{"t":"p","x":"Pangratiu, greqisht shpjegohet i gjithëpushtetshëm."}]},{"d":10,"m":7,"blocks":[{"t":"intro","x":"Më 10 të këtij muaji, nderojmë kujtimin e oshënarit Andon nga Lavra e Kievit të Rusisë, i cili themeloi jetën murgërore në Malin e Shenjtë në Rusi. Fjeti në vitin 1067."},{"t":"li","x":"Kujtimin e 45 dëshmorëve nga Nikopoli i Armenisë, ndërmjet tyre ishte dhe kryetari i qytetit: Leonti, Mariki, Danieli dhe Andoni. U martirizuan në vitet 308-324."},{"t":"li","x":"Kujtimin e dëshmorëve Vianori dhe Silvani nga Pisidia."},{"t":"li","x":"Kujtimin e dëshmorit Apolloni nga Sarda e Likisë, i cili u martirizua në Ikoni të Azisë së Vogël."},{"t":"li","x":"Kujtimin e 10 000 murgjve dëshmorëve nga Nitria e Egjiptit, të cilët u martirizuan në kohën e patriarkut të Aleksandrisë Theofili dhe me urdhrin e tij në vitet 385-412."},{"t":"li","x":"Kujtimin e shën Nikodhimit në Berat."},{"t":"li","x":"Kujtimin e etërve të shenjtë Partheni dhe Eumeni, të cilët e përtëritën Manastirin e Kudumës në Kretë."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Nikodhimi nga Vithkuqi"},{"t":"p","x":"Lindi nga prindër shqiptarë dhe shpresëtarë në Vithkuq të Korçës - dhe jo në Elbasan - dhe u bë rrobaqepës në Berat. Mbeti i ve për herë të tretë dhe u martua me një skllave të bukur pasi ndërroi besimin. Bëri synet me dhunë edhe fëmijët e tij, përveç njërit, të cilin të krishterët e çuan fshehurazi në Mal të Shenjtë."},{"t":"p","x":"I inatosur shkoi ta gjente dhe t’i ndëshkonte etërit. Ndër-kaq atje erdhi në pendim, bile u qeth murg me emrin Niko-dhim! - sipas të tjerëve shkoi në Athos sepse u pendua."},{"t":"p","x":"Mbas tre vjetësh vajtimesh dhe kreshmësh dëgjoi se kushdo që mohon Krishtin përpara njerëzve i intereson që ta pohojë Atë përsëri para tyre (shih Mat.10.32-33). Aspiroi atëherë martirizimin dhe shkoi në Kafsokalive tek oshënar Akaqi (12 prill)."},{"t":"p","x":"Ai e thirri me emrin e tij, megjithëse nuk e njihte, dhe e ngushëlloi. Duke u lutur për të iu ndriçua fytyra, ndërsa diçka si yll zbriti mbi të. Më pas i dha leje për t’u martirizuar dhe i dha një shkop për rrugës. Ai, i dobësuar prej kreshmës, iu lut që ta ndërpriste kreshmën për shkak të udhëtimit. Iu përgjigj se sidomos tani i nevoitej kreshma dhe se “njeriu nuk do të jetojë vetëm me bukë” (Mat.4.4). Nikodhimi shtoi se i trembej demonit - jeronti e këshilloi që t’i trembej Perën-disë. I pari mori uratën dhe shkopin e të dytit dhe u nis. Ndo-dhej akoma në Athos, kur iu shfaq Jisui, i dha zemër dhe i paratregoi martirizimet e tij."},{"t":"p","x":"Përshkoi pa u lodhur rrugën deri në Berat, ku e njohën, e rrëmbyen dhe e shpunë tek pashai. Meqenëse nuk u thye, e hodhën nga pallati i lartë i tij. Por nuk pësoi gjë dhe u ngjit përsëri duke vrapuar tek pashai, i cili u tmerrua dhe do ta linte nëse nuk do t’i trembej turmës. Iu dorëzoi pra martirin e ri. Pasi e torturuan tri ditë, duke e shpënë drejt ekzekutimit bënin në mënyrë të përsëritur sikur do ta therrnin, për ta trembur. Ia prenë kokën më 11.7.1722 (ndoshta më 1709, ose më 1714), ndërsa lipsani i shenjtë lëshonte erë të mirë dhe shëronte sëmundje."},{"t":"p","x":"Gjatë martirizimeve të tij rastisi që banorët e zonës së Shpiragut të zbrisnin në Berat. Të gjitha fshatrat e saj, kishin vendosur të islamizoheshin për të shpëtuar nga mundimet e turqve. Por duke parë heroizmin e martir oshënarit, fshatarët u çuditën dhe kur u kthyhen në vendin e tyre, i rrëfyen gjërat. Si rrjedhim pendohen të gjithë, kështu që krahina mbeti e krishterë."},{"t":"p","x":"Nikodhim, greqisht = fitorja e komunitetit. Disa e festojnë më 11 korrik."},{"t":"p","x":"Andoni, themelues i Lavrës së Shpellave të Kievit, atë i murgjërisë"},{"t":"h","x":"ruse"},{"t":"p","x":"U lind më 983 në Liubik, në krahinën e Çernigovit. Në pagëzimin e shenjtë mori emrin Antipa. Që në moshë të re dëshironte t’i përkushtohej Perëndisë, ndaj dhe braktisi atdheun, dhe duke kaluar nga Konstandinopoja arriti në Athos. Atje vizitoi shumë manastire, dhe u pranua në manastirin e Esfigmenut duke u bërë nxënës i igumenit të virtytshëm Theoktist. Ishte gëzimi i vëllezërve në manastir. Pas disa vitesh, igumeni nga një vizion hyjnor e dërgoi nxënësin e tij në Rusi e i tha: “Andon, shko në Rusi që të bëhesh shembull dhe udhëzues për popullin tënd. Bekimi i Malit të Shenjtë qoftë me ty!” Arriti në Kiev më 1013, vizitoi manastiret e qytetit, por s’gjeti vendin që dëshironte. Zbuloi Berestovon, një shpellë që kishin gërmuar Varegët (fis i Vikingëve) dhe qëndroi atje për t’iu përkushtuar lutjes dhe asketizmit. Pas vdekjes së shën Vladimirit më 1015 (15 korrik), biri i tij i pamëshirshëm Sviatopolku, hipi në fron të Kievit. Që të kishte çdo gjë në dorë vrau vëllezërit e tij shën Borisin e Glebin (24 korrik) dhe shpalli një persekutim të përgjakshëm kundër njerëzve të Perëndisë. Kur e pa këtë Andoni, u rikthye sërish në Athos dhe i kërkoi igumenit të tërhiqej diku larg manastirit në malin e Samarisë (Atje gjendet edhe një kishë kushtuar shën Andonit). Por Sviatopolku u mund nga princi i perëndishëm Iaroslav (1019), i cili mblodhi murgjit e shpërndarë në atë kohë dhe ndërtoi shumë kisha. Një prift i Berestovos me emrin Ilarion, i shquar për asketizmin e tij dhe njohjen e Shkrimeve, u vendos në kodrën e pyllëzuar të Dnieprit, ku ngrihet sot Manastiri i Lavrës së Kievit. Atje ai gërmoi një shpellë dhe jetoi me perëndishmëri deri ditën kur u ngjit në fronin episkopal të Kievit (1051). Në të njëjtën kohë, edhe igumeni Theoktist pati një zbulim hyjnor dhe e dërgoi Andonin në Rusi; dhe Perëndia i drejtoi hapat e tij atje ku kishte asketizuar prifti Ilarion. Vendi i ngjante Malit të Shenjtë, ndaj dhe shenjti kërkoi që bekimi i Athosit të vinte atje. Ushqehej vetëm me bukë një herë në 2-3 ditë, dhe kur kishte vegime kalonte një javë pa bukë e ujë. Njerëzit përreth e njohën jetën e tij engjëllore dhe filluan ta vizitonin. Disa kërkuan të jetonin pranë tij: fillimisht prifti Nikon (23 mars), shën Theodhosi, i cili atëherë ishte 23 vjet (3 maj). Vendin ku jetonte shenjti e vizitoi edhe princi i Kievit Iziaslav, që kishte pasuar fronin e Iaroslavit (1054) dhe kjo bëri që të vinin dishepuj të rinj në shpella, si i lumuri Varlaam, bir i bojarit Joan (19 nëntor) dhe Efrem eunuku, biri i adoptuar i princit të madh (28 janar). Por kur bojari Joan mori vesh se djali i tij ishte bërë murg, shkoi i tërbuar në shpella dhe i grisi të birit veshjen murgërore dhe e solli me forcë në pallat. Nga ana tjetër, Iziaslavi ndaloi shën Nikonin që e kishte qethur murg Efremin, kërcënoi se do t’i prishte shpellat dhe murgjit do t’i burgoste. Atëherë shën Andoni dhe nxënësit e tij shkuan në një tjetër vend, por gruaja e Iziaslavit e luti bashkëshortin e saj që t’i jepte fund persekutimit, sepse zemërimi hyjnor do të binte mbi ta. Princi u zbut. E thirri Andonin të rikthehej në manastir. Andoni kërkonte vetminë. Caktoi Varlaamin si igumen të vëllazërisë dhe vetë u largua pranë një korije ku gërmoi një shpellë (edhe sot ruhet kjo shpellë). Vëllazëria u rrit, u ndërtua një kishë më e gjerë. Igumeni Varlaam u thirr nga princi të ishte igumen në Manastirin e Shën Dhimitrit, që ai kishte ndërtuar vetë. Atëherë vëllezërit shkuan tek Andoni, i cili u caktoi si igumen shën Theodhosin për virtytet e tij, bindjen, butësinë dhe përulësinë. Nën drejtimin e tij manastiri u rrit nga 20 arriti në 100 murgj, kështu që u ndërtua një manastir për ta. I lanë shpellat dhe hynë në këtë manastir që mban emrin Lavra e Shpellave të Kievit (Peçersk). Falë lutjeve të Andonit, Theodhosi njohu murgun Mikhael të Studionit, që vizitoi në atë kohë Rusinë, dhe mori Tipikonin e Studionit."},{"t":"p","x":"Që atëherë, ky rregull hyri në manastiret ruse. Shën Andoni arriti në lartësi të mëdha, fitoi largpamësi, iu zbuloi princave të Kievit humbjen që do të pësonin në Alta kundër Popovciensëve (fise luftarake nomade), që më pas do të vidhnin e plaçkitnin qytetet. Një nga të afrimit e princit akuzoi Andonin se simpatizonte pushtuesin dhe u zemërua shumë me njeriun e Perëndisë. Në këtë periudhë shën Andoni kujdesej për Isaakun e mbyllur, i cili u mashtrua nga djalli, por ky i fundit frymëzoi princin ta largonte Andonin nga manastiri që dhe shërimi i vëllait të mashtruar të ndërpritej. Princi i Çernigovit, Sviatoslavi, kur mësoi për zemërimin e vëllait të tij kundër shenjtit, e ftoi Andonin në principatën e tij. Atje ai gërmoi një shpellë dhe rinisi jetën e tij. Më në fund Iziaslavi e kuptoi gabimin që kishte bërë dhe se shenjti ishte i pafajshëm, kuptoi edhe dredhinë e djallit, prandaj e luti Andonin të rikthehej në vend. Pasi u kthye në Kiev, dyfishoi betejat e tij. Ndjeu orën e largimit nga kjo jetë. Si jetoi 16 vjet në shpellën e tij të dytë, shën Andoni u bë patriarku i murgjve në Rusi, si shën Andoni i madh në Egjipt. Fjeti në paqe më 10 korrik 1073 (sipas të tjerëve në 7 maj) në moshën 90 vjeçare. Trupi i tij u vendos në shpellën e tij dhe ashtu siç dëshironte kur ishte ende në këtë jetë, trupi i tij nuk u zbulohej njerëzve. Sa herë që gërmohej në shpellë për ta gjetur atë, një zjarr dilte nga toka dhe i digjte të guximshmit. Megjithëse i fshehur, trupi i shenjtit nuk rreshti së bëri mrekulli dhe shërime tek besimtarët."}]},{"d":11,"m":7,"blocks":[{"t":"intro","x":"Më 11 të këtij muaji, nderojmë kujtimin e mrekullisë së shën Efimias, e cila lavdëroi dogmat e Kishës Orthodhokse para monofizitëve."},{"t":"li","x":"Kujtimin e hierodëshmorit Kindheu nga Sidi i Pamfilisë ndërmjet viteve 284-305."},{"t":"li","x":"Kujtimin e dëshmorit Markiani, i cili mbaroi me shpatë në Ikonium."},{"t":"li","x":"Kujtimin e oshënarit Leon nga Mandra."},{"t":"li","x":"Kujtimin e mbretëreshës Ollga, në Kiev të Rusisë, e cila në pagëzimin e saj mori emrin Elena në vitin 969."},{"t":"li","x":"Kujtimin e hierodëshmorit Arseni, patriark i Aleksandrisë në vitet 980- 1010."},{"t":"li","x":"Kujtimin e oshënarit Nikodhimi, i cili jetoi në shkretëtirën e Manastirit të Vatopedhit në Malin e Shenjtë, mësues shpirtëror i shën Grigor Pallamait, në shekullin e 13."},{"t":"li","x":"Kujtimin e martirit të shenjtë Martirokli, të cilin e shpuan me shigjeta."},{"t":"li","x":"Kujtimin e dëshmorit të ri Nektari."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Shën Efimia, e cila konfirmoi besimin e 630 Etërve Hyjmbajtës të"},{"t":"h","x":"mbledhur në Kalkidhoni në Sinodin e katërt Ekumenik"},{"t":"p","x":"Që nga Sinodi i IV-t Ekumenik, mbledhur nga perandorët Marsian e Pulkeria në Kalqedoni, në basilikën e shën Efimisë, 630 Etër u mblodhën për të hedhur poshtë mendimet heretike të arkimandritit Eftiqi, i cili mbështetej nga kryepeshkopi i Aleksandrisë, Dioskori. Që të kuptonin me një vendim nga Perëndia se kush ishte doktrina e vërtetë, patriku shën Anatoli sugjeroi që të dyja palët të hartonin nga një vëllim mbi doktrinën që mbronin dhe t’i vendosnin mbi lipsanet e shën Efimisë. Të dy librat që kishin në përmbajtjen e tyre personin e Krishtit, u vendosën mbi kraharorin e shenjtores dhe pasi mbyllën varrin, etërit filluan të luteshin. Pas 8 ditësh u hap varri i së lumurës dhe zbuluan të mrekulluar se shenjtorja shtrëngonte në krahët e saj doktrinën e vërtetë, sikur të dëshironte ta fuste brenda në zemër, ndërsa vëllimi tjetër heretik gjendej në këmbët e saj. Para kësaj mrekullie të krishterët e besimit të vërtetë lavdëruan Perëndinë, ndërsa heretikët u nxorën jashtë nga turma dhe u mbuluan me turp. Tregohen shumë mrekulli që ka kryer shën Efimia. Gjatë një invazioni pers, barbarët pushtuan Kalqedoninë dhe u përpoqën të shkatërronin me zjarr lipsanet e shenjta të saj. Por ato qëndruan të paprekura dhe gjak i freskët doli nga vrima që ata i kishin bërë varrit. Në vazhdim, kjo mrekulli vazhdoi të përsëritej herë pas here, duke bërë mjaft shërime tek besimtarët që merrnin nga gjaku i saj. Shumë shpesh nga varri i saj del një parfum erëmirë, si dëshmi e pëlqimit tek Perëndia. Për t’i mbrojtur këto lipsane të çmuara, i transferuan në Konstandinopojë dhe i vendosën në kishën që mban emrin e saj, pranë Hipodromit. Gjatë persekutimeve të Konstandin Kopronimit, lipsanet e shën Efimisë u hodhën në det, ndërsa kisha u transformua në një magazinë armësh, por u ndalën në breg të ishullit Lemnos dhe u morën nga peshkatarët. Pasi u gjetën gjatë mbretërimit të perandoreshës Irena, u transferuan solemnisht në kryeqytet (796) ku vazhduan të bënin mrekulli. Pas shumë peripecish të tjera, ato sot nderohen në kishën e Patriarkanës Ekumenike, në Fanar."},{"t":"h","x":"Ollga mbretëresha"},{"t":"p","x":"Pararendësja e Krishterimit në Rusi. Me sa duket, ishte prej një familjeje me prejardhje të parëndësishme sllave ose skandinave. U martua në vitin 903 me Igorin, mbretin e Kievit, kryeqytetit të të gjitha principatave ruse të asaj kohe, i cili më 941 ndërmori një invazion kundër Konstandinopojës, por pa sukses."},{"t":"p","x":"Mbas vdekjes së tij në vitin 945, është ajo që qeveris mbretërinë e Kievit, duke qëndruar si regjente e djalit të tyre dyvjeçar, Svjatosllavit."},{"t":"p","x":"Çifligarja më e madhe e stepave, duke qenë shumë e zgjuar, mundi menjëherë me dinakëri dhe u hakmor ndaj një fisi kryengritës, i cili kishte vrarë burrin e saj."},{"t":"p","x":"Organizoi një pushtet të centralizuar , dhe kështu morën fund invazionet ndaj fiseve sllave të veçuara. Gjithashtu u kujdes për sigurimin e rrugëve tregtare, si dhe për fitimin e privilegjeve tregtare nëpër qendrat e Perandorisë Bizantine."},{"t":"p","x":"Por më kryesorja ishte se mori pagëzimin, që pavarësisht nga karakteri personal që kishte, shërbeu si shembull për nënshtetasit e saj dhe hapi rrugën për pranimin në shkallë kombëtare të Krishterimit, të cilin e futi (më 989), nipi i saj, mbreti Vladimir (15 korrik)."},{"t":"p","x":"Ekzistojnë burime të ndryshme përsa i përket bërjes së krishterë të saj. Ka shumë mundësi të ketë udhëtuar vetëm një herë dhe jo dy herë në Konstandinopojë, në vitin 957, për shkak të marrëveshjeve të suksesshme tepër favorizuese tregtare me bizantinët, por edhe u pagëzua, siç duket e joshur prej Krishtit, gjatë qëndrimit të saj të gjatë atje. Gjatë misterit u quajt Eleni, ashtu siç quhej dhe bashkëshortja e perandorit Konstandin VII Porfirogjenit (913–959). Por ne mendojmë se mund të kishte parasysh të parën perandore tjetër të krishterë, Elenin (21 maj)."},{"t":"p","x":"Në kryeqendrën e Bizantit, u prit në bankete zyrtare në mënyrë të përsëritur nga mbreti i sipërpërmendur Porfirogjeniti, sikundër shkruan dhe vetë ai. Ollga (ose Elga) dërgoi amba-sadorë për zhvillimin e marrëdhënieve miqësore dhe politike edhe me mbretin e frëngëve, Otonin. Fjeti në vitin 969."}]},{"d":12,"m":7,"blocks":[{"t":"intro","x":"Më 12 të këtij muaji, nderojmë kujtimin e dëshmorëve Prokli dhe Ilariu, nipi i tij, të cilët u martirizuan në vitet 98-117."},{"t":"li","x":"Kujtimin e shën Veronikës, e cila u shërua nga Jisu Krishti. (Lluk. 8,42- 48)."},{"t":"li","x":"Kujtimin e dëshmorit Serapioni i ri, i cili u martirizua në 193-211."},{"t":"li","x":"Kujtimin e dëshmorëve Andrea bashkë me Iraklin, Faustin, Minain."},{"t":"li","x":"Kujtimin e dëshmorit Mamas."},{"t":"li","x":"Kujtimin e oshënarëve dhe dëshmorëve Theodhori i Kievit dhe biri i tij Joani, të cilët u martirizuan nga paganët në vitin 983 në Rusi."},{"t":"li","x":"Kujtimin e oshënarit Mikail Maleini, mësues dhe atë shpirtëror i oshënarit Athanas athoniti."},{"t":"li","x":"Kujtimin e oshënarit Arseni i marrë më Krishtin në Novgorod të Rusisë në vitin 1570."},{"t":"li","x":"Kujtimin e shën Serapionit, episkop i Vladimirit."},{"t":"li","x":"Kujtimin e atit të shenjtë Simon, igumen në Manastirin e Volomskut."},{"t":"li","x":"Kujtimin e shën Joanit (998) dhe Gabrielit të Siatogorskut."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Veronika, gruaja me fluks gjaku që u shërua nga Krishti * Shën Veronika ishte nga Qesaria e Filipisë. U shërua nga Shpëtimtari ynë Jisu Krisht nga një fluks gjaku që e mundonte prej shumë vitesh (Mat. 9:20). Si dëshmi të veprimit të hirit, ajo bëri një statujë bronzi që paraqiste Krishtin duke shtrirë dorën tek një grua e gjunjëzuar para Tij. Në këmbët e saj, ku mund të lexojmë edhe mbishkrimin: “Perëndisë, Shpëtimtarit të botës”, mbiu një bimë e cila shëronte të sëmurë. Këtë statujë e vendosi përpara shtëpisë së saj me qëllim që njerëzit të kujtonin Perëndinë. Pasi jetoi një jetë të pëlqyeshme tek Zoti, fjeti në paqe."},{"t":"p","x":"Sipas traditës, ajo ishte gruaja që i fshiu fytyrën Krishtit duke ecur me kryqin në Golgota. Në peshqirin e saj mbeti Fytyra e Shenjtë e Shpëtimtarit. Veronika në greqisht d.m.th vera ikona – ikonë e vërtetë. Ajo është mbrojtësja e lavantierëve dhe e fotografëve."},{"t":"h","x":"Theodhori dhe Joani, vikingë"},{"t":"p","x":"Shën Vladimiri (15 korrik), i cili futi përfundimisht Krishterimin në Rusi, sapo u bë mbret i Kievit (980) filloi të përndiqte të krishterët vikingë të shumtë në numër. Për të ringritur paganizmin, ndërtoi në kryeqytetin e tij idhuj të hyjnive sllave."},{"t":"p","x":"Atëherë u martirizuan turma të krishterësh, midis të cilëve dhe shën Theodhori dhe biri i tij, shën Joani, të cilët sipas urdhrit të Vladimirit, u sakrifikuan për perënditë në vitin 980 - diku tjetër këta shenjtorë janë të shkruar si martirë oshënarë të martirizuar në vitin 983. Gjithashtu ekziston mendimi se dëshmorët e parë të Rusisë ishin tregtarë grekë."}]},{"d":13,"m":7,"blocks":[{"t":"intro","x":"Më 13 të këtij muaji, nderojmë kujtimin e Mbledhjes së Kryeengjëllit Gabriel."},{"t":"li","x":"Kujtimin e oshënares Golindhuk në Persi, e cila në pagëzimin e saj mori emrin Maria, në Jeruzalem në shekullin e 7."},{"t":"li","x":"Kujtimin e oshënarit Stefani nga Manastiri i Shën Savës në Jerusalem, nipi i oshënarit Joan Damaskinoi, jetoi në vitin 725-807."},{"t":"li","x":"Kujtimin e oshënares Sara."},{"t":"li","x":"Kujtimin e martires së shenjtë Sirea në Persi."},{"t":"li","x":"Kujtimin e etërve të nderuar Eliofoti, Epafroditi, Amoni, Kulelei dhe Eustheni të cilët asketizuan në Qipro."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Shkrimi i Shenjtë në mëson se Perëndia në momente të caktuara historike i dërgon ëngjëjt edhe në forma të dukshme për të zbatuar ose lajmëruar ndonjë plan hyjnor me rëndësi. Na mëson gjithashtu se në krye të fuqive ëngjëllore qëndrojnë Kryeëngjëjt Mihail e Gavril. Edhe Kryeëngjëlli Gavril përmendet disa herë në Dhiatën e Vjetër dhe në Dhiatën e Re. Kështu Kreyëngjëlli Gavril iu shfaq profetit Dianiel dhe i shpjegoi atij kuptimin e ëndrrave të fikshme të Nabukodonosorit dhe njeridashja e Perëndisë e ndihmoi dhe e udhëhoqi atë në të gjitha situatat e vështira që kalonte. Gjithashtu iu shfaq Joakimit dhe Anës. Iu shfaq profetit Zaharia dhe i dërgoi lajmin e gëzuar duke i thënë: “Mos u tremb Zaharia sepse lutja jote u plotësua dhe gruaja jote Elizabeta do të lindë djalë të cilit do t’ia vesh emrin Joan”. Gjithashtu Kryeëngjëlli Gavril u dërgua prej Perëndisë tek Virgjëresha Mari për t’i njoftuar lajmin e trupëzimit tek ajo të shpëtimtarit tonë Isu Krisht. Dhe në muajin e gjashtë, shkruhet në Shkrimin e Shenjtë, Kryeëngjëlli Gavril u dërgua nga Perëndia në një qytet të Galilesë të quajtur Nazaret tek një virgjëreshë. Dhe Kryeëngjëlli i tha: “Gëzohu o Hirplotë, Zoti është me ty dhe e bekuar je ti në mes të grave se gjete hir tek Perëndia dhe do të mbetesh shtatzanë e do të lindësh djalë e do t’i vësh emrin Isu. Ky do të jetë i madh dhe do të quhet bir i të Shumëlartit”. Kryeëngjëlli Gavril gjithashu iu shfaq Josifit, barinjve dhe më pas përsëri Hyjlindëses e Josifit duke i njoftuar se mund të ktheheshin përsëri nga Egjipti në Nazaret sepse Herodi kishte vdekur. Sipas Proklit të K/pojës “Gavril” do të thotë Perëndi dhe njeri sepse veçanërisht edhe ai shërbeu në trupëzimin e fjalës së Perëndisë."},{"t":"h","x":"Oshënar Stefan Sabaiti"},{"t":"p","x":"Nipi i shën Joan Damaskinoit, lindi në Damask në vitin 725. Kur ishte 10 vjeç xhaxhai i tij e dërgoi në Labra të shën Savës ku për 15 vjet u ushtrua shumë mirë në jetën murgjërore. Pas vdekjes së xhaxhait të tij shkoi në shkretëtirë dhe iu përkushtua krejtësisht studimit të fjalës së Perëndisë. Gjithashtu në shkretëtirë u mor me poezi dhe arriti të bëhej një nga poetët e kishës sonë. Talentin që i kishte dhuruar Perëndia oshënari ia përkushtojë vetëm lavdisë së Perëndisë dhe jo admirimt njerzor. Kjo ndodhte sepse ai frymëzohej gjithmon nga fjalët e Shkrimit të Shenjtë i cili thotë: “Dhe çdo gjë që të bëni me fjalë e me vepër t’i bëni në emër të Zotit Isu, duke e falenderuar Perëndinë Atë nëpërmjet tij. Oshënar Stefani pasi e zbukuroi kishën me poezi ndërroi jetë në paqe në vitin 807."},{"t":"h","x":"Sara, oshënare"},{"t":"p","x":"“Amas” (= nënë) me famë, një nga eremitet e pakta mbinjerëzore, të cilat stolisin librin “Parajsa e etërve”, ndry-she “Jerontikoja”. Ky libër përshkruan përpjekjet e jerontëve të Egjiptit të shekujve të 4-t dhe 5-të. Shenjtja fjeti në paqe."},{"t":"p","x":"Çfarë tha: “Në qoftë se do të lutem që të informohen të gjithë në shpirt për sjelljen dhe jetën time, do të ndodhem që të pendohem përpara derës së secilit. Por më mirë do të lutem që zemra ime të jetë e kulluar me të gjithë. - Mirë është që të japë lëmoshë dikush qoftë edhe ‘për t’u dukur’, që të pëlqehet ndër njerëzit, sepse dikur do të ngjitet edhe në pëlqim të Perëndisë”."},{"t":"p","x":"Çfarë bëri: Asketoi për gjashtëdhjetë vjet mbi një lumë dhe nuk u përkul poshtë që ta shohë! - Gjithashtu kultivonte “kujtesën e vdekjes”."},{"t":"p","x":"Çfarë bëri dhe tha: Dy eremitë të respektuar pilusiotë (nga Pilusi i Nilit) shkuan tek ajo. Gjatë rrugës menduan: “Le ta bëjmë të përulur plakën”, dhe pasi vajtën i tërhoqën vëmendjen: “ - Shiko se mos të rritet mendja, që ne isikastët erdhëm tek ti, megjithëse je grua. -Në natyrë, në trup, jam grua, u përgjigj pa vonesë dhe burrërisht, por jo në arsye, në mendje”. - Dikur priti vizitorë murgj prej Skitit. Kur iu shtroi për të ngrënë ata hëngrën ushqimet e prishura dhe lanë të mirat. Atëherë ajo i përgëzoi: “Me të vërtetë jeni skitiotë!” - Për 13 vjet ishte në objektivin e demonit të prostitucionit, por asnjëherë nuk u lut që t’i hiqej përflakja e fuqishme! Lutej vetëm që Zoti t’i japë fuqi. Madje dikur, ku fryma e papastër e presionoi ekstremisht, u ngjit në qelinë e saj e sfi-litur që të komunikonte me të Gjithëpushtetshmin. Atëherë i paraqitet skandalbërësi velzevul dhe e pranoi: “Ti Sara më munde”! Hodhi tej lavdërimin e neveritshëm dhe krenarinë shkatërrimtare duke ia kthyer me përulësi: “Nuk të munda unë, por Krishti, Zoti im”!"},{"t":"p","x":"Sara, hebraisht përkthehet hegjemone."}]},{"d":14,"m":7,"blocks":[{"t":"intro","x":"Më 14 të këtij muaji, nderojmë kujtimin e apostullit Akila."},{"t":"li","x":"Kujtimin e dëshmorit Justi nga Roma."},{"t":"li","x":"Kujtimin e dëshmorëve Akila dhe Ilariu."},{"t":"li","x":"Kujtimin e hierodëshmorit Petro i ri, episkop në Kretë."},{"t":"li","x":"Kujtimin e dëshmorit Irakliu."},{"t":"li","x":"Kujtimin e oshënarit Onesim çudibërësi, i cili fjeti në Magnesia të Azisë së Vogël në shekullin e 4-t."},{"t":"li","x":"Kujtimin e atit tonë Josifi, kryepiskop i Selanikut, igumen në Manastirin e Studitit në Konstandinopojë. Fjeti në Selanik në vitin 832."},{"t":"li","x":"Kujtimin e oshënarit Stefan çudibërësit, igumen në Manastirin e Shën Trinisë në Vologda të Rusisë në vitin 1406."},{"t":"li","x":"Kujtimin e oshënarit Nikodhim Agjioriti, mësues i urtë i Kishës sonë dhe shkrimtar i shumë librave. Fjeti në Malin e Shenjtë në vitin 1809."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Nikodhim Ajoriti"},{"t":"p","x":"Ishte shkrimtar i palodhur, theolog i shquar i shekujve të fundit. Ka lindur më 1749 nga prindërit arkondë të pasur në ishullin Naksos (në mes të Egjeut), Anton Kallivurci dhe Anastasia, e cila më pas u bë murgeshë, Agathia."},{"t":"p","x":"U edukua në vendlindje dhe në Izmir të Azisë së Vogël (1765-1770) dhe kur u kthye në ishull në vitin 1770, me sa duket për shkak të përndjekjeve të turqve, depozitoi në kujtesën e tij kolosale një mori dijesh theologjike. Për më tepër atëherë u njoh me etër ajoritë, të cilët i zbuluan murgërinë."},{"t":"p","x":"Në një vizitë të shkurtër që bëri në ishullin Hidra, që banohet nga arvanitas, takon shën Makarin e Korinthit (17 prill) dhe lidhet me të. Këta të dy do të evidentohen më vonë si prijësa të lëvizjes, e keqkuptuar atëherë, së “kolivadheve”."},{"t":"p","x":"Më 1775 lundron në Malin e Shenjtë (Ajonoros). Qethet murg në Manastirin e Dionisit dhe nga Nikolla që quhej merr emrin Nikodhim. Meqenëse donte qetësi absolute shpërngulet në një qeli afër Karies (“kryeqytet” i Athosit), ku kalon pjesën më të madhe të jetës së tij - jetoi edhe në vende të tjera, por për pak kohë, midis të tjerëve dhe për një vit jetoi i vetëm në një ishull të vogël e të shkretë."},{"t":"p","x":"Mban korrespondencë edhe me Patrikun shën Grigor V (10 prill) etj., kopjon kodikë (dorëshkrime) që të siguronte jetesën dhe njëkohësisht studion. Formulon dhe koleksione, dhe më tepër se njëqind vepra autentike dogmatike, “ndërtuese” (shpirtërore), kanonike, himnologjike, shpjeguese etj., në origjinal, të cilat kanë rëndësi edhe nga ana letrare. Më të njohura janë “Filokalia”, shumëshpirtërore, “Për kungimin e vazhdueshëm”, e bujshme, të cilën e kundërshtoi dhe e dënoi një patrik i tërhequr nga antikolivistët, “Everjetinosi”, tërheqës, “Lufta e padukshme”, frytdhënëse, “Martirologji i ri”, i çmuar, “Timoni” me kanunet e së drejtës kishtare, “Sinaksaristi” (= jetë shenjtorësh) i përmbledhur, “Manuali këshillues” didaktik."},{"t":"p","x":"Duke qenë shëndetlig që nga 1805 oshënari asketik, i përulur, i sjellshëm dhe i varfër, fjeti më 14.7.1809 në Karies, ku ruhet edhe koka e tij."},{"t":"h","x":"Akila, apostull"},{"t":"p","x":"Sipas Veprave të Apostujve, Pavli (29 qershor) gjatë udhëtimit të tij të dytë (49-52) i ardhur nga Athina arriti në Korinth. Atje gjeti hebreun Akila (latinisht = shqiponjë), i cili ishte nga Ponti (në veri të Azisë së Vogël) dhe gruan e tij, Priskilën ose Prisken (= e vjetër e respektuar, arkonde). Para pak kohe i kishin dëbuar nga Roma me gjithë izrealitët. Kështu urdhëroi më 49-50 perandori Klaudi I (41-54), sepse siç na informon historiani latin Suetoni, shkaktonin trazira të nxitur nga një farë Kristo (Krestus). Nënkupton siç duket Krishtin - Suetoni me sa duket nuk ndante judenjtë nga të krishterët. Pavli pra shkoi dhe qëndroi me çiftin si punëtorë të një zanati dhe bënin bashkarisht çadra prej lëkure (18. 1-3). Mbase ishin vetë të krishterë nga Roma prandaj Pavloja u ngjit pas tyre. Por Sinaksarët bëjnë të ditur se u pagëzuan nga Pavloja në Korinth. Priskila duket se ishte romake, mund dhe prej familjeje të shquar, e cila u mohua për arsye të martesës së saj me një hebre."},{"t":"p","x":"Të dy apostujt, që më pas u bënë bashkëpunëtorë shumë të çmuar të Pavlit, ai i mori me vete dhe i la në Efes që të merreshin me misionarizëm (18. 18-19). Atje u njohën me intelektualin hebre, Apollo (8 dhjetor) nga Aleksandria. I mësuan me saktësi besimin, të cilin e predikonte por me mangësi (18. 24-26). Përderisa edhe Priskila mësonte Apo-lloin, konkludon se ishte e edukuar dhe aktive."},{"t":"p","x":"Pavloja, duke shkruar nga Efesi për Korinthianët, i përcjell të fala të dy bashkëshortëve (I Kor.16.19). Gjithashtu përmenden në mënyrë shumë të lavdërueshme në Letrën për Romakët (16.3-4): Pavloja si dhe Kishat e kombeve iu dedikojnë mirënjohje, sepse rrezikuan për hir të Pavlit. Përshëndeten akoma dhe në II Tim. 4.19. Çifti që vdiq me kokëprerje prej të pabesëve sipas Sinaksarit, kremtohet së bashku më 13 shkurt."}]},{"d":15,"m":7,"blocks":[{"t":"intro","x":"Më 15 të këtij muaji, nderojmë kujtimin e dëshmorëve Julita dhe djalit të saj Kiriku, të cilët u martirizuan në Tars të Kilikisë në vitet 284-305."},{"t":"li","x":"Kujtimin e dëshmorit Avudimi, i cili u martirizua në ishullin Tenedi të Greqisë në vitin 284-305."},{"t":"li","x":"Kujtimin e dëshmorit Loliani."},{"t":"li","x":"Kujtimin e mbretit të Konstandinopojës Justiniani i IItë (689-695)."},{"t":"li","x":"Kujtimin e gjetjes së kokës së shën Matronës nga Hios i Greqisë."},{"t":"li","x":"Kujtimin e apostullit dhe ndriçuesit të popullit rus shën Vladimiri, i cili në pagëzimin e tij mori emrin Vasili në vitin 987 në kohën që ishte mbret i Rusisë. Fjeti në vitin 1015."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Kiriku dhe Julita, martirë"},{"t":"p","x":"Me prejardhje gjaku mbretëror dhe “në lule të rinisë” duke patur një “jetë të panjollëshme”, Julita mbeti e ve. Jetonte në Ikoni, në brendësi të bregdetit jugor të Azisë së Vogël, kur në fillim të shekullit të 4-t shpërtheu përndjekja e perandorit Dioklitian (284-305)."},{"t":"p","x":"Meqenëse guvernatori lokal i përndiqte të krishterët me egërsi, ajo mori djalin trevjeçar, Kirikun dhe iku në Selefkinën bregdetare. Gjendja e njëjtë që ishte atje e dëboi më në lindje, në Tarso të Kilikisë, por atje e arrestoi qeveritari shpirtbishë."},{"t":"p","x":"Porsa shpalli publikisht besimin e vërtetë, e rrahu dhe e dënoi me gërvishtje dhe me tortura të tjera, të cilat i duroi duke lavdëruar Perëndinë."},{"t":"p","x":"Pastaj ia rrëmbyen djalin nga prehri dhe e hodhën në shkallët e gjykatës. Foshnja belbëzoi fjalën “i krishterë”, atëherë tirani i tërbuar e goditi me shkelm, duke i çarë kokën ende të njomë... Burime të tjera thonë se qeveritari u përpoq që ta mposhtte me përkëdhelje Kirikun (greqisht = predikues ose tellall), ai belbëzoi emrin e Krishtit dhe njëkohësisht e shkelmoi tiranin në bark. Atij i dhembi dhe i egërsuar e hodhi nëpër shkallë, duke u goditur në kokë. Kështu koret e shenjtorëve pritën vëllanë e tyre të vogël. Nëna trimëreshë nuk u dorëzua prej fundit të tij çnjerëzor dhe ia prenë kokën më 15 korrik pas torturave të tjera."},{"t":"p","x":"Lipsanet i kishin varrosur fshehurazi dy shërbëtorët e saj, që kishin vëzhguar martirizimin e tyre. Njëra jetonte akoma në kohën e Konstandinit të Madh (21 maj), kur ndaluan përndjekjet dhe tregoi varrin e tyre."},{"t":"p","x":"Shumë shpejt nderimi për dy dëshmorët u shtri në Azinë e Vogël, pak më vonë edhe në Palestinë, Konstandinopojë, Itali dhe Spanjë dhe u ndërtuan shumë kisha për ata."},{"t":"h","x":"Vladimiri i Madh"},{"t":"p","x":"Ai është si Konstandini i Madh (21 maj) për rusët. Lindi në vitin 949 ose 956. prindërit e tij ishin Svjatoslavi dhe Maluka. Svjatoslavi ishte biri i shën Olgës (11 korrik), princ i madh i Kievit dhe idhujtar, ndërsa Maluka , ish administratorja e saj, që duket se ishte edhe skllavja e saj."},{"t":"p","x":"Pas vdekjes së të atit (972) Vladimiri u bë princ i Novgorodit, por me dëshirën e vet u internua në Skandinavi për shkak të konflikteve me dy vëllezërit."},{"t":"p","x":"Më 980 vrau njërin prej tyre dhe u bë pasardhës i tij në fronin e Kievit. Ai u bë rigjallëruesi i paganizmit dhe flijoi shumë të krishterë, njëkohësisht ishte i dhënë shumë pas femrave. Por ai, gjenial dhe i shquar si politikan dhe ushtarak, u ndriçua. Kështu më 986 pranoi, siç besohet, përfaqësues fesh të mëdha dhe u tërhoq më tepër nga krishterimi. Që të gjente shprehjen e tij më të mirë, dërgoi më 987 ambasadorë në vende të ndryshme. Njerëzit e tij u joshën fort nga adhurimi në kishën e Shën Sofisë në Bizant, kultura e të cilit rrezatonte."},{"t":"p","x":"Në të kohë, perandori bizantin Vasili II (976-1025) i kërkoi ushtarë që të shtypte një grusht shteti. Si kundërpeshë ai i kërkoi për grua motrën e tij Ana, tjetri i kërkoi që të pagëzohej; pranoi. Ndihma u dërgua dhe rebelimi u shtyp. Mirëpo Vasili e sorollaste, nuk po e mbante fjalën; kuptohet, kishte ndikimin e vet edhe Ana. Kështu Vladimiri [rusisht= zotërues i paqes] pushtoi Hersonën bizantine dhe të gjithë Krimenë. Ana erdhi me nxitim dhe u martua me përndjekësin e mëparshëm të të krishterëve, pasi u pagëzua Vasil (988)."},{"t":"p","x":"Pas pagëzimit, Vladimiri u shërua nga një sëmundje në sy, si apostull Pavli. Së bashku me klerikë grekë u kthye në Kiev dhe pagëzuan popullin e tyre – sipas një tjetër burimi , mbreti i barabartë me apostujt ishte pagëzuar në Kiev më 987. tani ai rrëzoi tempujt idhujtarë, ndërtoi kisha, mbështeti edukimin e krishterë dhe u bë tepër popullor falë dhembshurisë së tij të skajshme – arrinte të mos gjykonte kriminelët! Organizoi Kishën e tij të sapokrijuar, e cila më 1988 festoi me madhështi mileniumin e saj. Bijtë e tij u bënë shenjtorë Borisi dhe Glebi (24 korrik). Fjeti në 15 korrik të vitit 1015."}]},{"d":16,"m":7,"blocks":[{"t":"intro","x":"Më 16 të këtij muaji, nderojmë kujtimin e atit tonë Athinogjeni, episkop Pidakthi dhe nxënësit e tij: Rigjini, Maksimini, Patrofili, Amoni, Thofrasti, Kleoniku, Petro, Isiki, të cilët u martirizuan në vitet 284-305."},{"t":"li","x":"Kujtimin e dëshmorit Fausti, që u martirizua ndërmjet viteve 249-251."},{"t":"li","x":"Kujtimin e dëshmorit Antioku, vëllai i shën Platonit dhe Qirjakos, i cili ishte xhelat dhe besoi tek Zoti nëpërmjet shën Antiokut. U martirizua në vitin 284-305."},{"t":"li","x":"Kujtimin e 15 000 dëshmorëve, të cilët u martirizuan në Pisidi të Palestinës."},{"t":"li","x":"Kujtimin e dëshmorit Athinogjeni, i cili shkroi himnin: O Dritë Gazmore."},{"t":"li","x":"Kujtimin e Sinodit të Katërt Ekumenik, i cili u bë në Kalqedoni në vitin 451, ku morën pjesë 630 Etër të Kishës."},{"t":"li","x":"Kujtimin e martires së shenjtë Julia e Korsikës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Athinogjeni i Pidhakthoisë dhe dhjetë nxënësit e tij martirë J I pari, me origjinë nga Sevastja (Sivas) e Armenisë (tani në Turqi) u hirotonis episkop i Pidhakthoisë (ose Pidha-kthisë). Vendndodhja e saj është e panjohur për ne. Sidoqoftë qytet me emrin Pidha ekzistonte pothuajse afër Sevastisë. Nga ana tjetër thuhet se ekzistonte edhe qytet tjetër Kloi."},{"t":"p","x":"Pra hierarku u arrestua në kohën e Dioklitianit (282-305) dhe u torturua bashkë me dhjetë nxënësit e tij, prej të cilëve tetë janë të njohur me emra nga shërbesa e tyre. Bëhet fjalë për Riginosin, Maksiminin, Patrofilosin, Amonin, Theofras-tin, Kleonikun, Petron dhe Isikiun. Një informacion i vetëm dhe madje shumë më pas i quan të tjerët: Antiokun dhe Athinogjenin gjithashtu. Në fund iu prenë kokën që të njëmbëdhjetëve. Oshënar Nikodhim agjioriti (14 korrik) në Sinaksarin e tij shton përafërsisht si vijon: “Thuhet se hierodëshmori, duke mos njohur se ishin kapur nxënësit e tij, shkoi në manastirin e tyre dhe nuk gjeti veçse një sor-kadhe, të cilën e kishte rritur atje. E bekoi dhe i uroi që gjuetarët të mos vrisnin fisin e saj. Në vend të saj do të duhej që pasardhësit e kafshës të sjellnin çdo vit një sorkadhe të vogël. Kjo mrekulli ndodh deri më sot [në kohën e shën Nikodhimit i cili fjeti në vitin 1809]. Gjatë panairit të tij në manastir, në veriperëndim të Azisë së Vogël, një sorkadhe lë një sorkadhe të vogël brenda në kishë, atëherë të besimtarët shtrojnë drekë me mishin e saj”!"},{"t":"p","x":"Diçka akoma: Vetëm Nikodhimi përmend kujtimin në të njëjtën datë edhe gjetkë të dëshmorit Athinogjen që përfun-doi në zjarr. Ky shenjtor i dytë nuk ka jetëshkrim, por oshënari thotë se është Athinogjeni që përmend Vasili i Madh (1 janar). E përmend si krijues të himnit mbrëmësor “O dritë gazmore e lavdisë së shenjtë”, të cilën e psali kur mësynte në flakë. Ndërkaq të tjerë përputhin të dy dëshmorët me të njëjtin emër."},{"t":"p","x":"Athinogjeni, greqisht = nga gjini athinase."},{"t":"h","x":"Julia e Korsikës"},{"t":"p","x":"Vinte nga Kartagjena, u kap gjatë invazioneve perse dhe u shit si skllave tek Eusebi, një tregtar sirian pagan. Tentoi shumë herë që ta bënte vajzën të hiqte dorë nga Krishti, por shërbëtorja e Perëndisë, e paqortueshme në punët shtëpiake, qëndronte e patundur për sa i përkiste besimit. Një ditë, Eusebi mori Julian dhe udhëtuan me anije drejt Francës. Sapo arritën në kepin e Korsikës, qëndruan në port dhe Eusebi shkoi në një festë pagane, ndërsa Julia qëndroi në anije dhe vajtonte për këto marrëzira. Qeveritari i vendit Feliks u informua për praninë e skllaves së krishterë dhe i propozoi Eusebit t’i jepte Julian në këmbim të 4 skllaveve të tij më të mira. Pasi Eusebi refuzoi, Feliksi e dehu gjatë festës dhe duke përfituar nga gjumi i tij dërgoi ta merrnin Julian në anije. I propozuan lirinë, nëse do t’u sakrifikonte idhujve. Por ajo u përgjigj: “Jam e lirë, përderisa i shërbej Jisu Krishtit dhe kurrë nuk do ta blej lirinë me çmimin e një mohimi!”. Atëherë qeveritari e dorëzoi në tortura, pastaj e vuri në kryq trupin e saj të shqyer nga druri. Julia tregoi një gëzim të madh që të merrte pjesë në vuajtjet e Shpëtimtarit dhe kur fjeti, shpirti i saj fluturoi në formë pëllumbi. Shumë ëngjëj u shfaqën tek disa murgj që jetonin në ishullin Margarita (Gorgona) që të vinin e të varrosnin denjësisht trupin e saj. Lipsanet i çuan në manastirin e tyre dhe më pas i transferuan në Breshia, nën urdhërin e mbretit lombardian Deziderius më 763. Nderohet si mbrojtësja e Korsikës dhe e Liburnit."},{"t":"h","x":"Sinodi i 4-t Ekumenik"},{"t":"p","x":"Sinodi i 4-t Ekumenik, u mblodh në Kalqedoni në vitin 451, në kohën kur qenë perandorë Markiani dhe Pulkeria. Shkaku i thirrjes së Sinodit ishte herezia e monofizitizmit që përfaqësohej nga Eftikia, i cili thoshte se Jisu Krishti ka vetëm një natyrë, atë Hyjnore."},{"t":"p","x":"Sinodi u mblodh më 8 tetor të vitit 451 në Kishën e martires së shenjtë Efthimia në Kalqedoni, i kryesuar nga vetë perandori Marcian. Në sinod merrnin pjesë përfaqësues të kishave të Lindjes dhe Perëndimit. Numri i etërve të shenjtë të sinodit ishte 630, të cilët dekretuan 30 kanone. Sinodi përcaktoi Krishtin si Perëndi të përsosur dhe njeri të përsosur në një person. Pra në Jisu Krishtin janë dy natyra të plota: Natyra Hyjnore dhe Natyra Njerëzore. Të dy këto natyra janë të papërzjera, të pandryshueshme dhe të pandara."},{"t":"p","x":"Disa kisha të krishtera nuk e pranuan Sinodin e 4-t Ekumenik që u mbajt në Kalqedoni. Këta të krishterë u quajtën monofizitë, që do të thotë se pranojnë vetëm një natyrë të krishtit. Për këtë shkak ata u shkëputën nga Kisha Orthodhokse. Këto janë kishat kopte, armene dhe etiopiane. Shpresojmë se një ditë kjo mosmarrëveshje do të zgjidhet."}]},{"d":17,"m":7,"blocks":[{"t":"intro","x":"Më 17 të këtij muaji, nderojmë kujtimin e dëshmores Marina, e cila u martirizua në Pisidi të Antiokisë në vitet 268-270."},{"t":"li","x":"Kujtimin e dëshmorëve Sperati dhe Veroniku."},{"t":"li","x":"Kujtimin e shën Efrasit, episkop në Jonopoli."},{"t":"li","x":"Kujtimin e oshënarit Irinarku, igumen i një manastiri në Solovski të Rusisë në vitin 1628."},{"t":"li","x":"Kujtimin e oshënarit Leonidha, themelues i Skitit të Shën Marisë, afër qytetit Ustiugut në Rusi në vitet 1551-1654."},{"t":"li","x":"Transferimi i lipsaneve të shën Llazarit të malit Galesio."},{"t":"li","x":"Kujtimin e shën Leonidhës, igumen i Manastirit të Ustnedumskut."},{"t":"li","x":"Kujtimin e shën Speratit dhe shokëve të tij: Nartzali, Citini, Veturi, Feliksi, Akilini, Laetantiu, si dhe të grave Januaria, Gjenerosa, Vestia, Donata dhe Sekunda, të martirizuara në Skili."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Marina virgjëresha, martire"},{"t":"p","x":"Fëmijë i vetëm i priftit të idhujve, Edhesiut, lulëzoi në kohë të Klaudit II (268-270) në Pisidhi, në mes të Azisë së Vogël. Dymbëdhjetëvjeçare ngeli jetime dhe i ati ia dha një gruaje që të kujdesej për të. Vajza e mençur ose nga ajo ose nga gjitonët u tërhoq në Krishterim - kjo për hidhërim të madh dhe inatosje të egër të Edhesiut - dhe dëshiroi shumë martirizimin."},{"t":"p","x":"Dikur, duke vajtur në kopenë e të atit, u takua me qeveritarin, të cilit i bëri shumë përshtypje freskia e 15 vjetëve të saj. E dëshiroi për grua, por ajo i zbuloi besimin e saj. U burgos dhe ditën tjetër trimëresha nuk flijoi, megjithë komplimentet, kërcënimet dhe propozimin për martesë me të. Pra e shtrinë përdhe dhe e rrahën me shkop sa toka u skuq nga gjaku i saj. E varën dhe e shqyen, pastaj e burgosën duke e lënë pa ushqim e mjekim, kështu, ajo ish - e bukura, u kthye në një grumbull mishrash pa formë."},{"t":"p","x":"Djalli i shndërruar në një gjarpër të madh bëri sikur e gëlltiti, por e zhduku me lutje. Erdhi përsëri si arap dhe më vonë si qen, por ajo e eliminoi duke e rrëmbyer dhe goditur me një çekan që u gjend atje. Një herë tjetër e rrahu me kamxhik dhe menjëherë u shfaq një kryq shumë i ndritshëm dhe një pëllumb, i cili i paralajmëroi çmimin, ndërkohë iu shëruan plagët."},{"t":"p","x":"Të çuditur, e varën përsëri, e dogjën me pishtarë dhe e zhytën në ujë që të mbytej - diçka si pagëzimi që aspironte. Pëllumbi u paraqit me kurorë në gojë dhe u ul mbi kokën e së resë, që doli nga uji e liruar nga prangat."},{"t":"p","x":"Atëherë u ndriçuan shumë njerëz, dhe për këtë u prenë kokën të gjithëve, si dhe më pas atletes (martires)."},{"t":"p","x":"Më përpara ishte lutur dhe kishte marrë vesh që i qëndronte afër Zoti. Lipsani më vonë u transferua në Konstandinopojë, kurse më 1230 u rrëmbye në Venecia prej kryqëzatave."},{"t":"p","x":"Shenjtja, që disa herë quhet Margarita, nderohet si mbrojtëse dhe shëruese e fëmijëve."}]},{"d":18,"m":7,"blocks":[{"t":"intro","x":"Më 18 të këtij muaji, nderojmë kujtimin e dëshmorit Emiliani, i cili u martirizua në Durostorum të Bullgarisë në vitin 361."},{"t":"li","x":"Kujtimin e dëshmorëve Pavli, Valentini dhe Thei, të cilët u martirizuan në Dhiokeraria."},{"t":"li","x":"Kujtimin e dëshmorit Jakinthi nga Amastridha e Pontit."},{"t":"li","x":"Kujtimin e oshënarit Pamvoi nga Egjipti në shekullin e 4-t."},{"t":"li","x":"Kujtimin e shën Athanasit në Klisma."},{"t":"li","x":"Kujtimin e martirit të shenjtë Markeli."},{"t":"li","x":"Kujtimin e martirëve të shenjtë Dhasi dhe Maroni, të cilët mbaruan me shpatë."},{"t":"li","x":"Kujtimin e pohuesit Joani, mitropolit i Kalqedonisë në shekullin e 8."},{"t":"li","x":"Kujtimin e atit tonë Stefani II, patriark i Konstandinopojës në vitet 925- 928."},{"t":"li","x":"Kujtimin e daljes së lipsanit të shën Llazarit nga mali Galic në Azinë e Vogël."},{"t":"li","x":"Kujtimin e oshënarit Onesifor në Qipro."},{"t":"li","x":"Kujtimin e oshënarit Joan, i shumëvuajturi i Lavrës së Kievit në vitin 1160."},{"t":"li","x":"Kujtimin e oshënarit Pamvoi i binduri në Lavrën e Kievit në shekullin e 13."},{"t":"li","x":"Kujtimin e oshënarit Leoni, igumen në Manastirin e Vologdës në Rusi."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Joani i shumëvuajturi i Lavrës së Shpellave të Kievit"},{"t":"p","x":"Ky atlet i virgjërisë jetoi për vite me radhë i mbyllur në shpellën e shën Andonit të Kievit. Një ditë, një nga vëllezërit, i cili po provohej ashpër nga demoni i imoralitetit, deri në atë pikë sa donte të braktiste manastirin, shkoi t’i kërkonte ndihmë shenjtit. Atëherë Joani i tregoi historinë e tij:"},{"t":"p","x":"“Kur erdha në këtë manastir, - tregon ai, - pata tundime trupore. U përpoqa të luftoja që të qëndroja dy-tri ditë, madje një javë pa ngrënë duke e privuar veten nga çdo pije, duke vigjiluar natën, por asgjë. E durova këtë torturë për tre vjet, shkova në shpellën e shën Andonit, pranë varrit të tij për t’u lutur natë e ditë. Dëgjova atëherë zërin e shenjtit, i cili më këshilloi të qëndroj atje i mbyllur, në heshtje e lutje, që të çlirohesha nga turbullimet e armikut. Qëndrova pra atje. Tridhjetë vjet kaluan, por vetëm kohët e fundit jam paqësuar. Gjatë gjithë këtyre viteve nuk kam pushuar së luftuar kundër mendimeve të papastra me kreshmë e agripni. Hoqa gjithçka nga trupi, u ngarkova me hekura, në të ftohtë e lagështirë, por ky asketizëm ishte i pamjaftueshëm. Kështu kur afroi Kreshma e Madhe, hapa një gropë në tokën me rërë të shpellës dhe e varrosa trupin tim duke lënë jashtë vetëm kokën dhe krahët. Qëndrova pa lëvizur gjatë gjithë kreshmës duke duruar kryengritjet e tmerrshme të demonit. Këmbët m’u rënduan kaq shumë, sa dukej se kockat e mia do të thyheshin. Ndjeja një përvëlim të padurueshëm, por shpirti ndihej i lehtë dhe gëzohej që çlirohej nga papastërtia, sepse preferova më shumë të vdisja që të fitoja Krishtin, sesa të dilja nga kjo gropë e të bëhesha pre e djallit. Në fillim të Kreshmës së Madhe, një dragua i tmerrshëm, nga goja e të cilit dilnin flakë, u lëshua të më shqyente, por e largova me shenjën e kryqit dhe me lutjen e Jisuit. Sulmet përsëriteshin gjatë gjithë javës dhe natën e Ngjalljes ai u hodh mbi mua duke hapur gojën e duke më djegur mjekrën e flokët, ashtu siç më shikon tani. Po në të njëjtën kohë, një dritë rrezatuese ndriti shpellën dhe dragoi u zhduk. Me hirin e Perëndisë nuk e pashë më që atëherë. Një zë më thirri: “Joan, të erdha në ndihmë, por tani vigjilo mbi veten që të mos vuash edhe më keq në jetën tjetër”. I kërkova Zotit se përse më kishte lënë të vuaja kaq kohë nga djalli. Ai m’u përgjigj: “Të kam provuar në masën që ti mund të mbash dhe të bëra që të kalosh në furrën e tundimeve që të shfaqesh para Meje i pastër, si ari i kulluar”. Dhe Ai më këshilloi t’i lutem shën Moisi hungarezit për t’u çliruar nga tundimi trupor. Për sa kohë që kam kërkuar ndërmjetimet e këtij shenjti, një dritë e pakrijuar më përshkonte dhe qëndron deri tani, saqë nuk kam nevojë për kandil që të më ndriçojë”."},{"t":"p","x":"Pasi përfundoi historinë e tij, u kthye drejt murgut të sprovuar dhe i tha:"},{"t":"p","x":"“Vëlla, vetë ne ia nënshtrojmë mendjen sensualitetit dhe duke mos pasur pendim, Zoti lejon prova”. I tregoi një pjesë të lipsanit të shën Moisi hungarezit dhe i kërkoi ta vendoste mbi trup e të thërriste emrin e shenjtit. Në atë çast vëllai u çlirua përgjithnjë nga kryengritjet e trupit."},{"t":"p","x":"Joani fjeti në paqe pas pak kohësh, më 18 korrik 1160. U varros në gropën ku u varros vetë kur ishte ende gjallë nga dashuria për virgjërinë dhe ky varr u bë burim shërimesh."},{"t":"h","x":"Pamvoi, oshënar"},{"t":"p","x":"Ndriçoi në Nitria, në jug të Aleksandrisë.Të dhëna për të ekzistojnë në librat e Lavsaikut, Jerondikonit dhe Evergjetinosit: U luftua prej blasfemisë, por një zë ia karakte-rizoi si mëkat të huaj; le të mos dekurajohej. - Për tre vjet lutej që të mos lavdërohej në tokë, sa që vetëtinte verbue-shëm! - Meqë shën Melania (31 dhjetor) i ofroi atje në Nitri, argjend të bollshëm, bëri urimet e rastit por nuk denjoi që ta shohë. Ajo u mërzit: “- Jeront janë 150 kile! - E di Perëndia, bija ime...” Dhe urdhëroi ikonomin që ta ndajë të gjithë në manastire të varfra. - Ushqehej vetëm prej prodhimeve të dorës së tij. - Sa herë që e pyesnin për probleme në lidhje me Shkrimin ose të tjera, përgjigjej pas shumë kohe! Në meditim dhe saktësi ia kalonte edhe Andonit të Madh (17 janar). Kështu që kurrë nuk u pendua për fjalët që tha. Ishte dhe mësues i “Vëllezërve të gjatë (= të trungjeve të lartë)”. - Rekomandonte të ruhej e pastër dhe e pafajshme ndërgjegjja ndaj të afërmit. - Theksonte bindjen."},{"t":"li","x":"Rasot i donte kaq të thjeshta saqë nëse i ekspozonin për tri ditë asnjë të mos i merrte!- Në Aleksandri ku e ftoi Athanasi i Madh (18 janar) pa një lavire dhe lotoi për humbjen e saj, sepse edhe ai vetë nuk ishte i pëlqyeshëm ndaj Zotit aq sa e gjora ishte e pëlqye-shme ndaj të pamoralshmëve... - Nxiti laikët të puthnin mur-gjit përderisa gojët e tyre ishin të shenjtëruara prej lutjes.- Demonët që t’i shkaktojnë shpërndarjen e mendjes përpi-qeshin dikur gjoja duke u munduar shumë, të ngrinin një pupël! Qeshi, pra ata gëzuan se triumfuan, por ai u sqaroi se pëlqeshte dobësinë e tyre. - Kur i erdhi ava Piori (17 qershor), kishte edhe ushqimin e tij, bukën e tharë, “që të mos i bëhej barrë”. Kur ia ktheu vizitën, kishte bukën e tij të tharë, madje të lagur!"},{"t":"p","x":"Ndërroi jetë 70 vjeç (më 417 siç mendohet) pa u sëmurur dhe duke pandehur se nuk ishte as fillestar në virtyt. Pak para fjetjes së tij i dhuroi për kujtim Paladhit shkrimtarit të Lavsaikut, një shportë, që porsa kishte thurur. E varrosi Mela-nia që mbajti edhe shportën."}]},{"d":19,"m":7,"blocks":[{"t":"intro","x":"Më 19 të këtij muaji, nderojmë kujtimin e oshënares Makrina, motra e shën Vasilit të Madh, e cila jetoi në Pont në vitet 327-379."},{"t":"li","x":"Kujtimin e oshënarit Dhiosi nga Antiokia, jetoi si murg në Konstandinpojë. Fjeti në vitet 406-425."},{"t":"li","x":"Kujtimin e oshënarit Diokli në shekullin e 4-t."},{"t":"li","x":"Kujtimin e atit tonë Theodhori, kryepiskop në Edesa të Sirisë në shekullin e 9."},{"t":"li","x":"Kujtimin e martirit të shenjtë Mikail Savaiti."},{"t":"li","x":"Kujtimin e Grigor pohuesit, episkop i Panidit në shekullin e 8-9."},{"t":"li","x":"Kujtimin e Romanit, princi i Riazanit."},{"t":"li","x":"Kujtimin e oshënarit Pais nga Lavra e Kievit të Rusisë në shekullin e 14."},{"t":"li","x":"Kujtimin e shën Stefanit, mbretit të Serbisë (1427) dhe nënës së tij Milica."},{"t":"li","x":"Kujtimin e gjetjes së lipsanit të shën Serafimit të Sarovit dhe kanonizimi i tij (1903)."},{"t":"end","x":"Me ndërmjetimet e Shenjtorëve të tu o Krisht Perëndi, Mëshirona. Amin."},{"t":"h","x":"Oshënare Makrina dhe katër shoqet e saj të asketizmit"},{"t":"p","x":"Ishte motra e shën Vasilit të madh (1 janar) dhe shën Grigorit të Nises (10 janar). Ishte më e madhja nga dhjetë fëmijët e kësaj familjeje të shenjtë. Kur ajo u lind (327), tregohet se një njeri mistik iu shfaq tri herë nënës së saj duke e urdhëruar që t’i jepte fëmijës emrin e shën Theklës, martires së parë dhe modelit të virgjëreshave të krishtera (24 shtator). Megjithëse fëmija mori emrin e gjyshes së saj Makrina, e cila kishte qenë nxënëse e shën Grigor Çudibërësit (17 nëntor), dhe kishte jetuar fshehur në pyjet e Pontit gjatë persekutimeve të mëdha. E ëma u kujdes për edukimin e saj, jo me gjëra të kota, por me urtësinë e Shkrimeve të frymëzuara. Kur u rrit bukuria e saj nuk mund të mbetej e fshehur, dhe në moshën 12 vjeçare, i ati e fejoi me një të ri me emër të mirë që kishte mbaruar studimet dhe kishte premtuar se do të priste Makrinën derisa të mbushte moshën e duhur për martesë. Megjithatë, para martesës Perëndia e mori të riun dhe kështu Makrina mundi të arrinte dëshirën e saj: të jetonte një jetë në pastërti. iu ofruan shumë raste për martesë, por ajo e konsideroi veten si vejushë, ndonëse nuk kishte bërë më përpara jetë bashkëshortore. Qëndroi bashkë me nënën e saj dhe ndihmoi në edukimin e vëllezërve dhe motrave më të vegjël. Pas vdekjes së atit të saj (341), ai drejtoi pronat në Pont, Kapadhoki dhe në Armeni. Së bashku me nënën e saj, u shtruan në asketizëm dhe Makrina ishte për të gjithë mbrojtje, mësuese dhe model i virtytit. Emelia, nëna e saj, kur u lirua nga edukimi i fëmijëve, e shndërroi shtëpinë në manastir. Shërbyeset u bënë shoqe asketizmi dhe Makrina arriti ta bindte Vasilin, i cili u kthye nga Athina pas studimeve të shkëlqyera që kreu atje, t’i përkushtohej jetës engjëllore. Pranë manastirit të grave, i cili rritej , u formua edhe një komunitet burrash i drejtuar nga vëllai më i ri i Makrinës Petro, episkopi i ardhshëm i Sevastisë. Shën Nafkrati (8 qershor) u tërhoq në një vend të shkretë, - ku më pas do të shkonte edhe shën Vasili, - në bregun e kundërt të Irisit, dhe plotësonte nevojat e etërve me të vjetër me gjuetinë e tij. Të çliruara nga zinxhirët e botës, Makrina bashkë me vajzat e tjera jetonin një jetë engjëllore. Nuk kishte mes tyre zemërim, smirë, urrejtje, arrogancë, apo diçka tjetër të ngjashme me to. Jetonin në vetëpërmbajtje larg dëshirës për lavdi. Jetonin me punën e duarve të tyre. Makrina u sëmur nga një tumor në gji. Me gjithë përgjërimet e nënës së saj, ajo refuzoi të merrte mjekimet tek mjeku duke e gjykuar si jo të pëlqyeshme zbulimin e pjesës së trupit të saj. gjatë gjithë natës qëndronte në lutje dhe e mjekonte plagën me baltën e përzier me lotët e saj. Në mëngjes i kërkoi nënës së saj të bënte kryqin mbi plagën, dhe qelbi u zhduk duke mbetur vetëm një shenjë e plagës. Kishte arritur në një vetëpërmbajtje kaq të madhe sa kur vdiq Nafkrati në një aksident në gjueti, ajo ishte një mbështetje e fuqishme për nënën. Gjithashtu edhe kur vëllazërinë e goditën vdekje të njëpasnjëshme. Në kohën kur Kapadhokinë e goditi uria, manastiri i tyre u bë një strehë ngushëllimi për të gjithë popullin përreth. Lutja e shën Makrinës siguronte rezerva të cilat i shpërndanin tek nevojtarët. Pak pas vdekjes së shën Vasilit, shën Grigori i Nisës mori vesh për gjendjen shumë të rëndë të Makrinës dhe pas nëntë vjet mungese, ai shkoi dhe e vizitoi. E gjeti të shtrirë në një shtrat në ethe, megjithëse shpirti sodiste të mirat qiellore. Në çdo çast fliste për dashurinë e Dhëndrit të saj, Krishtit. Kur ndjeu të afronte vdekja, psherëtiu dhe u lut: “Zot, ti e zhduke prej nesh frikën nga vdekja. Ti hape pas kësaj jete këtu në tokë fillimin e jetës së vërtetë. Ti i jep për pak kohë prehje trupit dhe e zgjon përsëri me tingullin e trumbetës. Ti e vendos përsëri përtokë baltën me të cilën na gatove dhe vjen ta marrësh duke e transformuar në pavdekësi dhe bukuri atë që është e vdekshme. Ti na çlirove nga mallkimi i mëkatit. Ti e shtype kokën e dragoit që e rrëzoi njeriun në humnerën e mosbindjes, duke e kapur për fyti. Ti na hape rrugën e ngjalljes si i shembe dyert e ferrit dhe e shfuqizove atë që mbretëronte mbi vdekjen. Ti u dhe të gjithë atyre që të kanë frikë shenjën e Kryqit tënd të shenjtë për të shuar armikun dhe për t’u dhënë siguri jetëve tona. O Perëndi i përjetshëm! Tek ti u dhashë që në gji të nënës sime, ty të deshi shpirti im me tërë fuqinë, ty ta kushtova tërë trupin dhe shpirtin tim që nga rinia dhe deri në këtë çast, vendos pranë meje një engjëll drite që do të më drejtojë në vend freskie, atje ku gjendet uji i prehjes, në gji të Etërve të shenjtë. Ti që e shove flakën e shpatës dhe e more në parajsë kusarin që u kryqëzua me ty dhe u fal nga mëshira jote, kujtohu edhe për mua në Mbretërinë tënde, sepse edhe unë u kryqëzova me ty, trupin me frikën tënde dhe u mbusha me frikë nga porositë e tua. Mos më ndaj nga të zgjedhurit e tu nga me humnerën e pakapërcyeshme. Armiku xheloz të mos më pengojë në udhë dhe mëkati im mos dalë përpara teje, për shkak të natyrës sonë të dobët, rashë në mëkat me mendim, fjalë dhe vepër. Ti që ke pushtet mbi tokë të falësh mëkatet, falmë edhe mua që të marr frymë dhe kur të ndahem nga ky trup të dal para teje me shpirt të paqortueshëm dhe të panjollë, si temjani përpara teje.”"},{"t":"p","x":"Me këto fjalë, shenjtorja bëri kryqin mbi sytë, buzët, gojën dhe zemrën. Mori pjesë në heshtje në shërbesën e mbrëmjes dhe me një psherëtimë të fundit u preh. Gjatë varrimit që u kryesua nga shën Grigori, bukuria shpirtërore e shën Makrinës shkëlqente tërë trupin. U varros në Ibora, në varrin ku preheshin prindërit e saj në kishën e Dyzet Martirëve."}]},{"d":20,"m":7,"blocks":[{"t":"intro","x":"Më 20 të këtij muaji, nderojmë kujtimin e ngritjes në qiell të profetit Ilia në vitin 854 para Krishtit."},{"t":"li","x":"Kujtimin e Inagurimit të Kishës së Manastirit të Shën Joan Pararendësit në Studion të Konstandinpojës në vitin 467."},{"t":"li","x":"Kujtimin e etërve të shenjtë Ilia I-të, patriark i Jerusalemit, Flaviani II-të, patriark i Antiokisë."},{"t":"li","x":"Kujtimin e atit tonë të shenjtë Abraham i Galicit."},{"t":"li","x":"Kujtimin e shën Ilia Çavçavadze (i drejti) në Gjeorgji."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Ilia, profet"},{"t":"p","x":"Jetëshkrimi i tij gjendet kryesisht në librin e Mbretërve III, kap.17-20 dhe Mbretërve IV, 1-2 [sipas një emërtimi tjetër Mbretërve I dhe II]."},{"t":"p","x":"U lind në fshatin e Cisjordanisë, Thesvë (nga ku dhe Thesvit), dhe veproi kryesisht në kohën e mbretit Ahaav 873-854 para Kr.). Ky mbret i Izraelit Verior ishte martuar me princeshën idhujtare Jezavel, e cila vrau profetët, përndoqi besimtarët dhe imponoi adhurimin e Vaalit."},{"t":"p","x":"Kështu, Ilia ose Iliu (hebraisht = Perëndia im është Zoti), me zellin e zjarrtë për të Lartin, i parathotë për një shkatërrim trevjeçar nga thatësira. Më pas ai shkon në shkretëtirë, ku e ushqejnë korbat dhe më vonë shkon në Sarepta, në shtëpinë e një vejushe mikpritëse, Sarafthia (të Dielën e Paraetërve - para Krishtlindjeve)."},{"t":"p","x":"Pra, gjatë thatësirës dhe urisë trevjeçare, i Larti i thotë që të shkonte të banonte pranë vejushës Sarafthia, domethënë që banonte në qytetin bregdetar Sarepta të Sidonit në Fenikë, në veri të Palestinës. Ajo do ta ushqente me porosi nga lart."},{"t":"p","x":"Dhe vërtet, në portat e qytetit e sheh gruan duke mbledhur dru. I thërret që t’i jepte ujë për të pirë. Duke shkuar për t’i sjellë ujë, ai i kërkon edhe bukë. Ajo, në vend që të zemërohej me hebreun kërkues, betohet se ka grushtin e fundit të miellit në magje dhe pak vaj në enë. Me drutë e holla do të piqte një bukë për të ngrënë me fëmijët e saj. Më pas do të kishin përsëri uri dhe do të vdisnin nga uria."},{"t":"p","x":"Por ai i jep kurajo. Le të gatuante më parë një bukë të vogël për të, pastaj për familjen e saj, sepse Zoti premtoi që të mos shteronin dy enët, derisa të binte shi përsëri. Dhe kështu u bë!"},{"t":"p","x":"Më pas, i sëmuret rëndë i biri derisa dha shpirt... E ëma e brengosur iu ankua: “O njeri i Perëndisë, erdhe në shtëpinë time dhe i Gjithëpushtetshmi e vuri re dhe kujtoi mëkatet e mia dhe vrau frytin tim”."},{"t":"p","x":"Shenjti ia mori nga prehri, u ngjit në dhomën e rregulluar mirë që i kishte lëshuar, e shtriu në krevatin e vet dhe u lut me zjarr. Më pas fryu tri herë dhe u lut që të ringjallej. Fëmija thirri! E zbriti poshtë dhe ia dha nënës së tij duke thënë: “Ja, yt bir është gjallë!”. Ajo e mahnitur tha: “Tani u binda plotë-sisht që ti je i dërguari i Perëndisë!” ."},{"t":"p","x":"Gojarti i shenjtë (13 nëntor) e lumuron gruan si më të lartë në lëmoshë dhe në mikpritje se sa Abrahami që ishte shumë i pasur (9 tetor), sepse përveçse që ishte e varfër, ishte prej kombi tjetër, e ve, me fëmijë, ndërsa Thesviti ishte i huaj."},{"t":"p","x":"Pas tre vjetësh (rreth vitit 857), profeti turpëroi publikisht në malin Karmel katërqind profetët e Vaalit: Lutet dhe arrin të bëjë atë që nuk mund të arrinin pseudoprofetët. Pra, zjarr bie nga qielli dhe djeg flinë e tij. Populli i entuziazmuar besoi tek Perëndia e Thesvitit, të katërqindët vriten dhe profeti lajmëron ardhjen e shiut, që vërtet erdhi."},{"t":"p","x":"Duke iu larguar inatit të mbretëreshës Jezavel, fuqizohet nga ushqimi që i sollën engjëjt, dhe pas dyzet ditë rruge dhe pa ngrënë (!) arrin në Malin e Sinait. Aty i shfaqet Jahveu, si një fëshfëritje flladi."},{"t":"p","x":"I paratha për fundin tragjik të Ahaavit dhe Jezavelës, e cila kishte vënë njerëz që të shpifnin dhe kështu të ekzeku-tonin dikë, me qëllim që vreshti i tij t’i kalonte bashkëshortit të saj, gjë që u bë."},{"t":"p","x":"Ai dogji me zjarr qiellor dy regjimente me pesëdhjetë ushtarë secili me tendenca armiqësore. Thau tej për tej ujërat e lumit Jordan, dhe në kohën e mbretit Joram (853-842) u ngjit në qiell mbi një qerre të zjarrtë! U shfaq pranë Krishtit gjatë Metamorfozës së Tij (Mat.17.1-9 etj.). Gjithashtu, ai ka qenë protipoza e Pararendësit (7 janar) në jetën eremite, në veshjen me rroba të ashpra dhe në predikimin për pendesë."},{"t":"p","x":"Nxënës i tij ishte profet Eliseu (14 qershor), ndërsa Mala-kia 4.4 dhe Mat.17.10-13 i referohen shfaqjes së tij para Ar-dhjes së Parë dhe asaj të Dytë të Krishtit."}]},{"d":21,"m":7,"blocks":[{"t":"intro","x":"Më 21 të këtij muaji, nderojmë kujtimin e oshënarit Simeoni, i marrë për Krishtin dhe Joanit bashkasket i tij nga Edesa e Sirisë në shekullin e 6."},{"t":"li","x":"Kujtimin e tre dëshmorëve nga Melitina."},{"t":"li","x":"Kujtimin e dëshmorëve Theofili, Trofimi dhe 13 dëshmorë të tjerë."},{"t":"li","x":"Kujtimin e dëshmorëve Justi dhe Mattheu, të cilët mbaruan me shpatë."},{"t":"li","x":"Kujtimin e dëshmorit Eugjeni."},{"t":"li","x":"Kujtimin e martirëve të shenjtë Theodhori dhe Gjergji."},{"t":"li","x":"Kujtimin e atit të shenjtë Partheni, episkop i Radobisdionit."},{"t":"li","x":"Kujtimin e oshënarit Onufri i heshturi dhe i Onesimit të mbyllur në Lavrën e Shpellave të Kievit."},{"t":"li","x":"Kujtimin e martirit të shenjtë Viktori i Marsejës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"p","x":"Kujtimin e etërve Simeon i Emesit, i marrë për Krishtin dhe i shokut"},{"t":"h","x":"të tij të asketizmit Joan"},{"t":"p","x":"Që të dy ishin nga Siria dhe jetuan në kohën e mbretërimit të Justinianit: Joani ishte 22 vjet dhe sapo ishte martuar, ndërsa Simeoni ishte 24 vjet dhe nuk kishte familje, veç nënës së tij të moshuar. Lidhën miqësi së bashku gjatë një pelegrinazhi që bënë në Vendet e shenjta me rastin e Lartësimi të Kryqit të çmuar. Kur arritën në Jeriko, Joani i tha shokut të tij se njerëzit që jetonin në manastiret pranë Jordanit ishin të ngjashëm me engjëjt e Perëndisë, dhe duke i treguar rrugën që të çonte atje, ai tha: “Ja rruga që të çon në jetë”. U kthye mbrapa dhe me gisht tregoi rrugën e gjerë me njerëz dhe tha përsëri: “Ja udha që të çon në vdekje”. U lutën dhe hodhën në short rrugën që duhet të ndiqnin, kështu shkuan në manastiri i Shën Gjerasimit me gëzim duke harruar çdo përkujdesje të botës. Igumeni i manastirit, i lumuri Nikon, kishte marrë vesh për ardhjen e tyre me anë të një zbulimi, shkoi para portës iu uroi mirëseardhjen dhe iu profetizoi të ardhmen. Me kërkesën e tyre, Nikoni i qethi murgj menjëherë dhe iu veshi skimën engjëllore duke i futur në jetën e re me këtë pagëzim të dytë. Nga frika se mos e humbisnin zellin hyjnor që ua digjte shpirtrat dhe lavdinë e veshjes engjëllore, ata vendosën që të largoheshin nga manastiri pas dy ditësh dhe të ndaheshin nga njëri-tjetri që të jetonin në shkretëtirë të braktisur në përkujdesjen e Perëndisë. Morën udhën në drejtim të Detit të Vdekur dhe ndaluan në një vend të shkretë që quhej Arnonas, ku gjetën disa rezerva të një eremiti që kishte vdekur pak ditë më përpara. Sa filluan betejat e tyre shpirtërore në vetmi, u sulmuan nga Kujtimin e të afërmve të tyre: Joanit i kujtohej gruaja dhe Simeonit nëna. Të shtypur nga këto mendime dhe nga plogështia, ata ishin gati ta braktisnin luftën, por sa herë që kujtonin skimën që kishin veshur dhe ati i tyre shpirtëror që u dilte në ëndërr, merrnin kurajë dhe këmbëngulnin. Qëndruan në qeli të ndara, dhe kur plogështia i bezdiste luteshin së bashku. Tregoni vegimet e njëri-tjetrit dhe gëzoheshin që kishin braktisur gjithçka për Perëndinë. Përparuan kaq shumë në jetën shpirtërore sa për pak vjet u bënë të denjë për vizitat e Perëndisë dhe për mrekulli. Kur kaluan tridhjetë vjet në shkretëtirë dhe kishin arritur gjendjen e papasionshmërisë, Simeoni i propozoi mikut të tij ta braktisnin shkretëtirën dhe të shkonin në botë të shpëtonin njerëz të tjerë. Joani mendoi se miku i tij ishte bërë viktimë e një vizioni demoniak, e qortoi dhe i kujtoi premtimin që i kishin bërë njëri-tjetrit se kurrë nuk do të ndaheshin. Por asnjë argument nuk e bindte Simeonin, sepse kuptoi se kjo vinte nga një frymëzim hyjnor. Joani e la të nisej, dhe thanë se përsëri do të takoheshin para fjetjes së tyre. Simfoni bëri një pelegrinazh në Jerusalem, dhe si u lut për tri ditë atje, u nis për në Emesa, me vendimin se do shtirej si i marrë. Ishte i pari që e përqafoi këtë lloj asketizmi të rrezikshëm, pra marrëzinë për Krishtin. Duke zbatuar fjalë për fjalë fjalët e apostullit kur thotë: “Ai që do të bëhet i urtë le të bëhet i marrë në këtë botë” (I Kor. 3,18), qëllimi i tij ishte të shpëtoheshin shpirtra nëpërmjet shtirjeve të llogaritura, qoftë me anë të mrekullive, qoftë me fjalë për ndërtim ose profetike. Mbi të gjitha, ai u përpoq të qëndronte i fshehur dhe i panjohur nga njerëzit, që të largohej nga çdo lavdi e nderim. Hyri në qytetet duke lidhur në rripin e tij kufomën e një qeni dhe fëmijët e shkollës e tallnin. Të nesërmen, që ishte ditë e diel, hyri në kishë dhe filloi të shuante qirinjtë duke lëshuar arra mbi flakët. Donin ta dëbonin, por hipi në amvon dhe i gjuante gratë me arra. Përfundimisht e hodhën jashtë, ku përmbysi tavolinat e pastiçierëve. Një tregtar pitesh e mëshiroi dhe i sugjeroi të mbante tabakanë tij, por Simeoni i shpërndau gjithë çka ai kishte tek kalimtarët, hëngri edhe për vete sepse kishte një javë që agjëronte. Tregtari e kapi Simeonin dhe e rrahu. Kur erdhi mbrëmja, Simeoni mori karbon dhe ndezi temjan në dorë, kur gruaja e tregtarit e pa këtë, shenjti u shtir se gjoja u dogj, duke i futur thëngjijtë në pallton e tij që nuk po digjej. Ai bëri të mundur kthimin e tregtarit, i cili ishte nxënës i Severit të Antiokisë, duke dëbuar prej tij një demon. Më pas u vu në shërbim të pronarit të një kabareje, i cili ishte mizor me të dhe pa mëshirë, megjithëse shenjti e kishte shtuar klientelën. Një ditë, ai e dënoi dhunshëm Simeonin, i cili kishte thyer një kupë vetë. Por kur pa gjarprin që e kishte hedhur helmin e në gotën që theu shenjti, ai derdhi gjithçka që kishte ena, duke u përpjekur të vriste zvarranikun. Që atëherë, padroni i tij e konsideronte si një shenjtor, por kur Simeoni u shtir se do të përdhunonte gruan e tij, i llahtarisur nga britmat e së shoqes, ai e dëboi shenjtin duke e qëlluar. Njeriu i Perëndisë jetonte në mes të qytetit pa pasione. Kishte fituar dhuratën e kreshmës, sepse gjatë Kreshmës së Madhe, rrinte pa ngrënë, por kur vinte e Enjtja e Madhe, ulej tek pastiçieri dhe gllabëronte tërë ëmbëlsirat që të shikonte nëse do skandalizoheshin ata që mendonin mirë. Herë të tjera, pasi e kalonte tërë javën në agjërim, hante mish në sytë e të gjithëve. Një ditë, bëri që t’u shtrembëroheshin sytë disa vajzave që po talleshin me të, por pastaj i shëroi, por disa nuk i shëroi sepse mësoi se më përpara ato kishin rënë në imoralitet. Të dielën qëndronte në dalje të kishës dhe hante salçiçe, të cilat i kishte varur si litar përreth qafës. Një herë paralizoi dorën e një zhongleri që e qëlloi me gur, por e dhuroi duke iu shfaqur në ëndërr dhe i premtoi se do ta braktiste këtë zanat. Një herë tjetër godiste me dru shtyllat enjë shkolle duke paralajmëruar në këtë mënyrë tërmetin që do të shkatërronte qytetin e Antiokisë (588); kur tërmeti ra, asnjë nga kolonat që shenjti kishte prekur nuk u shemb. Para se të binte epidemia e murtajës, ai përqafoi fëmijët që do të prekeshin nga kjo duke iu uruar një udhëtim të mbarë. Hynte shpesh në familjet e të pasurve që të hante, dhe shtirej se kishte përqafuar shërbëtoret atje. Njëra prej tyre e akuzoi shenjtin se kishte mbetur me barrë, dhe ai u kujdes për të gjatë shtatzënisë, por kur ajo lindi, fëmija zbuloi emrin e babait të vërtetë. Shëroi shumë të demonizuar, megjithëse shtirej se ishte si ata. Një artizan jude e pa të rrethuar nga dy engjëj; ai donte t’ia tregonte këtë, por shenjti u shfaq në ëndërr dhe ia vulosi gojën. E njëjta gjë ndodhi me të gjithë ata që donin t’i vinin në dukje virtytet e tij. Denonconte krimet e njerëzve, vjedhjet, paturpësitë, me qëllim që t’u jepnin fund paligjësive banorët e Emesit. Nuk kishte asgjë në këtë botë, lutej gjatë gjithë natës në një kasolle. Nuk kishte mjekër dhe flokë, gjë që e bënte të ishte i privuar nga respekti që nxit paraqitja e një murgu. Nga goja e tij dilte një erë e mirë, por kur njeriu me të cilin fliste e kuptonte këtë dhe e shpallte tek të tjerët, shenjti e kërcënonte me tortura të tmerrshme në jetën e ardhshme. Dy ditë para se të largohej nga kjo botë, Simeoni ia tregoi gjithë jetën e tij dhjakut Joan, dhe pa në vegim asketin Joan, mikun e tij, me kurorë mbi kokë që kishte të shkruara këto fjalë: “Kurora e durimit në shkretëtirë”. Dhe nga ana tjetër, Siemoni iu përgjigj se mbante kurorat e të gjithë shpirtrave që ishin shpëtuar nga marrëzia e tij e shtirur. Pasi e nxiti dhjakun Joan të mos afrohej kurrë në altarin e shenjtë me mendime të këqija kundër dikujt, Simeoni u tërhoq në kasolle, dhe u shti në një grumbull dërrasash që të tjerët të kuptonin se kishte dërrasat kishin rënë mbi të dhe ai kishte vdekur. Ata që qëndronin afër tij vunë re se shenjti nuk dilte më në rrugë, prandaj shpejtuan në kasollen e tij dhe e gjetën të vdekur. Menduan se ishte viktimë e një aksidenti, e varrosën, pa llambadhe dhe psalme në varrezat e rezervuara për të huajt. Gjatë kortegjit, një artizan xhami jude, të cilin Simeoni e kishte kthyer në besim, dëgjoi psalme që kurrë ndonjëherë nuk i kishte dëgjuar kënduar nga një turmë e madhe e padukshme. I çuditur, pa nga dritarja vetëm dy njerëz, dhe tha: “I lumur je ti, o i marrë, sepse i privuar nga psalme njerëzore, ke Fuqitë qiellore që të nderojnë me himnet e tyre!” Zbriti dhe shkoi ta varroste me duart e tij. Kur dhjaku Joan mësoi për fjetjen e Simeonit, shkoi në varreza dhe e hapi varrin. Ai u gjet bosh, dhe kuptoi se Zoti e kishte lavdëruar shenjti e tij duke e çuar edhe me trup në lavdi para ngjalljes. Banorët e Emesit e kuptuan se mes tyre jetonte një apostull i ri që i sillte në shpëtim, duke qëndruar i fshehur."},{"t":"h","x":"Martiri i shenjtë Viktori i Marsejës"},{"t":"p","x":"Ky atlet i lavdishëm i Krishtit lindi në një familje fisnike të qytetit të Marsejës në shekullin e 3. U angazhua në ushtri dhe i shërbente me trimëri perandorit dhe ligjit. Por kur Maksimiani vizitoi Marsejën (rreth 388) me qëllimin që të persekutonte të krishterët, shenjti në vend që ta fshihte besimin, refuzoi të merrte para dhe filloi të inkurajonte shokët e krishterë të ushtrisë që të mos i frikësoheshin torturave, që të denjësoheshin për triumfin qiellor. Natë e ditë shkonte shtëpi më shtëpi për të forcuar besimtarët dhe i shoqëronte deri në sheshin e ekzekutimit. Edhe atij i erdhi radha e ekzekutimit. E lidhën me zinxhirë dhe e nxorën para perandorit. Pohoi Krishtin, e tërhoqën zvarrë në rrugë dhe populli që merrte pjesë e godiste dhe e fyente. E lidhën pas një tufe kuajsh që e tërhiqnin, Zoti iu shfaq me një kryq në dorë dhe i premtoi një kurorë të pavdekshme. Natën iu shfaqën tre engjëj në qeli, dhe rojet e tij, Aleksandri, Longini dhe Felikiani,u çuditën nga ky spektakël i ndritshëm, ndaj u kthyen në besim. U pagëzuan dhe vdiqën si martirë para Viktorit, mësuesit të tyre. Tri ditë më vonë, shën Viktori doli para gjykatës dhe përmbysi statujën e Jupiterit që tirani i kërkonte të blatonte. I tërbuar, Maksimiani i preu këmbën dhe urdhëroi ta lidhnin shenjtin në gurin e një mulliri që të bluhej si maja e Krishtit. Por instrumenti i vdekjes u thye dhe shenjtit atëherë ia prenë kokën. Kur shpata e goditi, një zë nga qielli u dëgjua: “Viktor, fitove”. Trupat e martirëve të hedhur të det i gjetën disa të krishterë të perëndishëm dhe i varrosën në katakombin prej guri. Mrekulli të shumta u kryen nga shën Viktori dhe madje nderohet si mbrojtësi i qytetit të Marsejës. Rreth vitit 415, shën Joan Kasiani, jo larg nga qyteti, themeloi një manastir kushtuar shenjtit, i cili ndihmoi në përhapjen e nderimit të shën Viktorit dhe shërbeu si një qendër murgërore në Francë. Pas disa gërmimesh arkeologjike të ndërmarra në këtë manastir më 1963, u gjetën në katakomb që korrespondonte me të dhënat e martirizimit të tyre trupat e tre martirëve, njëri prej tyre ngjante të ishte i shën Viktorit."}]},{"d":22,"m":7,"blocks":[{"t":"intro","x":"Më 22 të këtij muaji, nderojmë kujtimin e shën Maria Magdalena Miroprurëse. Fjeti në Efes të Azisë së Vogël në shekullin e parë."},{"t":"li","x":"Kujtimin e oshënares virgjereshë dhe dëshmore Markela nga ishulli Hios në Greqi në shekullin e 16."},{"t":"li","x":"Kujtimin e oshënarit Kornel nga Perejaslavi i Rusisë në vitin 1693."},{"t":"li","x":"Kujtimin e atit të shenjtë Vandrili, ava i Fontenelës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Maria Magdalena"},{"t":"p","x":"Ishte nga fshati Magdhala, afër Gjenisaretit. Bënte pjesë në grupin e grave që ishin shëruar nga Krishti dhe E ndoqën pas nëpër udhëtimet e Tij për të përhapur Ungjillin, duke i shërbyer Atij nga gjëja e tyre (Mat. 27. 55-56; Mark. 15. 40-41). Maria ishte çliruar nga shtatë (= shumë ?) demonë (Luk. 8.1-3; Mark.16. 9)."},{"t":"p","x":"E pranishme në kryqëzimin dhe varrosjen e Jisuit, vërejti me kujdes vendin e Varrit për ta gjetur ditën tjetër, kur pas pushimit të pashkelur të së shtunës, do të vinte për të lyer me aromë trupin e perëndishëm (Mat. 27.55-56, 61; Joan. 19.25; Mark.15. 40-47)."},{"t":"p","x":"Vazhdimi është disi i paqartë. Sipas të gjitha gjasave gratë miroprurëse shkonin pranë Varrit në orë të ndryshme, herë veç e veç, herë në grupe të vegjël. Maria kishte nderin të shi-konte e para të Ngjallurin në të gdhirë të së dielës së parë. E mori për kopshtar derisa i njohu zërin, kur Ai e thirri në emër. E porositi të përhapte tek apostujt lajmin e mirë të Ngjalljes. Dhe e kreu porosinë dhe kështu u bë apostulle e tyre (Joan. 20.1-18; Mark. 16.9-10). Gjithashtu, së bashku me gra të tjera mori edhe një tjetër porosi gjatë Ngjalljes (Mat. 28.1-11; Mark. 16.1- 7; Luk. 24.1-10)."},{"t":"p","x":"Përputhja e saj me gruan mëkatare që leu me miro këmbët e Zotit (Luk.7.36-50) konsiderohet krejt e pabazë, ashtu si rrëfimi se gjoja ajo shkoi në Romë dhe arriti që të dënohej Pilati."},{"t":"p","x":"Sipas sinaksarit, prindërit e saj ishin Siri dhe Eukaristia, zyrtarë dhe të pasur, ndërsa vetë ajo, e bukur, gojëtare dhe mrekullibërëse. Veproi në Francë, Itali, Egjipt, Fenikë, Siri dhe Azi të Vogël. Fjeti në Efes, ku qëndroi me Joan Theologun (26 shtator)."},{"t":"p","x":"Më 4 maj kremtohet transferimi i lipsaneve të Maria Magdalenës dhe të Llazarit në vitin 890 nga perandori Leon VI (886-912) në Manastirin e Shën Llazarit që kishte ndërtuar në atë kohë. Miroprurësja kremtohet së bashku me gratë e tjera miroprurëse të dielën e tretë të Pashkës."},{"t":"h","x":"Markela e Hios, martire"},{"t":"p","x":"Kjo shqerrë e shenjtë e Krishtit vinte nga një fshat i ishullit të Hios. Nëna i kishte vdekur, ndaj dhe u rrit nga babai. Ndërsa rritej në moshë, rritej edhe në virtyt, në mënyrë të tillë sa trupi i shkëlqente nga pastërtia e shpirtit. Djalli e kishte zili për virtytet e saj, prandaj e sulmoi me mendime të turpshme, por shenjtorja i largonte ato me fuqinë e Kryqit. Atëherë, prici i errësirës u kthye nga babai i saj dhe provokoi tek ky njeri besëpakë dëshirë trupore ndaj vajzës. Pasi i lejoi në shpirt mendimet e këqija, filloi të joshte vajzën e tij. E turbulluar nga kjo paturpësi, shenjtorja u largua nga fshati dhe shkoi në mal. Kjo e egërsoi më shumë pasionin e tij, saqë shkoi ta kërkonte mal më mal. E lumura duke parë babanë e vet t’i afrohej, shkoi drejt detit dhe u fsheh në një ferrë, por nuk mundi t’i shpëtonte vëmendjes së të atit, i cili pasi nuk mundi dot të hynte në gëmushë, i vuri zjarrin. Markela u fsheh në një vend tjetër dhe vraponte përgjatë bregut, nëpër shkëmbinj. Si nuk mundi dot ta kapte, e qëlloi me një shigjetë që e plagosi të lumurën, por kjo nuk e ndali vrapin e saj. Kur pa se forcat po i shteronin, iu lut Zotit që t’i vinte në ndihmë. Kështu, Zoti bëri të thërrmohej një shkëmb për të mbrojtur shenjtoren. Kur i ati mbërriti në atë vend, nuk e tërhoqi dot nga shkëmbi, fillimisht i preu gjinjtë e më pas kokën dhe ia hodhi në det, duke i hapur kështu portat e oborrit qiellor mes virgjëreshave të urta. Në shkëmbin ku u strehua shenjtja, buron ujë i pastër me vlera shëruese, i cili i mbulon gurët me një cipë të kuqe, të quajtur “gjaku i shenjtë” për banorët e ishullit. Ata i mbledhin këta gurë dhe pasi i pastrojnë, i vendosin në vazo dhe i përdorin për sëmundje të ndryshme. Shenjtorja u është shfaqur shumë njerëzve të sëmurë, veshur me rroba murgjërore, sikur del nga deti. Në vendin e ferrës është ndërtuar një kishë për nder të saj."}]},{"d":23,"m":7,"blocks":[{"t":"intro","x":"Më 23 të këtij muaji, nderojmë kujtimin e profetit të madh Jezekielit, i cili jetoi në shekullin e 6 para Krishtit."},{"t":"li","x":"Kujtimin e martirit të shenjtë Foka në Sinopë."},{"t":"li","x":"Kujtimin e hierodëshmorit Apolinari, episkopi i parë i Ravenës, dhe të martirëve të shenjtë Vitali dhe gruas së tij Valeria."},{"t":"li","x":"Kujtimin e hierodëshmorit Apolonio, episkop i Romës."},{"t":"li","x":"Kujtimin e 7 dëshmorëve nga Kaldhia."},{"t":"li","x":"Kujtimin e martirëve të shenjtë që vdiqën nga bullgarët gjatë perandorisë së Niqiforit I-rë."},{"t":"li","x":"Kujtimin e oshënares Ana nga Lefkadhi. Fjeti në Konstandinopojë në shekullin e 9."},{"t":"li","x":"Kujtimin e oshënares Pelagjia nga Tinos i Greqisë në vitin 1830."},{"t":"li","x":"Kujtimin e shën Thirsit, episkop në Karpasia në Qipro."},{"t":"li","x":"Kujtimin e shfaqjes së mrekullueshme të Hyjlindëses, e cila shpëtoi Manastirin Potçajev nga sulmi i turqve dhe i tatarëve (1675)."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Oshënare Pelagjia e Tinos"},{"t":"p","x":"Një vit pas fillimit të revolucionit grek (1822), e Tërëshenjta iu shfaq një murgeshe të respektuar të quajtur Pelagjia, e cila asketizonte në manastirin e Kekrovunit, në lartësitë e ishullit Tino. I kërkoi të vinte në dijeni një nga fshatarët përreth, Stamatelos Kangadis, se ishte zgjedhur të zbulonte ikonën e Saj, që gjendej në një arë dhe të ndërtonte një kishë për nder të Saj. E frikësuar, e konsideroi veten të padenjë për një vegim të tillë, prandaj nuk u bind. E Tërëshenjta iu shfaq përsëri pas një jave, por Pelagjia e priti me të njëjtat dyshime. Përfundimisht, ndërsa po lutej, Pelagjia e pa Mbretëreshën e Qiejve para saj, të rrethuar nga një dritë hyjnore. I përsëriti urdhrin që i kishte thënë më përpara dhe e përshëndeti me këto fjalë: “Gëzohu, Toka e Gëzimit të madh...”. Murgesha iu përgjigj me vazhdimin e himnit: “Lavdëroni o qiej lavdinë e Perëndisë.” Në fillim të shërbesës së Mëngjesores, Pelagjia shkoi t’i tregonte igumenes vegimin që pati dhe superiorja konfirmoi vërtetësinë e tij. Të nesërmen shkoi në fshat dhe e informoi Stamatelos Kangadis-in dhe pasi peshkopi dha bekimin e tij dhe tha se bëhej fjalë për një shenjë të dashurisë së të Tërëshenjtës, mblodhi të gjithë besimtarët për të gërmuar. Por gruaja e zotërisë, që Nëna e Zotit e kishte caktuar, refuzoi veprimet pasi burri i saj nuk ndodhej në shtëpi. Atë natë, ajo pa në ëndërr sikur një njeri me pamje të tmerrshme e kërcënonte, kështu që ajo jo vetëm lejoi të bëheshin gërmime, por edhe e dhuroi tokën për të ndërtuar kishën. Shumë njerëz erdhën nga ishulli dhe filluan të gërmonin, por nuk gjetën gjë pas 2 muaj kërkimesh. U dekurajuan, disa filluan edhe të dyshonin, megjithatë e Tërëshenjta ndërhyri përsëri dhe punimet rifilluan. Kështu, në 30 janar të vitit 1823, u zbulua një ikonë madhështore e Ungjillëzimit, e cila ishte prerë vertikalisht në dy pjesë, por nuk kishte pësuar dëmtim nga qëndrimi i saj brenda në tokë. Sapo u vendos në kishën që ishte ndërtuar për nder të saj, filloi të bënte kaq shumë mrekulli, saqë ikona e Tinos është shndërruar në një vend pelegrinazhi popullor të Greqisë. Në manastirin e Kekrobunit, nderohet ende qelia në të cilën Pelagjisë iu shfaq Nëna e Zotit."}]},{"d":24,"m":7,"blocks":[{"t":"intro","x":"Më 24 të këtij muaji, nderojmë kujtimin e dëshmores së madhe Kristina, e cila u martirizua në Tiro të Palestinës në vitet 193-211."},{"t":"li","x":"Kujtimin e dëshmorëve Boris dhe Glebi, djemtë e mbretit të Rusisë Vladimirit, të cilët në pagëzimin e tyre e morën emrin Romano dhe David. U martirizuan në vitin 1015."},{"t":"li","x":"Kujtimin e dëshmorëve Kapitoni dhe Imenei."},{"t":"li","x":"Kujtimin e dëshmorit Ermogjeni."},{"t":"li","x":"Kujtimin e shën Solomptinit, episkop i Jerusalemit."},{"t":"li","x":"Kujtimin e martirit të ri Theofili i Zakinthit, të cilin e dogjën të gjallë në Hio."},{"t":"li","x":"Kujtimin e dëshmorit të ri Athanasi, u martirizua në Konstandinopojë në vitin 1670."},{"t":"li","x":"Kujtimin e atit të shenjtë Polikarpi i Lavrës së Kievit."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Kristina, martire e madhe"},{"t":"p","x":"Fëmijë e vetme e gjeneralit idhujtar Urban, u lind e jetoi në qytetin bregdetar të Tirit, në veri të Palestinës, në kohën e Sebirit (193-211). Për shkak të bukurisë së saj u mbyll nga i ati në një kullë luksoze, nga ku, duke vështruar qiellin me yje, filozofonte për krijesën dhe Krijuesin e saj."},{"t":"p","x":"Atëherë, me anën e zbulesës hyjnore, besoi tek Krishti dhe nuk u falej më idhujve të saj prej ari, siç e këshillonin prindërit. Për më tepër, një natë ajo copëtoi ato dhe ua shpër-ndau të varfërve."},{"t":"p","x":"Pas kësaj Urbani dha urdhër dhe e torturuan. E goditën pa mëshirë; e vendosën në një rrotë, ku poshtë kishte zjarr, i cili dogji shumë njerëz, por jo vajzën; e burgosën, duke e lënë pa ushqim dhe ujë, por ndërkohë, e ushqeu dhe e shëroi engjëlli; e hodhën në det, duke i varur gur në trup, por ajo pa Shpëtimtarin që e pagëzoi. Pastaj u ndodh në stere shëndoshë e mirë. I ati e burgosi përsëri për ta ekzekutuar si magjistare, por po atë natë ai dha shpirt me dhimbje."},{"t":"p","x":"Pasardhësi i tij, pasi nuk ia ktheu besimin me lajka, dha urdhër ta rrihnin dhe ta hidhnin në zift të përvëluar, t’i rruanin kokën dhe ta bridhnin rrugëve të zhveshur. Virgjëresha, në vend që t’i falej idhullit të Apollonit, urdhëroi dhe u vet-shkatërrua dhe si rezultat sundimtari vdiq nga hidhërimi. Në saje të mrekullive të saj u kthyen 3.000 idhujtarë."},{"t":"p","x":"Sovrani i ri e hodhi në furrë, por ajo brenda furrës, e pa-prekur, psalte së bashku me engjëjt; e hodhi tek zvarranikët helmues, por nuk u prek. Madje ngjalli zbutësin e egërsirave, të cilin e kishin kafshuar gjarpërinjtë kur i ndërsente kundër saj."},{"t":"p","x":"Pastaj xhelatët i prenë gjinjtë e në vend të gjakut rrodhi qumësht. I prenë edhe gjuhën që pohonte Krishtin, të cilën ajo vetë ia hodhi tiranit në sy, i cili u verbua - si dënim, siç ia sqaroi ajo, duke i folur qartë edhe pse nuk kishte gjuhë! Së fundi, e shpuan me shtizë në brinjë e në zemër dhe kështu fitoi (24 korrik) kurorën që i kishte parathënë një zë qiellor."},{"t":"p","x":"Ati i nderuar Polikarpi, arkimandrit i Lavrës së Shpellave të Kievit *"},{"t":"p","x":"Që kur hyri në Manastirin e Lavrës, ndërmori beteja të ashpra nën drejtimin e të afërmit të tij shën Simeonit (10 maj). Kur Simeoni u zgjodh episkop i Vladimirit, mori Polikarpin me vete dhe vazhdoi ta formonte si me fjalë, ashtu edhe me vepra. Mbajti shënim gjithë tregimet e shën Simeonit dhe ia dërgoi igumenit të Lavrës, Akindhini, i cili vazhdoi veprën e ndërmarrë nga Nestor kronisti (27 tetor), i cili do të hartonte Paterikonin e Kievit. U kthye në Manastir. Pas fjetjes së igumenit Akindhini, vëllezërit zgjodhën Polikarpin si igumen, i cili u përpoq ta ruante traditën që u la shën Theodhosi. Për vëllezërit ishte një udhëheqës i mençur. Fjeti më 24 korrik 1182."},{"t":"p","x":"Lavra qëndroi gjatë pa igumen, jo se nuk kishte më etër të denjë, por sepse asnjë prej tyre nga përulësia nuk pranuan të bëheshin. Atëherë vëllezërit u mblodhën në kishë dhe u lutën se nëse Polikarpi kishte gjetur pëlqim para Perëndisë, do t’u zbulonte atyre emrin e pasuesit të tij. Një zë u dëgjua: “Shkoni e gjeni priftin e perëndishëm Vasil, në Shkekovica, bëjeni murg dhe ai u bëftë igumeni juaj”. Menjëherë vepruan kështu. Gjetën priftin Vasil, i cili pranoi me vështirësi. Episkopët Niqifor i Kievit dhe Laurenti i Turovit dhe Nikolai i Polotskut dhe ava të tjerë morën pjesë në qethjen e tij. Ai ishte shembulli i shën Polikarpit, model i virtytit dhe e drejtoi manastirin me urtësi deri në fjetjen e tij të lumur."}]},{"d":25,"m":7,"blocks":[{"t":"intro","x":"Më 25 të këtij muaji, nderojmë kujtimin e Fjetjes së shën Anës, nëna e së Terëshenjtës Mari."},{"t":"li","x":"Kujtimin e 165 Etërve të Sinodit të Pestë Ekumenik në Konstandinopojë në vitin 553."},{"t":"li","x":"Kujtimin e dëshmorëve Lioni e Vjeni, si dhe të Saktit, Maturit nga Atalit dhe Blandinës (grua) nga Pergami; që u martirizuan në Lion të Francës në vitet 138-161."},{"t":"li","x":"Kujtimin e oshënares Olimbia dhjakoneshë, nxënësja e shën Joan Gojartit, e cila vdiq në internim në shekullin e 5-të."},{"t":"li","x":"Kujtimin e oshënares Efpraksia, e cila jetoi në një manastir të Egjiptit në shekullin e 5-të."},{"t":"li","x":"Kujtimin e oshënarit Makar çudibërësi, i cili jetoi në shkretëtirën afër liqenit Zelta të Rusisë në vitin 1504."},{"t":"li","x":"Kujtimin e oshënarit Kristofori, igumen i Manastirit të Solviçegodsk (krahinë e Vologdës) shek. 16."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Ana (fjetja e saj) dhe Joakimi"},{"t":"p","x":"Edhe Anën (hebraisht = hir) edhe Joakimin (hebraisht = Perëndia nxit), prindërit e Perëndilindëses, nuk i gjejmë në Ungjill, por në apokrifet dhe sidomos në Protoevangjelin e Jakovit (mesi i shek. të 2-të). Ky ruan një traditë shumë të vjetër, autentike të paktën për sa i përket bazës së saj. Kështu, Kisha, edhe pse i hodhi poshtë apokrifet, pranoi disa rreth gjenealogjisë dhe rinisë së shën Marisë, kështu që ato ndikuan në liturgjikë, himnologji dhe ikonografi. Veç kësaj, nga apo-krifet merr material edhe Shkrimi i Shenjtë (p.sh. Jud. 9)."},{"t":"p","x":"Pra, çifti shpresëtar dhe i pasur, sipas të gjitha gjasave nga Jerusalemi, pasardhës të mbretit David (e diela pas Lindjes së Krishtit), edhe pse sterilë dhe të moshuar, vajtonin dhe luteshin që t’iu hiqej turpi i mosbërjes fëmijë. Atëherë mungesa e fëmijës konsiderohej si turp, për disa arsye të caktuara. Ana premtoi se do t’ia kushtonte Perëndisë fëmijën e famshëm që do të lindte, siç e lajmëroi engjëlli. Ajo lutej në kopsht, ai në mal. Dhe me të vertëtë, ajo mbeti shtatzënë (9 dhjetor) dhe lindi Marinë (8 shtator)."},{"t":"p","x":"Në moshën trevjeçare ia besojnë kryepriftit Zaharia, i cili e fut në të Shenjtat e të Shenjtëve të Tempullit të Jerusa-lemit (21 nëntor). Ajo qëndron aty nën mbikqyrjen e priftë-rinjve për nëntë (ose dymbëdhjetë) vjet, duke u ushqyer nga engjëlli, derisa i dorëzohet Josifit (e diela pas Lindjes së Krishtit), i cili ishte i ve."},{"t":"p","x":"Ai thuhet se është i biri i vëllait të Anës, si Saloma (3 gusht) dhe Elisaveta (24 qershor), të cilat thuhet se janë bijat e motrave e saj. Pra, ato ishin kushërira të para të Marisë dhe, rrjedhimisht, Pararendësi (7 janar) ishte kushëri i dytë me Krishtin."},{"t":"p","x":"Mirëbërësja Ana fjeti në moshën 69 - vjeçare, ndërsa Joakimi në moshën 80 - vjeçare. Kështu Virgjëresha mbeti jetime në moshën 11 - vjeçare."},{"t":"p","x":"Më 9 shtator, ditën e nesërme të lindjes së saj, bëhet mbledhje për nder të prindërve të saj, ndërsa sipas shumë dëshmive kremtohet sot fjetja e të dy prindërve të Nënës së Perëndisë."},{"t":"p","x":"Së fundi, në skitën e famshme të Nënës së të Tërëshenjtës në Malin e Shenjtë ruhet këmba e saj e majtë, që bën mrekullira."},{"t":"h","x":"Olimbia dhjakone"},{"t":"p","x":"Olimbia e lumur lindi në Konstandinopojë mes viteve 361 e 368 në një familje të aristokracisë së lartë. Babai i saj Konti Selefkos dhe nëna e saj vdiqën kur ajo ishte fëmijë dhe e besuan tek një nga të afërmit e familjes së saj, Prokopi, guvernator i Konstandinopojës, i cili edukimin e vajzës ia besoi Theodhosisë, motrës së shën Amfilokut të Ikoniumit (23 nëntor). Nëpërmjet saj, Olimbia pati lidhje miqësie e familjare me shën Grigor Teologun, shën Grigorin e Nisës e të tjerë njerëz të ndritshëm të kishës. Pasi u rrit shkëlqeu si me bukurinë trupore, ashtu edhe në urtësi e mëshirë. Më 386 u martua me Nebridios, prefektin e Konstandinopojës i cili vdiq shumë shpejt pa pasur marrëdhënie me të. Atëherë vendosi t’i kushtohej Perëndisë si vejushë dhe virgjëreshë dhe dha gjithçka që kishte për kishën. Refuzoi të rimartohej me Elpidios, i afërm i perandorit Theodhos. Shteti i konfiskoi të mirat e saj dhe pengoi të frekuentonte njerëzit e kishës derisa t’i nënshtrohej kërkesës. Por kur u kthye nga fushata kundër Maksimit më 388 perandori admiroi zellin për asketizmin e virtytin dhe ia ktheu të mirat. I bëri lëmoshë. Shiti pronat që kishte në Thrakë, Galati, Kapadhoqi e në Bitini si dhe ndërtesat madhështore të Konstandinopojës që të ndërtonte hotele për udhëtarët, spitale, kisha dhe një manastir në portikun meridional të kishës së shën Sofisë, i cili kishte më shumë se 50 murgesha: fillimisht shërbëtoret e saj, të afërmet si dhe më pas erdhën edhe gra të shoqërisë së lartë. U vesh me rroba të varfra, trup të dobët e të lehtë nga agripnitë e lutjet si dhe zemër të qetë e të pastruar nga çdo kureshtje mondane. Ishte ikona e virtytit për të gjitha motrat. Me gjithë sprovat që pati, kurrë nuk doli nga goja e saj një fjalë qortimi, dashuria që kishte shtrihej tek të gjithë: të denjë e të padenjë. Gjithë kohën e kaloi në soditjen me lot e pendim. Virtyti i saj u njoh nga të gjithë, saqë në moshën 30-vjeçare patriku shën Nektar (11 nëntor) e dorëzoi dhjakoneshë* e u bë këshilltare e tij për çështje kishtare. Kur shën Joan Gojarti pasoi fronin pas shën Nektarit, Olimbia nuk gjeti tek ai vetëm atin shpirtëror që ajo dëshironte, por autoritetin për interpretimin e Shkrimit, bariun që kujdesej për gjithë kishën më shumë se për trupin, një mik si në ditë të paqta ashtu edhe në turbullimet për shkak të së vërtetës dhe drejtësisë. U vu në shërbim të tij me zell. I vetmi person i gjinisë mashkullore që u pranua brenda manastirit të Olimbias ishte peshkopi i shenjtë, i cili i mësonte murgeshat dhe disa prej tyre i dorëzoi në dhjakonesha. Pas dëbimit të Gojartit në Armeni (404), Olimbia refuzoi të njihte personin e Joanit patriark e filloi të mbronte shenjtin. Pasi u akuzua nga prefekti i Optat se kishte provokuar një zjarr që kishte shkatërruar pallatin pritës, u dënua me një gjobë. Atëherë u tërhoq në Sitikë dhe pas një tjetër paraqitjeje para prefektit u dërgua në mërgim në Nikomedi, ku shën Joan Gojarti i shkroi 17 letra ngushëllimi për ta inkurajuar të duronte provën e padrejtësisë me besim e durim. Falë tyre Olimbia përparoi në durim e përulësi. Pasi u dha në shumë beteja të vështira për kishën, pasi mësoi shumë gra në rrugën e virtytit, pasi nderoi etërit e shërbeu për peshkopët e shenjtë, ia dorëzoi shpirtin e saj Perëndisë në Nikomedi më 25 korrik 408 duke fituar kurorën e pohuesve (rrëfyesve) të besës. Sipas dëshirës së saj, trupin ia mbyllën në një arkivol dhe e lëshuan në det. Pasi arriti afër manastirit të shën Thomait në Broktua, në gjirin aziatik të Bosforit, një engjëll lajmëroi igumenin dhe ai e mori trupin e saj dhe e vendosi në shenjtërore, ku kryen shumë mrekulli. Manastiri i shenjtores në Konstandipojë, i shkatërruar gjatë revoltës së Niketas më 532, u rindërtua nga Justiniani dhe lipsanet e saj u transferuan atje në fillim të shekullit VII gjatë një invazioni pers. * Dhjakoneshat e zgjedhura në radhët e virgjëreshave ose të vejushave të moshuara (60 vjeç në fillim, pastaj 40 vjeç) dorëzoheshin me vënien e duarve dhe hynin në ajodhimë, por nuk konsideroheshin si pjesë e klerit. Detyra e tyre kryesisht ishte pjesëmarrja në pagëzimin e grave, vizitat tek të sëmurët, si edhe disa punë ndihmëse, por ato nuk mund të predikonin në publik dhe as të pagëzonin. Më pas ky funksion u zbeh derisa u zhduk."},{"t":"h","x":"Efpraksia oshënare"},{"t":"p","x":"E lumura Efpraksi ishte kushërirë e perandorit Theodhosi i Madh (379- 395). Kur babai i saj, senatori Antigon, vdiq para kohe, nëna e besoi atëherë vajzën 6-vjeçare nën mbrojtjen e perandorit, i cili donte ta fejonte me birin e një prej senatorëve më të shquar. Por shenjtorja preferoi më tepër të ruante pastërtinë e saj dhe t’i kushtohej Zotit, prandaj u largua për në Egjipt bashkë me nënën e saj, e cila donte t’i shpëtonte martesës së dytë. Gjatë udhëtimit bënë lëmoshë dhe bamirësi të ndryshme, vizituan disa asketë të shenjtë dhe arritën në Tebaidë, në një manastir me 130 murgesha që jetonin jetën engjëllore. E admiruan jetën e tyre dhe i vizituan shpesh, derisa një ditë Efpraksia me dëshirën për të imituar virtytet e tyre i tha nënës së saj se donte të qëndronte në manastir. Asgjë nuk e bëri vajzën e re të hiqte dorë nga kjo zgjedhje, as pohimet e igumenes, e cila i thoshte se jeta atje ishte tepër e ashpër, pa mjete komforti dhe me pak ushqim. Por vuri re se thirrja e saj ishte e pakthyeshme; atëherë nëna i drejtoi një lutje të nxehtë Krishtit për t’i ofruar fëmijën e saj dhe pasi e la në duart e igumenes, la Egjiptin për të përshkuar tërë Lindjen që të shpërndante pasurinë. Pas disa kohësh u sëmur dhe pati kohë vetëm sa për të shkuar në Tebaidë e të takonte bijën e saj. Pasi u takuan në manastir, fjeti në paqe. Atëherë Efpraksia mori të gjithë pjesën e pasurisë që i kishte mbetur nënës së saj dhe shkoi ta ndante tek të varfrit, në manastire e kisha të Egjiptit, që më pas të asketizonte pa pasur merak. Perandori pasi mori vesh për fjetjen e nënës së shenjtores dhe ndërsa martesa e të pasurit trashëgimtar dhe Efpraksinë po afrohej, e thirri këtë të fundit në Konstandinopojë për dasmën. Por shenjtorja, e cila ishte 12 vjeç, i tha se tashmë ishte bërë nusja e Krishtit dhe se nuk mund ta braktiste dhëndrin qiellor e të pavdekshëm për një njeri të vdekshëm. E përfundoi letrën e saj duke i shkruar perandorit që të shpërndante pasurinë e prindërve tek të varfrit. Që atëherë mundi të përkushtonte tërë energjinë e saj për dashurinë e Perëndisë. Ushqehej me bukë e ujë çdo katër ditë dhe u shërbente motrave në manastir. Meqë u sulmua nga mendime të papastra, e ashpërsoi kreshmën dhe punën, e zbukuroi vendin ku flinte me hi dhe gurë të mprehtë dhe kur tundimet nuk pushuan, kaloi 45 ditë e netë në agjërim, në këmbë, jashtë me duar të shtrira drejt Perëndisë duke e lutur që t’i vinte në ndihmë. Kur djalli e pa se nuk mundi ta nënshtronte dot në tundimet e trupit, e rrëzoi në një pus. Por e lumura thirri në ndihmë Jisuin dhe pasi kapi litarin, u ngjit lart me ndihmën e motrave. Një herë tjetër e qëlloi në thembër dhe e bëri të binte mbi një copë dru, që i çau fytyrën afër syrit. Por asgjë nuk mundi ta tërhiqte nga prania e Perëndisë dhe nga shërbimi që u bënte motrave. Një herë një motër e pati shumë zili Efpraksinë dhe e qortoi se asketizonte përtej normave me qëllim që t’u pëlqente motrave dhe të pasonte igumenen. Efpraksia e kuptoi kurthin e ri të djallit dhe iu hodh në këmbë motrës ziliqare e i kërkoi të falur. Kjo e fundit, pasi u përjashtua, i kërkoi igumenes të falur dhe të ribashkohej me vëllazërinë."},{"t":"p","x":"Në moshën 20-vjeçare, betejat e saj i kishin pëlqyer Zotit, aq sa fitoi dhuratën e shërimit. Shëronte me anën e lutjes sëmundjet e banorëve të krahinës, të cilët shkonin në manastir si në një liman shpëtimi; shëroi një fëmijë paralitik dhe nxori frymëra të këqija nga një e demonizuar, duke e goditur me shkopin baritor të igumenes. Në moshën 30-vjeçare, Zoti i zbuloi igumenes se kishte ardhur tashmë ora e Efpraksisë për të shkuar në qiell. Pasi mori këtë lajm dhe pa motrat që qanin, e lumura e luti Zotin t’i linte kohë për t’u penduar. U sëmur dhe u transferua në kishë, ku motrat vinin dhe i jepnin përshëndetjen e fundit. Gjatë mesit të natës e dha shpirtin e saj tek Krishti për t’u gëzuar përjetësisht në praninë e Tij me Virgjëreshat e urta."}]},{"d":26,"m":7,"blocks":[{"t":"intro","x":"Më 26 të këtij muaji, nderojmë kujtimin e oshënares Parashkevi (ose e Premtja) virgjereshë, e cila jetoi dhe vdiq në Romë në vitin 138-161."},{"t":"li","x":"Kujtimin e hierodëshmorëve Ermolau, mësues i shën Pandeleimonit, Ermipi, Ermokrati priftërinj, që u martirizuan në Nikomedi në vitin 304."},{"t":"li","x":"Kujtimin e dëshmores Oreozela."},{"t":"li","x":"Kujtimin e dëshmorit Apioni."},{"t":"li","x":"Kujtimin e dëshmores Jerusalima."},{"t":"li","x":"Kujtimin e oshënarit Ignat Stironiti nga Manastiri i Shën Llukait afër malit Stirion në Greqi në shekullin e 11."},{"t":"li","x":"Kujtimin e oshënarit Simeon, i cili jetoi mbi një shtyllë."},{"t":"li","x":"Kujtimin e shën Ermolaut çudibërës dhe anargjend, i cili kremtohet shumë në Qipro."},{"t":"li","x":"Kujtimin e oshënarit Geronti, i cili themeloi Skitin e Shën Anës në Malin e Shenjtë në shekullin e 17-18."},{"t":"li","x":"Kujtimin e atit të shenjtë Moisi Hungarezi i Lavrës së Kievit."},{"t":"li","x":"Kujtimin e martirit të shenjtë Apion, i cili mbaroi me shpatë."},{"t":"li","x":"Kujtimin e atit të shenjtë Sava III, kryepiskop i Serbisë."},{"t":"li","x":"Kujtimin e shën Jakov Netsetovit, misionar në Alaskë."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Parashqevia, oshënare – martire"},{"t":"p","x":"Prindërit e saj të krishterë, Agathoni dhe Politia, jetonin në periferi të Romës në kohën e Adrianit (117-138). Duke qenë pa fëmijë më parë, e pritën si shpërblim të lutjeve të tyre dhe i dhanë emrin Parashqevi, sepse lindi të premten (= Paraskevi = përgatitje). E edukuan me dashuri më Zotin."},{"t":"p","x":"Vajza e virtytshme, e mençur dhe e bukur studionte Shkrimin e Shenjtë dhe frekuentonte shërbesat, derisa mbeti jetime. Atëherë pasurinë e saj ua dha të varfërve dhe vetë u rreshtua në një vëllazëri (murgeshash)."},{"t":"p","x":"Më vonë, me “bekimin” e igumenes doli nëpër Romë dhe në krahinën e saj dhe predikonte Krishtin me sukses. Çifutët e patën zili dhe e paditën. Kështu u kap në kohën e Antoninit Piu (138 - 161). As me të butë dhe as egërsisht nuk mundën ta konvertonin dhe e torturuan: i veshën në kokë përkrenaren e skuqur, e varën nga flokët dhe e dogjën me llambadhe, e futën në zift dhe vaj të nxehtë, e ekspozuan në një gjarpër të tmerrshëm, e kamxhikuan dhe e shtypën me një pllakë të rëndë në gjoks. Shumë herë virgjëresha nuk pësonte asgjë."},{"t":"p","x":"Një herë tjetër iu shfaq në burg një engjëll, madje edhe vetë Krishti, i Cili e lumëroi dhe e shëroi. Meqenëse ajo mbetej e pacënuar brenda vajit të përvëluar, pushtetari kërkoi që ta spërkatte, për të vërtetuar në ishte i nxehtë ose jo. Kur u spërkat, ai u verbua nga djegia! Iu lut oshënares i penduar dhe ajo i dha shëndetin - ndoshta për këtë arsye ne kërkojmë ndërmjetimin e saj si mjeke okuliste."},{"t":"p","x":"Një herë tjetër, duke bërë shenjën e kryqit, bëri që të përplasej një gjarpër i frikshëm dhe një mrekulli e fundit e saj bëri që të bien dhe të copëtohen idhujt e një tempulli. Pas këtyre besoi një shumicë njerëzish. Kështu, për t’i dhënë fund mrekullive të saj u detyruan t’i prisnin kokën."},{"t":"p","x":"Shenjtorja mjaft popullore nderohet edhe si mbrojtëse nga kolera dhe flama. Më 14.10.1442 një stuhi e tmerrshme do ta kishte përmbytur ishullin Hios, nëse ajo nuk do të ndërmjetonte në mënyrë efikase, siç e ëndërroi një hieromonak pasi u lut në një kishë të saj."},{"t":"p","x":"Shtojmë se sinaksarët (biografitë) e saj nuk përputhen plotësisht."},{"t":"h","x":"Ermolau, Ermipi, Ermokrati, martirë"},{"t":"p","x":"Kanë qenë priftërinj të krishterë të Nikomedisë, një qytet të madh në bregdetin aziatik të Propondit, të cilët shpëtuan nga zjarri që iu vu kishës në Krishtlindjet e vitit 304. Aty u dogjën rreth 20.000 besimtarë (29 dhjetor). Fshiheshin pra në shtëpi."},{"t":"p","x":"Ermolau ftoi atje shën Pandeleimonin (27 korrik) dhe pasi u njohën e përsosi në diturinë e Perëndisë, në të cilën e kishte futur të riun nëna e tij shpresëtare, shën Evulia (30 mars). Prifti e bindi se Jisui shëron më efektivisht se mjekësia që studionte atëherë me sukses Pandeleimoni."},{"t":"p","x":"Studenti, duke “eksperimentuar” në lidhje me fjalët e mësipërme e thirri Shpëtimtarin duke iu lutur që ta vriste nepërkën dhe të ngjallte fëmijën e kafshuar prej saj. Kështu edhe u bë, atëherë besoi pa rezerva, sa u pagëzua prej shenjtit."},{"t":"p","x":"Më vonë, dëshmori i madh Pandeleimon Shëruesi, i hetuar prej perandorit Maksimiani (286-305), u pyet se kush ia mësoi fenë e re. Duke patur besim tek qëndrueshmëria e drejtuesit të tij u përgjigj drejt, që të predikonte dhe ai të vërtetën dhe të ndriçonte shumë dëgjues të gjyqit. Vetë Pandeleimoni i drejtoi ushtarët në vendin ku rrinin të tre klerikët, ku derën ia u hapi Ermolau, i cili kishte pasur një informacion hyjnor që do të martirizohej."},{"t":"p","x":"Të tre priftërinjtë nuk pranuan të sakrifikonin tek perën-ditë; kur po luteshin iu shfaq Zoti në kohën e një tërmeti që theu idhujt. Në fund pasi u torturuan, iu prenë kokat. Emrat e tyre u përkthyen në greqisht: populli i Hermës, kali i Hermës dhe fuqia ose pushteti i Hermës."},{"t":"h","x":"Moisi hungarezi i Lavrës së Shpellave të Kievit"},{"t":"p","x":"Ishte me origjinë nga Hungaria, dhe bashkë me vëllain e tij Gjergjin, shërbenin në oborrin e princit martir Boris (24 korrik), i cili e donte shumë shenjtin. Gjatë vrasjes së Borisit, Moisiu mundi të mbijetonte dhe u strehua në Kiev në banesën e Predislavës, motrës së princit Iaroslav, ku e kaloi kohën në lutje. Iaroslavi fitoi mbi Sviatopolkun, por ky i fundit u fsheh në Poloni, u forcua nga trupa të tjerë dhe dëboi Iaroslavin dhe kështu pushtoi Kievin. Shën Moisiu u dërgua rob në Poloni nga mbreti Boleslav. Një vejushë e pasur kur vuri re forcën dhe kurajën e tij, e bleu Moisiun si skllav për 3000 monedha ari dhe u përpoq ta tërhiqte në imoralitetit me premtime të ndryshme. Por ky Josif i ri u rezistoi tundimeve duke shtuar kreshmën. Atëherë, gruaja e mbylli në një kafaz, që ai të vdiste nga uria. Por Zoti frymëzoi një nga shërbëtorët e shtëpisë që t’i çonte fshehur ushqim. Miqtë e shenjtit u përpoqën ta bindnin të pranonte propozimet për martesë me vejushën, por ai u përgjigj se këshillat e tyre ishin më të këqija se ato të gjarprit në Parajsë, sepse dëshironte të qëndronte i virgjër për t’iu përkushtuar Zotit. Këto fjalë arritën në veshët e gruas dhe nga inati, ajo e hipi mbi një kalë dhe vizituan pronat, duke thënë tek njerëzit se ai ishte burri i saj. Por Moisiu deklaroi se asgjë nuk mund ta largonte nga dëshira e të mirave të paprishshme të premtuara tek të zgjedhurit."},{"t":"p","x":"U qeth murg nga një murg kalimtar i Athosit dhe iu paraqit vejushës me rrobën murgërore. E mjera u çmend nga zemërimi dhe urdhëroi ta torturonin, ta godisnin me hekura derisa toka të mbulohej me gjak. Xhelatët kërkonin ta kursenin nga torturat Moisiun, por ai u përgjigj: “Vëllezër, është e pamundur të heq dorë nga detyrat murgërore. As torturat, as zjarri, as shpata nuk do të mund të më ndajnë nga dashuria e Perëndisë dhe veshjes së shenjtë engjëllore”. Kjo çështje iu çua mbretit Boleslav. Ai u përpoq ta bindte Moisiun që ta pranonte për grua vejushën. Pasi pa refuzimin e shenjtit, i dha leje gruas të vepronte si të donte me të. Ia prenë gjymtyrët e brendshme, e rrihnin çdo ditë me 100 goditje dhe duroi sharje dhe keqtrajtime për shumë kohë."},{"t":"p","x":"Më në fund Perëndia e tregoi drejtësinë e Tij. Boleslavi, i cili kishte organizuar një persekutim kundër murgjërve, u sëmur dhe vdiq. Një revoltë shpërtheu në të gjithë mbretërinë, kryengritësit vranë episkopët e tyre dhe fisnikët, ndërsa vejusha e shën Moisiut vdiq gjatë këtyre ngjarjeve. U çlirua nga kjo provë e tmerrshme që e torturonte për 6 vjet dhe që e bëri të shkëlqente virtyti i tij, ashtu si Jobi dhe i pastri Josif. Shën Moisiu shkoi në Kiev. Hyri në Shpellat e Kievit dhe nën drejtimin e shën Andonit ruajti heshtjen dhe lutjen përgjatë 10 vjetëve. Pasi arriti në një shkallë të lartë shpirtërore dhe rrezatonte hir, fjeti në paqe më 26 korrik 1043. Lipsani i tij i çmuar mbeti i paprishur në shpellën e shën Andonit të Kievit. Gjatë shekujve, lutjet e tij kanë çliruar një numër të madh besimtarësh nga imoraliteti dhe tundimet trupore."},{"t":"h","x":"Oreozila, virgjëreshë martire"},{"t":"p","x":"Nuk e dimë origjinën e këtij pëllumbi të bardhë të Krishtit dhe cilët ishin prindërit e saj. Sipas disave, shenjtja ishte pagëzuar nga apostull Andrea i parëthirruri dhe pastaj kaloi pjesën tjetër të jetës së saj në një kishë kushtuar Kryeëngjëllit Mikail në Bosfor. Ashtu si një tokë e mirë ku shën Andrea kishte mbjellë farën e mësimit ungjillor, shenjtorja dha fryte nga lutja dhe hezikia e saj. Punonte me zell për të zbatuar të gjitha urdhërimet dhe nga shembulli i jetës së saj, nga ashpërsia në të cilën ushtrohej, u bë një predikuese e vërtetë e Zotit Jisu Krisht, e barabartë me apostujt. Të shumtë ishin paganët që vraponin drejt saj për të dëgjuar e që më pas të ktheheshin në besim. Dy vajza idhujtare i kërkuan të shenjtores të qëndronin bashkë me të, pasi e konsideronin si imazh të gjallë të virtytit dhe që atëherë përpiqeshin me zell të zjarrtë në vepra të mira. Jetuan kështu deri në kohën e perandorit Deka, të cilin djalli e shtyu të persekutonte dhunshëm të krishterët. Tirani e thirri një ditë Oreozilën dhe e pyeti se përse e kishte braktisur besimin e të parëve të saj dhe kishte pranuar Krishtin, madje kishte nxitur shumë besimtarë të ndërronin besimin. Shenjtorja iu përgjigj: “Ti e di o perandor, se Krishti të cilin shpall, është kryqëzuar si njeri dhe si nuk e ke mësuar ende se u ngjall si Perëndi? Nuk ke dëgjuar se zbriti në ferr për të ngritur të gjithë ata që dergjeshin atje dhe si princ i jetës u fali jetën e përjetshme të vdekurve? Ishte Perëndi para jetëve, u bë njeri, vuajti dhe u kryqëzua për shpëtimin tonë. Por e gjitha kjo është tepër e fortë për veshët e një njeriu që nuk do të dëgjojë zbulimin e këtij misteri. Gjithsesi, çfarëdo që të pësoj nga ti, kurrë nuk do të arrish të më ndash nga dashuria për Krishtin, as të mohoj Perëndinë tim!”"},{"t":"p","x":"Deka i inatosur urdhëroi ta rrahin shenjtoren për shumë orë rresht. Të gjithë u mahnitën për durimin dhe kurajën që tregoi nusja e Krishtit, sepse i duronte torturat sikur të rrihnin dikë tjetër. Kur perandori mbërriti në vend dhe priste të dëgjonte shenjtoren të mohonte Krishtin, papritur u verbua. Oreozila, e cila priste me padurim të shkonte tek Krishti, i tha perandorit se do të fitonte shikimin vetëm po të lyente sytë e tij me gjakun e saj. Atëherë Deka dha urdhër që menjëherë t’i pritej koka shenjtores dhe me gjakun që rridhte nga koka e saj leu sytë dhe shpejt filloi të shikonte. Por nuk pati fare mirënjohje për këtë mrekulli, aq sa i pengoi të krishterët të varrosnin trupin e saj dhe madje urdhëroi ta digjnin atë. Festa e shën Oreozelës kremtohet në kishën që i është kushtuar asaj, pranë kishës së shën Anastasisë në Konstandinopojë, ku dhe kreu shumë mrekulli, veçanërisht për gratë që nuk lindin."},{"t":"p","x":"Në të njëjtën ditë nderohet dhe Kujtimin e martires së shenjtë, Jerusalima, e vrarë me shpatë. Ishtë nxënëse e shën Oreozelës. Kishte përparuar aq shumë në virtyt, saqë djalli nuk duronte të shikonte fuqinë e Perëndisë të rrezatonte tek ajo. Kështu që një ditë, i ligu u sugjeroi disa paganëve ta nxirrnin të lumurën nga manastiri dhe ta detyronin që t’u falej idhujve dhe të martohej me një oficer. Pasi refuzoi për dashurinë e Krishtit, e shenjta duroi të gjitha torturat e tmerrshme derisa iu pre koka."}]},{"d":27,"m":7,"blocks":[{"t":"intro","x":"Më 27 të këtij muaji, nderojmë kujtimin e dëshmorit të madh Pandeleimon çudibërësi, i cili u martirizua me shumë tortura në Nikomedi në vitin 304."},{"t":"li","x":"Kujtimin e oshënares Anthuza virgjëreshë nga Konstandinopoja në shekullin e 8-9."},{"t":"li","x":"Kujtimin e oshënarit Manueli."},{"t":"li","x":"Kujtimin e atit të shenjtë Simeon Stiliti i Ri."},{"t":"li","x":"Kujtimin e 153 martirëve të Thrakës që i mbytën në det."},{"t":"li","x":"Kujtimin e shën Klementit të Ohrit, episkopi i parë i Bullgarisë, dhe të nxënësve të tij Kirili e Metodi, Gorazdi, Naumi, Angjelari dhe Sava."},{"t":"li","x":"Kujtimin e oshënarit Nikolla Koçanovi i marrë për Krishtin nga Novgorodi i Rusisë në vitin 1392."},{"t":"li","x":"Kujtimin e shën Joasafit, mitropolit i Moskës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Pandeleimon Shëruesi"},{"t":"p","x":"U ushtrua rreth vitit 305 në vendlindjen e tij, Nikomedia, në bregdetin aziatik të Propondidës. Pandoleon, siç quhej, ishte një mjek i dalluar, fryt i idhujtarit Efstorgi dhe e shën Evulës (30 mars), që ishte e krishterë nga paraardhësit e saj, por që vdiq herët."},{"t":"p","x":"Duke “eksperimentuar” ai ngjalli, duke thirrur Zotin, një fëmijë që e kishte pickuar një nepërkë, kështu që u pagëzua nga shën Ermolau (26 korrik), siç është shkruar edhe atje. Prifti, d.m.th. shën Ermolau, e bëri të përsosur në besim dhe e bindi atë se Jisui shëron më me efikasitet se mjekësia që studionte atëherë. Ndaj Pandoleoni u lut dhe vërtet ngjalli fëmijën."},{"t":"p","x":"Më vonë Pandeleimoni u bë shkas që të martirizohej Ermolau dhe të fitonte kështu kurorën, që nuk vyshket, të shenjtërisë. (Ngjarjet u treguan më qartë në jetën e shën Ermolaut dje)."},{"t":"p","x":"Pandoleoni shëroi në mënyrë mrekullibërëse edhe një të verbër të pashërueshëm (kremtohet sot). Pra u ndriçuan dhe u pagëzuan ish i verbri dhe Efstorgi, (i cili tashmë ishte ndikuar nga i biri), por kolegët e tij bashkëkombas treguan smirë ndaj shkencëtarit shpresëtar."},{"t":"p","x":"Shëruesi, pas vdekjes së të atit, ndau pasurinë e vet dhe shëronte falas - prandaj quhet edhe “anargjer” - duke kërkuar vetëm besimin tek Jisui. Mjekët e denoncuan tek perandori Maksimian (286-305). Në gjyq sollën edhe të verbrin, që tashmë ishte i krishterë entuziast, i cili u tall me mbretin, kështu që i prenë kokën. Pandeleimoni kërkoi e shëroi para tyre një të paralizuar, gjë që nuk kishin mundur ta bënin kundërshtarët e tij dhe shumë njerëz besuan."},{"t":"p","x":"Maksimiani më kot u përpoq ta frikësonte shenjtin, të cilin e donte pa masë. Dhe e urreu! Urdhëroi dhe e torturuan, por Perëndinjeriu, që shfaqej si Ermolau, bënte shpesh që të mos vepronin xhelatët dhe të mos funksiononin mjetet e tor-turës, e shëronte dhe shpëtonte."},{"t":"p","x":"Por tirani i zemëruar nuk tërhiqej. Martirin e madh e gërvishën me thonj hekuri; e dogjën me llambadha; e hodhën në plumb që ziente, e hodhën në det të lidhur me gur në trup; e hodhën tek egërsirat; e lidhën në një rrotë të rëndë dhe e lëshuan tatëpjetë. Shpata që do t’i priste më pas kokën, u përkul si qiri dhe ushtarët u tronditën."},{"t":"p","x":"Por Pandeleimoni (greqisht = përdëllimtar i të gjithëve), kështu e quajti atëhere zëri hyjnor, u thoshte të zbatonin urdhrin, që ai të fitonte kurorën e të ushtruarit. Nga prerja që bëri shpata doli qumësht, ndërsa ulliri i thatë, në të cilin ishte i lidhur, lulëzoi menjëherë dhe lidhi fryte! Në ikonë paraqitet duke mbajtur një kuti me ilaçe."},{"t":"p","x":"Klementi i Ohrit, episkopi i parë i Bullgarisë dhe dishepujt e shën"},{"t":"h","x":"Kirilit dhe Metodit: Gorazdi, Naumi, Angjelari, Sava"},{"t":"p","x":"Shën Klementi lindi më 840 dhe ka mundësi të ketë qenë me origjinë sllave. Shumë shpejt u bë nxënës i shën Metodit (11 maj). U përpoq që gjatë gjithë jetës të imitonte mësuesin e tij. Kur shën Metodi fjeti, armiku i tij i betuar episkopi Uiking, mori tërbim kundër dishepujve të tij, sepse mësimi i tyre po depërtonte në popull dhe e detyronte atë të largohej nga ndikimi frank. Ai i denoncoi tek Svatopluku, duke i akuzuar si magjistarë. Klementi dhe Gorazi i shpjeguan princit se nuk dëshironin të revoltoheshin kundër autoritetit të tij por të mbrojnë dogmën orthodhokse të Trinisë së Shenjtë. Princi nuk donte t’ia dinte për argumentet e tyre, ndaj i dha në duart e gjermanëve, të cilët i tërhoqën zvarg nëpër ferra dhe i shitën si skllevër. Kryetarët e misionit bizanti: Gorazdi, Klementi, Naumi (Laurent), Sava dhe Angjelari u burgosën. U liruan nga një tërmet që e shkundi vendin. Por Svatopluku i keqtrajtoi përsëri. Pas tri ditësh, ra një tjetër tërmet, por tirani i pandjeshëm i ndëshkoi shenjtorët, i la në qeli, mbuluar me plagë dhe pa ushqim. Më vonë i dëbuan për në mbretërinë e Moravisë. Klementi, Naumi, Angjelari dhe Sava u drejtuan nga Danubi me shpresën se do të arrinin në Bullgari. Arritën në një fshat dhe u pritën bujarisht nga një njeri, djali i të cilit kishte vdekur para se shenjtorët të mbërrinin. Me lutjet e shenjtorëve fëmija u ngrit. Pasi përshkuan Danubin, arritën në Beograd, ku qeveritari, i informuar se cilët ishin, i çoi pa vonuar shumë në oborrin e carit Boris, i cili i donte njerëzit e Perëndisë. Pas pak kohësh, cari ia besoi Klementit ungjillëzimin e krahinës së Kutmicevicës, të Ohrit dhe të Gllavenicës (885). Falë mbështetjes së autoriteteve lokale, shenjti e përhapi fjalën e Perëndisë në popull dhe mblodhi 3500 dishepuj. I mësoi me alfabetin e zbuluar të shën Kirilit, të cilin e kishte modifikuar dhe në të cilin përktheu shumë libra të Bizantit që Kisha të ndërtohej mbi themele të forta. Kur cari Boris fjeti, biri i tij Simeoni (893-927) pasoi vendin e të atit dhe tregoi të njëjtin zell për ungjillëzimin e popullit. E vlerëzonte shën Klementin dhe e caktoi si episkop të Velicës me juridiksion Maqedoninë perëndimore. Shën Klementi, i pari hierarki me origjinë sllave, u tregua një pasues i denjë i apostujve. Gjatë kësaj periudhe u mor me vazhdimin e përkthimit të librave të shën Kirilit dhe Metodit. Hartoi në gjuhën sllave një seri fjalimesh për festat kryesore të vitit, me qëllim që priftërinjtë t’i lexonin. Përktheu dhe kompozoi Shërbesa të Kishës. Themeloi në Ohër një manastir kushtuar shën Pandelimonit."},{"t":"p","x":"Pas 20 vjet punë apostolike, shë Klementi, në moshë të madhe, i kërkoi carit Simeon t’i jepte leje që ditët e fundit të jetës t’i kalonte në manastirin e Ohrit. Cari u hidhërua për këtë dhe nuk donte ta linte shenjtin të tërhiqej në manastir. Që atëherë, i lumuri u bind dhe nuk foli më për dorëheqje. Në momentin që u kthye në manastir ai u sëmur dhe shën Kirili dhe Metodi i paralajmëruan largimin e tij të ardhshëm nga kjo botë. Fjeti në paqe më 27 korrik 916. shumë shpejt u nderua si apostull i Bullgarisë, të cilën e ungjillëzoi dhe bëri organizimin e parë kishtar të saj. Konsiderohet si një nga themeluesit të letërsisë sllave."}]},{"d":28,"m":7,"blocks":[{"t":"intro","x":"Më 28 të këtij muaji, nderojmë kujtimin e dëshmorëve Prohori, Nikanori, Timoni, Parmeni, dhjakonët e parë (shiko Veprat e Apostujve 6,5)."},{"t":"li","x":"Kujtimin e dëshmorit Juliani nga Dalmacia në shekullin e 2-të."},{"t":"li","x":"Kujtimin e dëshmorit Akaki i ri, i cili u martirizua në Milito të Azisë së Vogël në vitin 308."},{"t":"li","x":"Kujtimin e dëshmorit Efstathi nga Angjira e Azisë së Vogël."},{"t":"li","x":"Kujtimin e dëshmores Dhrosi, të cilën e hodhën në kazan ku tretej ar."},{"t":"li","x":"Kujtimin e oshënares Ireni Krisovalanti, igumene në Manastirin e Krisovalanti në Konstandinopojë në shekullin e 9."},{"t":"li","x":"Kujtimin e oshënarit Pavli i Ksiropotamit, themelues i Manastirit të Ksiropotamit dhe të Shën Pavlit në Malin e Shenjtë."},{"t":"li","x":"Kujtimin e martirit të ri Kristodhuli i Kasandrës."},{"t":"li","x":"Kujtimin e oshënarit Moisi çudibërës nga Lavra e Kievit të Rusisë në shekullin e 13-14."},{"t":"li","x":"Kujtimin e shën Pitirimit, episkop në Tambov."},{"t":"li","x":"Kujtimin e shën Samsonit, episkop i Dolit (në Bretanjë)."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Shën Juliani"},{"t":"p","x":"Në kohën e perandorit Antonin, Shën Juliani shkoi nga Dalmaci te Ilirisë e në Kampnja të Italisë. Ai ishte një djalë i pashëm dhe i ishte kushtuar Zotit me gjithë shpirt. Gjatë rrugës takoi një grup ushtarësh perandorake të cilët ishin në kërkim të të krishterëve. Juliani iu drejtua atyre duke i thënë: “Paqja qoftë me ju vëllezër”. Ushtarët duke dëgjuar një përshëndetje të tillë dhe duke parë kaq mirësi dhe butësi në shprehjen e fytyrës së tij dyshuan se mos ishte i krishterë dhe prandaj e pyetën: “Nga je, çfarë besimi ke?” Djaloshi i ri u përgjigj pa frikë: “Jam një ilir nga Dalmacia dhe besoj më Krishtin”. Dhe për më tepër djaloshi trim shtoi se qëllimi i udhëtimit të tij ishte që të kthente adhuruesit e idhujve në fenë e vërtetë dhe të besonin në Perëndinë e gjallë. Ushtarët kur dëgjuan këto fjalë e rrahën djalin e njomë mizorisht dhe pastaj e hodhën në një pus të thellë. Aty qëndroi shtatë ditë e shtatë net pa asnjë lloj ushqimi. Mbas shtatë ditësh atij iu shfaq një ëngjëll dhe e ushqeu me ushqim qiellor. Kur ushtarët panë se edhe pas kaq kohësh qëndrimi pa bukë ai ishte akoma gjallë e nxorën nga pusi ilirin e ri dhe e çuan në gjyq. Por edhe atje Juliani qëndroi si burrë dhe dëshmoi me forcë besën e tij. Duke parë kurajon, besën dhe trimërinë e tij, 30 vetë nga ata që po dëgjonin gjyqin u kthyen në të krishterë. Gjykatësi e dënoi me vdekje. Kur Juliani dëgjoi vendimin, ra në gjunjë dhe me lot në sy falenderoi Zotin që i dhuroi martirizimin. Pastaj iu lut Atij që t’i mëshironte e t’i shpëtonte të gjithë ata të cilët do të ruanin Kujtimi e tij. Ne fund e çuan tek vendi i ekzekutimit ku i prenë kokën me sëpatë. Shpirti i tij u ngjit në qiell tek Zoti i tij, të cilit i shërbeu me besnikëri."},{"t":"h","x":"Irini e Krisovalantit, oshënare"},{"t":"p","x":"Shën Irini jetoi në Kapadhoqi, në një familje të pasur e fisnike, pas vdekjes së perandorit ikonoklast Theofili (842). Pas qeverisjes së saj, Theodhora kërkoi një vajzë për të birin, perandorin Mikel III (842-8670). Bukuria dhe fisnikëria e Irinit u ra në sy të dërguarve nga oborri perandorak, prandaj u dërgua në Konstandiopojë me motrën e saj, ku do të martohej me diktatorin Bardas, vëllain e Theodhorës. Duke kaluar pranë malit Olimp të Bitinisë shenjtorja vizitoi shën Joaniqin e Madh (4 nëntor), i cili e përshëndeti dhe i paratha se do të bëhej igumene e manastirit të Krisovalantit."},{"t":"p","x":"Përkujdesja hyjnore e pengoi martesën e saj me perandorin dhe me zemër të çliruar e plot gëzim shpërndau gjithë pasurinë që kishte dhe shkoi në manastirin e Krisovalantit, themeluar nga patriku Nikolao pranë rezervuarit Aspar, në një vend me ajër të pastër, larg vendeve publike e me zhurmë. Me qethjen murgërore, e lumura preu çdo lidhje që e mbante me botën dhe filloi me zell përpjekjet asketike, derisa trupi të dobësohet dhe njeriu i brendshëm të ripërtërihet e t’i afrohet Perëndisë. Veshur vetëm me një tunikë që e ndërronte një herë në vit, shenjtorja ushqehej me bukë e ujë dhe nënshtrohej me dëshirë e gëzim në gjithçka, duke urryer kundërshtimin dhe murmuritjen. Pendimi i saj i përhershëm i gëzonte zemrën dhe e bënte të shkëlqente fytyrën e saj, ashtu si një tokë pjellore jepte fryte të bollshme nga virtytet e shenjta. I shikonte të gjitha motrat si mbretëresha dhe e konsideronte veten si shërbëtoren e tyre, duke bërë punë të rëndomta. Goja e saj fliste vetëm fjalët e Shkrimit e të Etërve të Shenjtë dhe meditonte pa pushim. Kur ishte në manastir prej më pak se një viti pasi lexoi me admirim jetën e Shën Arsenit (8 maj), i cili lutej që nga perëndimi i diellit e deri në mëngjes, filloi ta imitonte. Me ndihmën e hirit të Perëndisë arriti pak nga pak të qëndronte në këmbë me duar të shtrira në lutje gjatë ditës dhe natës. Luftoi me një mjet të tillë që të nënshtronte trupin tek vigjilenca e shpirtit, në mënyrë që asnjë tundim i djallit të mos e turbullonte. Kur ky i fundit i sugjeronte kujtimet e lavdisë dhe të madhështisë së jetës që kishte lënë, shenjtja shkonte dhe i rrëfente këto mendime tek igumenia dhe e dyfishonte asketizmin. Kur igumenia fjeti, ajo u zgjodh në vend të saj dhe u dorëzua nga patriku Shën Metodi (14 qershor). Kujtoi atëherë profecinë e shën Joaniqit dhe pasi vlerësoi detyrën e saj që të mos kërkonte atë që i pëlqente, por “të mbante barrët e më të dobtëve” (Rom.15:1), jetoi që atëherë si engjëll në tokë duke shtuar agjërimet, duke u lutur gjatë gjithë natës dhe duke bërë metani të panumërta. Me këto mjete tërhoqi tek vetja mëshirën e Perëndisë dhe mori një urtësi të tillë, saqë mundi të drejtonte shumë shpirtra në rrugën e shpëtimit. U kërkoi motrave të mos e konsideronin si kryetaren e tyre, por si një nga motrat që do t’u shërbente atyre. Me butësi dhe durim i nxiste të jetonin çdo gjë me frymën e Ungjillit. Duke përbuzur çdo tërheqje të kotë të lavdisë dhe vlerësimin e njerëzve, që të mos e kishin mohuar botën vetëm në dukje, ato duhet të ruanin jo vetëm pastërtinë, por edhe butësinë, virtytet më të larta për natyrën, të cilat jepen nga Krishti për ata që e lusin me besë. Çdo arritje që ato kishin, shenjtja i këshillonte që ta konsideronin si një dhuratë nga Perëndia dhe të qëndronin në frymën e pendimit dhe në veprimin e përhershëm të hirit. I ndalonte të luteshin për shëndetin e tyre, sepse asgjë nuk ishte më e vlefshme për shpirtin, sesa sëmundja e pranuar me mirënjohje. Pasi mori nga një engjëll dhuratën e largpamësisë, shenjtja ishte si një profete për manastirin e saj. Çlodhej pak pas shërbesës së mëngjesit, i thërriste motrat një nga një dhe me art e dallueshmëri i ndihmonte të paraqiteshin të pastra dhe pa shtirje para Perëndisë duke iu zbuluar dhe mendimet më të fshehta. Shumë shpejt u bë e njohur në qytet për virtytet dhe urtësinë e saj, me të cilën drejtonte komunitetin dhe çdo njeri të pasur a të varfër, të shtresës së ulët apo fisnike, që vinte për të marrë këshillat dhe lutjet e saj. Tek të gjithë mësonte domosdoshmërinë e pendimit dhe të kthimit në çdo çast tek Perëndia i mëshirshëm. Plot hir përparonte në asketizëm dhe lutjen e pastër. Gjatë Kreshmës së Madhe deri për Pashkë, ajo hante vetëm bukë dhe një herë në javë pak perime. Vigjilenca gjatë natës ishte bërë për të shumë natyrale, si gjumi për njerëzit e tjerë dhe e kalonte natën me duar të shtrira drejt qiellit e absorbuar nga meditime të shenjta. Qëndronte në këtë pozicion ndonjëherë edhe dy ditë, madje ndodhi edhe një javë, derisa një nga motrat erdhi e i uli duart e saj të lartësuara drejt qiellit. Një natë, një murgeshë e pa në oborr shën Irinin duke u lutur, qëndronte lart nga toka dhe dy qiparisa të mëdhenj që ishin brenda manastirit, kishin përkulur majën e tyre deri në tokë dhe u drejtuan vetëm atëherë kur u bëri shenjën e kryqit. Kjo lutje natën ishte e tmerrshme për demonët, të cilët i dyfishuan sulmet. Një mbrëmje, një prej tyre hodhi mbi shenjtoren fitilin e ndezur të një kandili. Veshja e saj mori flakë menjëherë. Por ajo qëndroi e palëkundur dhe do të digjej e tëra në qoftë se një murgeshë, e cila u zgjua nga era e mishit dhe e rrobave të djegura, nuk do të kishte hyrë në qelinë e saj duke shqyer derën. Në mes të tymit të dendur, me habi ajo pa mes flakëve shenjtoren duke u lutur në këmbë. Duke u përpjekur të shuante flakët, shën Irini uli krahët dhe i tha me një ton qortues: “Përse më keni privuar nga kjo kënaqësi me ardhjen tuaj në kohë të papërshtatshme? Një engjëll qëndronte para meje dhe ishte duke vënë mbi kokën time një kurorë me lule të paprishura, saqë syri nuk i ka parë ndonjëherë dhe ai ishte gati të më merrte kur ti hyre”. Ndërsa nxënësja e saj shkuli pjesët e copës së ngjitur në trup, një parfum me erë të mrekullueshme mbushi gjithë manastirin. Një herë tjetër, një lundrues i ardhur nga Patmos mbërriti në manastir dhe i dha shenjtores 3 mollë të shijshme, që ia kishte dhënë shën Joani. E lumura u ushqye me mollën e parë për 40 ditë dhe gjatë kësaj kohe prej gojës së saj dilte një aromë e këndshme, mollën e dytë ia ndau vëllazërisë të Enjten e Madhe dhe mollën e tretë e ruaji si një thesar të çmuar, si një dëshmi të të mirave të Parajsës. Falë hirit të saj profetik, shën Irini bëri një numër të madh çudish dhe parashikoi vrasjen e Bardas të pasuar nga ajo e Mikelit III (867), gjithashtu edhe ardhjen në pushtet të Vasilit të Maqedonisë. Me ndihmën e shën Vasilit të Madh e të shën Anastasisë Farmakolitria, e lumura shëroi të demonizuar dhe shpëtoi një nga prindërit e saj, që perandori mendonte ta ekzekutonte për tradhti. Perandori Vasil kuptoi gabimin dhe kërkoi të falur, më pas tregoi tërë dashamirësinë e tij për manastirin. Shën Irini edhe në moshë të thyer, 103 vjeç, ruante gjithë freskinë dhe bukurinë fizike, shenjë kjo e bukurisë së shpirtit. Një vit më përpara, engjëlli i saj mbrojtës i lajmëroi datën e saktë të fjetjes. Kur kjo ditë erdhi, ajo mblodhi motrat emëroi igumenen e re dhe pasi i nxiti që të përbuznin gjithçka kalimtare në këtë jetë për të jetuar me Dhëndrin e shpirtit, mbylli sytë qetësisht duke e dorëzoi shpirtin tek Zoti. E varrosën në kishën e shën Theodhorit. Nga varri i saj del një erë e mirë, e cila dëshmon për pëlqimin që kishte marrë nga Perëndia dhe deri në ditët tona shën Irini e Krisovalantit nuk ka pushuar së ndërmjetuari për ata që e lusin më besë."},{"t":"h","x":"Prohori, Nikanori, Timoni, Parmenasi, dhjakonë"},{"t":"p","x":"Prej të shtatëdhjetë apostujve (4 janar). Për arsye anoma-lie gjatë “agapeve (= dashurive)” domethënë darkave të përbashkëta të Kishës së parë, dymbëdhjetë apostujt kërkuan dhe besimtarët zgjodhën 7 burra frymëmbajtës. Të zgjedhurit u hirotonisën prej apostujve dhe morën në ngarkim kujdesin e darkave dhe kështu ata u çliruan për t’iu përkushtuar lutjes dhe predikimit. Pra u treguan dhjakonë që të katër që festojmë sot dhe gjithashtu dëshmori i parë Stefan (27 dhjetor), Filipi (11 tetor) dhe Nikola (Vepra 6.1-6). I fundit nuk nderohet si shenjtor, sepse sipas mendimit të Etërve më të shumtë ishte krijuesi i herezisë së shëmtuar dhe imorale të Nikolaitëve (shih Apok. 2.14-15). Megjithatë ekziston dhe mendimi se ai vetë bëri një jetë të pastër, por pasuesit e tij e keqinterpretuan një frazë të tij dhe rrëshqitën... Dhjakonët më vonë iu përkushtuan gjithashtu misionarizmit. Tradita na informon për këta të katërt:"},{"t":"p","x":"Prohori ndihmoi Joan Theologun (26 shtator), vuajtën së bashku dhe sipas diktimit të tij shkroi Apokalipsin. Mbas jetëndërrimit të Theologut shërbeu si episkop i Nikomedisë në brigjet aziatike të Propondidhës, ku u preh pas një baritorie rezultative."},{"t":"p","x":"Nikanori fjeti në paqe të njëjtën ditë që u martirizua Stefani, megjithëse Veprat nuk e përmendin."},{"t":"p","x":"Timoni u bë prej apostujve episkop i Vostroneve të Arabisë. Meqë atje u përpoq ashpër dhe bëri shumë të krishte-rë, u rrah prej idhujtarëve dhe u dogj në zjarr."},{"t":"p","x":"Në fund Parmenasi, mbasi i shërbeu perëndishëm vëllezërve, u sëmur dhe dha frymë përpara apostujve, të cilët dhe e varrosën."}]},{"d":29,"m":7,"blocks":[{"t":"intro","x":"Më 29 të këtij muaji, nderojmë kujtimin e dëshmorit Kaliniku nga Kilikia; që u martirizua në Gangra në shekullin e 3-të."},{"t":"li","x":"Kujtimin e martires së shenjtë Theodhota dhe tre fëmijët e saj."},{"t":"li","x":"Kujtimin e dëshmorit Mamas."},{"t":"li","x":"Kujtimin e dëshmorit Vasilisku plak."},{"t":"li","x":"Kujtimin e oshënarëve Benjamini dhe Beri."},{"t":"li","x":"Kujtimin e dëshmores dhe virgjëreshës Serafima nga Antiokia; që u martirizua në shekullin e 2-të."},{"t":"li","x":"Kujtimin e dëshmorit Joani ushtar në kohën e mbretit pagan Juliani; u martirizua në vitin 363."},{"t":"p","x":"-Kujtimin e Theodhosit të ri, perandor shpresëtar i Konstandinopojës në vitet 408-450."},{"t":"li","x":"Kujtimin e dëshmorit Efstathi nga Mçeti i Ivirisë; u martirizua në vitin 589."},{"t":"li","x":"Kujtimin e atit tonë Konstandini III Likudhi, patriark i Konstandinopojës në vitet 1059-1063."},{"t":"li","x":"Kujtimin e shën Romanit, igumen i Manastirit të Kirjaçit."},{"t":"li","x":"Kujtimin e shën Konstandinit dhe Kozmait në Kosin."},{"t":"li","x":"Kujtimin e shën Bogolepit të Çerni-Jar, fëmijë që u bë murg me skimë të madhe."},{"t":"li","x":"Kujtimin e shën Efstathit të Mtsketa në Gjeorgji."},{"t":"li","x":"Kujtimin e shën Lupit, episkop i Trojës, shek. 5-të."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Theodhota dhe të tre fëmijët e saj"},{"t":"p","x":"U atletizuan (martirizuan) në kohë të Dioklitianit (284-305) në atdheun e tyre, Nike të Vithinisë, në veriperëndim të Azisë së Vogël."},{"t":"p","x":"Theodhota shkoi dhe u përkushtua në shën Anastasia Farmakolitria (22 dhjetor) që ndodhej atje, sepse u tërhoq prej famës së saj."},{"t":"p","x":"Më parë Dioklitiani për hir të paraqitjes trupore dhe shpirtit madhor të saj e destinoi për grua të arkondit Lefkadhit me shpresë që ai ta tërhiqte në idhujtari - duhej të ishte e ve. Theodhota refuzoi propozimin, por Lefkadhi këmbëngulte."},{"t":"p","x":"Që të fitonte kohë i kërkoi të priste pak, kështu gjeti rastin gjatë mungesës së tij dhe për pak ditë shoqëronte Anastasinë në burg. Atje i japnin kurajo të krishterëve në pranga."},{"t":"p","x":"Lefkadhi, përderisa nuk arriti ta bindi Theodhotën as me brutalitet, e dërgoi tek qeveritari i Vithinisë, i cili e torturoi me shumë mënyra. Për ta përkulur përdori fëmijët e saj. I kërcënoi me vdekje në qoftë se nuk iu faleshin perëndive. Më i madhi, Evodhi ia mbylli gojën me mençuri burrit, saqë qeveritari e rrahu egërsisht që të vuante e ëma."},{"t":"p","x":"Megjithatë trimëresha gëzohej dhe i jepte zemër. Ia do-rëzoi atëherë shenjtoren një të pamoralshmi që ta poshtëronte, por porsa ai vuri dorë mbi të hëngri një dackë të tillë nga një qenie dritëmbartëse, aq sa nga hunda i rrodhi gjak si çezëm."},{"t":"p","x":"Tirani i pamençur e kërcënoi se do t’i therrte fidanët. I ktheu përgjigjen se këtë dëshironte: T’i përcillte tek Zoti sa ishte gjallë dhe pastaj t’i pasonte ata. Qeveritari duke dalë menç urdhëron t’i djegin në furrë që të katër, që mbaruan të gëzuar."},{"t":"p","x":"Më vonë shenjtorja i shfaqej netëve të burgosurës Anastasi dhe i jepte fuqi. Gjithashtu mbajti varkën, në të cilën kishin hipur Farmakolitrian së bashku me të tjerë, të cilën e kishin shpuar për ta mbytur dhe e drejtoi deri në breg."},{"t":"p","x":"Katërshja familjare kremtohen edhe së bashku me shën Anastasinë më 22 dhjetor."},{"t":"p","x":"Theodhota, greqisht përkthehet e dhënë nga Perëndia, ndërsa Evodhi përkthehet udhë e mbarë. Nuk referohen emrat e dy vëllezërve të tjerë."},{"t":"h","x":"Joan ushtari"},{"t":"p","x":"Shën Joani shërbente në ushtrinë romake, në kohortën e Taifalëve, nën mbretërimin e Julian Apostatit (361-363). U dërgua me ushtarë të tjerë për të persekutuar të krishterët, u shtir se do ta plotësonte këtë punë, por fshehurazi ndihmonte të burgosurit e i ndihmonte të arratiseshin. Jetën e tij e kaloi në kreshmë e në lutje, mëshironte të hidhëruarit, u jepte lëmoshë të varfërve, vizitonte të sëmurët e të shtypurit dhe mundësoi përmirësimin e kushteve të të jetuarit. Pasi kaloi jetën në vepra të pëlqyera nga Perëndia, me gjithë detyrat e përgjegjësitë që kishte, fjeti në paqe e u varros në vendin e quajtur Pandekt, në një varr të ruajtur për të huajt. (Ka mundësi në Konstandinopojë. Trupi i tij nderohet në kishën e Shën Sofisë, pranë shën Sofisë). Pas pak kohësh, iu shfaq në vizion një gruaje duke i zbuluar emrin e tij si dhe veprat që ai kishte bërë gjatë jetës. Kreu edhe shumë mrekulli të tjera pas fjetjes së tij ndaj skllevërve që donin të arratiseshin nga zotërinjtë e tyre. Paratha pushtime dhe zbuloi hajdutë. Ky shenjtor thirret në lutje për gjetjen e hajdutëve."}]},{"d":30,"m":7,"blocks":[{"t":"intro","x":"Më 30 të këtij muaji, nderojmë kujtimin e apostujve Sila, Siluani, Epeneti, Kreshendi dhe Androniku nga të 70-t."},{"t":"li","x":"Kujtimin e dëshmores Julita, e cila u martirizua në Kapadhoqi të Qesarisë në vitin 303."},{"t":"li","x":"Kujtimin e shën Pavlit, episkop, dhe Joani prift."},{"t":"li","x":"Kujtimin e daljes së lipsanit të shën Gjermanit nga Solovski i Rusisë."},{"t":"li","x":"Kujtimin e shën Angjelinës, princesha e Serbisë."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Shën Angjelina"},{"t":"p","x":"Ishte e bija e princit shqiptar Gjergj Arianitit dhe motra e Donikës, gruas së Gjergj Kastriotit. Angjelina u martua me despotin e Serbisë, Stefan Brankoviçin dhe lindën dy fëmijë, Maksimin dhe Joanin. Mbas vdekjes së Stefanit, Angjelina u vesh murgeshë në Manastirin e Krushedolit, duke ia përkushtuar jetën lutjeve dhe veprave bamirëse saqë populli e thërriste \"Nënë Angjelina\". Fjeti në fillimet e shekullit të XVI-të në Manastirin e Krushedolit, ku ruhen edhe sot lipsanet e saj mrekullibërës. Kisha e kanonizoi shenjtore dhe e nderon Kujtimi e saj më 30 korrik."},{"t":"h","x":"Julita nga Qesaria"},{"t":"p","x":"E lavdëroi kryepiskopi i qytetit të saj, Vasili i Madh (1 janar). Ishte e krishterë shpresëtare në gjendje shumë të mirë ekonomike. Dikur denoncoi në publik një zaptues arrogant që duke përdorur shpifje dhe gënjeshtra, duke paguar rryshfete dhe duke bërë për vete dëshmitarë të rremë, kishte përvetësuar shumicën e skllevërve, të fushave, të kafshëve dhe të të mirave materiale të saj."},{"t":"p","x":"Tamhaqari i paskrupullt dhe mashtrues që nuk stepej përpara asgjëje, bën plan që t’i mbyllë gojën njëherë e për-gjithmonë protestueses për bërjen pluhur të pasurisë së saj. Pra i bëri denoncim si kundërshtuese të perëndive, që për këtë nuk ishte e hijshme të disponoje pasuri të patundshme - ose të drejta shtetërore sipas një versioni tjetër."},{"t":"p","x":"Atëherë u tërhoq në gjykatë, ku pa vonesë mohoi çdo lavdi dhe pasuri dhe komoditet, për të mos devijuar nga e Vërteta. Kështu qeveritari e hodhi në furrë, por flakët u çanë duke formuar një bark si kamare, si një dhomë vezulluese! Brenda këtij prehri të paparë dha frymën, megjithëse trupi nuk iu cënua aspak, që ta kenë ngazëllim dhe frymëzim dhe shërim të afërmit e saj si dhe besimtarët."}]},{"d":31,"m":7,"blocks":[{"t":"intro","x":"Më 31 të këtij muaji, nderojmë kujtimin e të drejtit Evdhokimi nga Kapadhoqia, në shekullin e 9."},{"t":"li","x":"Kujtimin e shën Josifit nga Arimathea, i cili varrosi Trupin e Shenjtë të Zotit tonë Jisu Krisht."},{"t":"li","x":"Kujtimin e Inagurimit të kishës së Shën Marisë në Vllahernë të Konstandinopojës në vitin 450."},{"t":"li","x":"Kujtimin e 12 martirëve romakë që vdiqën me shpatë."},{"t":"li","x":"Kujtimin e Demokritit, Sekondit dhe Denisit të Sinadhës së Frigjisë."},{"t":"li","x":"Kujtimin e Joan eksarkut."},{"t":"li","x":"Kujtimin e shën Gjermanit, episkop i Aukserës."},{"t":"end","x":"Me ndërmjetimet e shenjtorëve të tu, o Krisht Perëndi, mëshirona. Amin."},{"t":"h","x":"Shën Josifi"},{"t":"p","x":"Kishte një pozitë të lartë shoqërore dhe i përkiste asaj kategorie njerzish të cilët prisnin me shpresë të fshehur mbretërinë e Perëndisë. Lidhur me këtë ungjillori Joan shkruan: “Josifi nga Arimathea ishte dishepull i Isuit, por fshehtas, nga frika e judenjve, i kërkoi Pilatit të merrte trupin e Isuit”. Në momentin kur nxënësit të fiksuar dhe të dëshpëruar nga kryqëzimi i mësonjësit të tyre ishin mbyllur brenda në shtëpi, Josifi guxoi dhe i kërkoi Pilatit që të merrte trupin e Krishtit. Brenda tij u zgjua dëshira per t`i bere nderet më të mëdha mësuesit të tij të cilit nuk kishte guximin t’i shërbente kur Ai ishte gjallë. Kryqi në vend që ta frikësonte e armatosi me guxim."},{"t":"p","x":"Sot pas 20 shekujsh është e vështirë të kuptojmë se çfarë guximi nevojitej për të marrë parasysh pasojat që kishte ky veprim. Josifi nga Arimatea e dinte se sa e rëndë mund të ishte për të akuza e një të dënuari dhe se ndoshta do ta paguante me jetën e tij këtë guxim. Megjithatë ai mbeti në histori për guximin që pati për marrjen e trupit të Isuit. Që nga ajo kohë e gjer më sot një guxim i tillë u shkruajt dhe vazhdon të shkruhet në faqet më të bukura të historisë mbarënjerzore."},{"t":"h","x":"Evdhokimi i Drejtë"},{"t":"p","x":"Ishte fëmijë i patricit Vasil dhe Evdhokisë nga Kapadhoqia, shpresëtarë dhe të pasur. U arsimua seriozisht në Konstandinopojë ku jetonin familjarisht. Perandori Theofil (829-842) e nderoi me gradë të lartë, e caktoi komandat të ushtrisë në Kapadhoqi."},{"t":"p","x":"Atje që herët, perëndidashësi i ri u tregua mbrojtës i të vobektëve: “Më tepër zell ai kishte të jepte se sa ata që kërkonin për të marrë”. Jetonte brenda një ambienti shumë komod, me luks dhe me shumë njerëz dhe e presiononin dety-rime të mëdha, pra dhe shpërqëndrime. Megjithë këto fitoi sidomos pastërti dhe dëlirësi të lartë morale, të rrallë edhe tek heremitët. Për shembull kishte vënë si rregull që të mos shohë asnjëherë fytyrë gruaje!"},{"t":"p","x":"I Drejti, siç u quajt për hir të drejtësisë dhe virtytit të tij shumë të lartë, u sëmur dhe u preh 33 vjeç më 31-7-840. Më përpara i ishte lutur njerëzve dhe Zotit të mos e nderojnë pas vdekjes. Ndërsa njerëzit e varrosën thjesht, i Larti tregoi varrin, dheun dhe kandilen e tij kuruese për të demonizuarit dhe të sëmurët."},{"t":"p","x":"Fama e Evdhokimit - i cili është një prej të paktëve oshë-narë jo murgj arriti shpejt deri në kryeqytet. Solli edhe nënën e tij që vajtonte për privimin e birit të saj, por edhe lumturonte veten e saj, duke u mburrur si një nënë shenjtori! Mbas porosisë së saj u hap varri, atëherë trupi që aromatizonte, u duk i pacënuar megjithëse kishin kaluar 18 muaj. Madje qëndroi drejt, kur e ngriti një hieromonak dhe i ndërroi rrobat e varfra për t’i mbajtur si bekim. Vendasit nuk i lejuan patricisë që ta merrte në vendin tyre bashkë me të. Por më vonë, i njëjti klerik e mori fsheurazi dhe e çoi tek prindërit e oshënarit në kryeqytet megjithëse edhe në rrugë tradhtohej prej miros që pikonte dhe mrekullive që kryente. Pikërisht ky transferim kremtohet më 6 korrik."},{"t":"p","x":"Evdhokimi, greqisht përkthehet i suksesshëm."},{"t":"h","x":"G U S H T"}]}]};
